/* Generated by tools/build.py from templates/*.json - do not edit by hand. */
window.SIGNOFF_TEMPLATES = [{"id":"requirements","title":"Requirements & Concept","short":"Concept","version":2,"description":"Concept-phase review of product requirements, interfaces, loads, regulatory scope, manufacturing and cost targets, risks, serviceability, ID handshake, electronics integration and battery constraints.","sections":[{"id":"rq-prd","title":"Product Requirements & Use Cases","tags":[],"items":[{"id":"rq-prd-1","text":"Every mechanical requirement traces to a numbered line in the PRD or customer specification","hint":"Keep a requirements matrix with PRD reference, ME requirement, verification method and owner. Requirements without a source tend to be argued about at DVT.","tags":[],"severity":"major"},{"id":"rq-prd-2","text":"Each requirement is quantified with a value, unit and tolerance or limit","hint":"\"Rugged\" or \"compact\" is not verifiable; rewrite as e.g. drop height in m, envelope in mm, mass in g. If the customer can't give a number, record the assumed value and get it approved.","tags":[],"severity":"major"},{"id":"rq-prd-3","text":"Each requirement has a defined verification method (test, analysis, inspection or demonstration)","hint":"Fill the verification column of the requirements matrix now; it becomes the skeleton of the design verification plan.","tags":[],"severity":"major"},{"id":"rq-prd-4","text":"Intended use and reasonably foreseeable misuse cases are written down","hint":"List how users will actually handle it: dropped off a bench, sat on, used as a step, cleaned with solvent. Misuse cases drive loads and safety requirements.","tags":[],"severity":"major"},{"id":"rq-prd-5","text":"Use environment is defined: indoor/outdoor, operating and storage temperature range, humidity, altitude","hint":"State operating and storage ranges separately in °C and %RH. Storage and transport extremes (e.g. a closed vehicle in summer) often exceed operating conditions.","tags":[],"severity":"major"},{"id":"rq-prd-6","text":"Product life and duty cycle are specified in years and in use cycles","hint":"E.g. 5 years at 20 uses per day gives the cycle count for hinges, buttons, latches and connectors. Without it there is no basis for life testing.","tags":[],"severity":"major"},{"id":"rq-prd-7","text":"Target user population is defined, including size range, strength and dexterity limits","hint":"Grip size, actuation forces and reach depend on who uses it (children, elderly, gloved hands). Reference anthropometric data rather than the design team's own hands.","tags":[],"severity":"major"},{"id":"rq-prd-8","text":"Packaging, shipping and installation conditions are captured as requirements","hint":"Transit drop, stacking load and vibration often govern the design more than use. Note whether the product ships assembled, in retail packaging or bulk.","tags":[],"severity":"major"},{"id":"rq-prd-9","text":"Product mass target is set, with an allocation by subsystem","hint":"Track mass in a budget spreadsheet updated from CAD mass properties with correct material densities. Mass growth is easier to stop early than to remove later.","tags":[],"severity":"minor"},{"id":"rq-prd-10","text":"Requirements baseline is under revision control and changes go through a documented approval","hint":"A dated, versioned requirements document with a change log stops scope creep from silently invalidating completed design work.","tags":[],"severity":"minor"}]},{"id":"rq-env","title":"Interfaces & Envelope","tags":[],"items":[{"id":"rq-env-1","text":"Space claim (maximum envelope) is defined in CAD and agreed with the customer and other disciplines","hint":"Publish a space-claim model with locked outer boundaries. Check the current design against it with an interference or clearance check.","tags":[],"severity":"critical"},{"id":"rq-env-2","text":"Every mating product or accessory interface is identified with its controlling drawing or model","hint":"Docks, chargers, mounts, cartridges and third-party parts each need a reference model at a known revision. Designing to a photo or a competitor sample is how mismatches happen.","tags":[],"severity":"critical"},{"id":"rq-env-3","text":"Interface tolerances of mating third-party parts are known, not assumed from nominal CAD","hint":"Get the supplier drawing with tolerances; vendor STEP files are usually nominal. Feed worst-case values into the stack-ups (see Tolerancing & GD&T).","tags":[],"severity":"major"},{"id":"rq-env-4","text":"Mounting method and mounting points to the customer's system are defined","hint":"Specify hole pattern, fastener type, mounting surface and load direction. Confirm the customer's mounting surface flatness and material.","tags":[],"severity":"major"},{"id":"rq-env-5","text":"Connector and I/O access locations are agreed with EE and match cable and plug clearances","hint":"Check plug overmold dimensions and cable bend radius at each port, including right-angle and oversized aftermarket plugs, not just the receptacle.","tags":["electronics"],"severity":"major"},{"id":"rq-env-6","text":"User interface locations (buttons, displays, indicators) are fixed relative to the envelope","hint":"Lock UI positions early; moving a button after PCB layout costs a board spin and a tooling change.","tags":[],"severity":"major"},{"id":"rq-env-7","text":"Access requirements for installation, cable connection and maintenance are defined","hint":"Check hand and tool access with a human model or simple clearance volumes in CAD, including fastener driver length.","tags":[],"severity":"minor"},{"id":"rq-env-8","text":"Orientation, mounting position and gravity direction in use are defined","hint":"Drainage, venting, cable entry and load paths all depend on which way up the product sits or hangs.","tags":[],"severity":"minor"}]},{"id":"rq-load","title":"Environmental & Mechanical Loads","tags":[],"items":[{"id":"rq-load-1","text":"Drop requirement is defined: height, surface, orientations and number of drops","hint":"E.g. height in m onto concrete or steel, faces/edges/corners, in or out of packaging. Get the spec from the customer or the applicable product standard.","tags":["handheld"],"severity":"major"},{"id":"rq-load-2","text":"Vibration requirement is defined as a profile (frequency range, level, duration, axes)","hint":"Use a transport or application profile from the customer or a recognized standard rather than an invented sine sweep. Note whether the product is powered during vibration.","tags":[],"severity":"major"},{"id":"rq-load-3","text":"Mechanical shock requirement is defined (pulse shape, peak acceleration, duration)","hint":"Shock levels often come from the end application (vehicle, machinery, shipping). Record the source of the numbers.","tags":[],"severity":"major"},{"id":"rq-load-4","text":"Static and user loads are quantified with direction and point of application","hint":"Include lean, sit, step and pull-on-cable loads as relevant. State whether a safety factor is applied and what it is.","tags":[],"severity":"major"},{"id":"rq-load-5","text":"Impact requirement for exposed surfaces is defined where the product could be struck","hint":"Specify energy in J and the impactor (ball, hammer). Displays, windows and thin cosmetic walls are the usual weak points.","tags":[],"severity":"minor"},{"id":"rq-load-6","text":"Chemical exposure list is defined: cleaners, disinfectants, oils, fuels, sunscreen, sweat","hint":"Name actual products and concentrations; they drive material selection and chemical resistance testing. Plastics like PC and ABS can stress-crack under common cleaners.","tags":[],"severity":"major"},{"id":"rq-load-7","text":"UV and weathering exposure is specified, including expected outdoor hours or years","hint":"Defines UV stabilization, colorfastness and material choice. Indoor-only grades fade and embrittle outdoors.","tags":["outdoor"],"severity":"major"},{"id":"rq-load-8","text":"Corrosion environment is defined (salt spray, coastal, industrial, condensation)","hint":"Drives plating, coating, fastener material and galvanic-pair choices.","tags":["outdoor"],"severity":"major"},{"id":"rq-load-9","text":"Water and dust exposure is captured as a target IP rating or ingress scenario","hint":"Record the IP code per IEC 60529 or a plain-language scenario (rain, hose, immersion depth in m). Sealing design itself is covered in Enclosures, Sealing & IP.","tags":[],"severity":"major"},{"id":"rq-load-10","text":"Grip, carry and one-handed use requirements are defined","hint":"Specify mass limit, grip diameter range and whether use with gloves is required. Validate with foam or printed ergonomic models early.","tags":["handheld"],"severity":"minor"}]},{"id":"rq-reg","title":"Regulatory & Standards Identification","tags":[],"items":[{"id":"rq-reg-1","text":"Target markets and sales regions are listed","hint":"Region drives which certifications, marks and material restrictions apply. Adding a region late can force redesign.","tags":[],"severity":"major"},{"id":"rq-reg-2","text":"Applicable product safety standards are identified and owned","hint":"E.g. IEC 62368-1 for ICT/AV equipment, IEC 61010-1 for lab and measurement equipment. Confirm with the test lab or compliance consultant, not by guess.","tags":["regulatory"],"severity":"critical"},{"id":"rq-reg-3","text":"Mechanical requirements of the safety standard are extracted into the requirements matrix","hint":"Enclosure strength, impact, stability, flammability rating (UL 94) and accessible-part requirements need to be design inputs, not test-day surprises.","tags":["regulatory"],"severity":"major"},{"id":"rq-reg-4","text":"Material compliance requirements (RoHS, REACH, Prop 65 and similar) are flagged for all parts","hint":"Capture them as requirements so suppliers are asked for declarations at sourcing, not after tooling.","tags":[],"severity":"major"},{"id":"rq-reg-5","text":"Medical device classification and regulatory pathway are identified","hint":"Class and pathway determine design control rigor, documentation and testing. Get regulatory affairs sign-off.","tags":["medical"],"severity":"critical"},{"id":"rq-reg-6","text":"Applicable medical standards are listed (e.g. IEC 60601-1, ISO 14971, ISO 10993)","hint":"List the specific parts and collateral standards applicable; each brings mechanical requirements such as stability, cleaning and biocompatibility.","tags":["medical"],"severity":"major"},{"id":"rq-reg-7","text":"Design control process (design inputs, reviews, traceability) is set up per the quality system","hint":"Under ISO 13485, design inputs must be documented and reviewed. Retrofitting traceability at the end is painful and audit-visible.","tags":["medical"],"severity":"major"},{"id":"rq-reg-8","text":"Skin-contact materials and contact duration are identified for biocompatibility evaluation","hint":"List every part touching skin, contact type and duration. This drives ISO 10993 testing scope and material choice.","tags":["wearable","medical"],"severity":"major"},{"id":"rq-reg-9","text":"Labeling and marking requirements (rating label, symbols, regulatory marks) are captured","hint":"Reserve label area in the design and note whether marking is molded, printed or a label, and its durability requirement.","tags":[],"severity":"minor"}]},{"id":"rq-mfg","title":"Manufacturing & Cost Targets","tags":[],"items":[{"id":"rq-mfg-1","text":"Annual volume and lifetime volume forecasts are documented","hint":"Volume determines process choice, tooling investment and cavitation. Get the forecast in writing with ramp assumptions.","tags":[],"severity":"critical"},{"id":"rq-mfg-2","text":"Target product cost (BOM plus assembly) is set and allocated by subsystem","hint":"Track estimated cost against the target in a cost model updated at each review.","tags":[],"severity":"major"},{"id":"rq-mfg-3","text":"Tooling and NRE budget is defined","hint":"Tooling budget limits cavitation, steel choice and number of slides. Know it before the part design commits to them.","tags":[],"severity":"major"},{"id":"rq-mfg-4","text":"Manufacturing process for each major part is selected with a written rationale","hint":"Record why injection molding vs. machining vs. sheet metal vs. additive, given volume, cost, tolerance and lead time. Revisit if volume changes.","tags":[],"severity":"major"},{"id":"rq-mfg-5","text":"Process selection is consistent with forecast volume and cost targets","hint":"Rule of thumb: machined or printed parts that suit pilot volumes rarely meet volume cost targets; plan the transition and its tooling lead time.","tags":[],"severity":"major"},{"id":"rq-mfg-6","text":"Tooling lead times and their place in the schedule are confirmed with suppliers","hint":"Get quoted lead times for tools, T1 samples and modifications. Tooling is often the critical path to PVT.","tags":["high-volume"],"severity":"major"},{"id":"rq-mfg-7","text":"Supplier strategy is defined: single vs. dual source, region, and assembly location","hint":"Decide early whether parts are sourced near the final assembly site; it affects logistics, cost and supplier DFM input.","tags":[],"severity":"minor"},{"id":"rq-mfg-8","text":"Key suppliers are engaged for DFM input before design freeze","hint":"Early molder, fabricator or machinist feedback avoids expensive tooling changes.","tags":[],"severity":"major"},{"id":"rq-mfg-9","text":"Assembly location and assembly method (manual, semi-automated, automated) are assumed and documented","hint":"Automated assembly imposes stricter part presentation and tolerance needs. See Assembly, Fastening & DFA.","tags":["high-volume"],"severity":"minor"},{"id":"rq-mfg-10","text":"Production test and inspection strategy is outlined, including end-of-line tests","hint":"Decide what is inspected at the supplier vs. at assembly and what fixtures are needed; fixtures have their own lead time.","tags":["high-volume"],"severity":"minor"}]},{"id":"rq-risk","title":"Concept Risk Review","tags":[],"items":[{"id":"rq-risk-1","text":"A technical risk register exists with owner, likelihood, impact and mitigation for each risk","hint":"Review it at every design review. Risks without owners don't get mitigated.","tags":[],"severity":"major"},{"id":"rq-risk-2","text":"Design FMEA is started at the concept stage for the key functions","hint":"Begin with system-level functions and failure modes; refine as detail design develops. It feeds the verification plan.","tags":[],"severity":"major"},{"id":"rq-risk-3","text":"Hazard analysis or risk management file is started per ISO 14971","hint":"Mechanical hazards (pinch points, sharp edges, instability, ejected parts) need documented risk controls traceable to verification.","tags":["medical"],"severity":"critical"},{"id":"rq-risk-4","text":"Make vs. buy decision is recorded for each major subassembly","hint":"Off-the-shelf mechanisms, hinges, fans and seals often reduce risk; note lead time and obsolescence of bought parts.","tags":[],"severity":"minor"},{"id":"rq-risk-5","text":"IP and freedom-to-operate check is done for the core mechanism or architecture","hint":"Search patents for the key mechanism before investing heavily in detail design; involve counsel if anything close is found.","tags":[],"severity":"major"},{"id":"rq-risk-6","text":"Prior art and competitor products are reviewed and their known failure modes noted","hint":"Teardowns and reviews of competitor field complaints show which problems the design must avoid.","tags":[],"severity":"minor"},{"id":"rq-risk-7","text":"Key technical unknowns are listed with a planned prototype or analysis to answer each","hint":"E.g. mechanism feel, seal compression, thermal margin, drop survival. Prototype the riskiest unknowns first, before the full design.","tags":[],"severity":"critical"},{"id":"rq-risk-8","text":"Critical-to-function features are identified at concept stage","hint":"Naming the CTF dimensions and functions early lets tolerance analysis, drawings and inspection focus on what matters.","tags":[],"severity":"major"},{"id":"rq-risk-9","text":"Safety-critical failure modes and load paths are identified","hint":"Mark parts whose failure could injure someone; they need higher safety factors, analysis and validation.","tags":["structural"],"severity":"critical"},{"id":"rq-risk-10","text":"Concepts are compared against requirements with a documented selection matrix","hint":"Score each concept against weighted requirements and keep the matrix; it explains later why alternatives were rejected.","tags":[],"severity":"minor"}]},{"id":"rq-svc","title":"Serviceability, Repair & End of Life","tags":[],"items":[{"id":"rq-svc-1","text":"Service and repair strategy is defined: field-repairable, depot repair or replace-only","hint":"This decides whether snaps vs. screws, glue vs. gaskets and modular subassemblies are acceptable.","tags":[],"severity":"major"},{"id":"rq-svc-2","text":"Field-replaceable parts and consumables are identified with their access path","hint":"Batteries, filters, seals and wear parts should be reachable without destroying cosmetic parts or seals.","tags":[],"severity":"minor"},{"id":"rq-svc-3","text":"Disassembly for service does not require destroying single-use features unless planned","hint":"Single-use snaps and adhesives are fine for replace-only products but not for repairable ones; record the decision.","tags":[],"severity":"minor"},{"id":"rq-svc-4","text":"Right-to-repair or regional repairability requirements are reviewed for the target markets","hint":"Some regions are introducing repairability and spare-part rules, particularly for batteries; check with compliance.","tags":["regulatory"],"severity":"minor"},{"id":"rq-svc-5","text":"End-of-life and recyclability requirements are defined, including material marking","hint":"Plastics marking per ISO 11469 and separable materials simplify recycling and meet take-back expectations.","tags":[],"severity":"minor"},{"id":"rq-svc-6","text":"Sustainability targets (recycled content, mass, packaging) are captured if the customer has them","hint":"Recycled-content resins have different properties and color limits; capture them as inputs before material selection.","tags":[],"severity":"minor"}]},{"id":"rq-id","title":"Industrial Design & CMF Handshake","tags":["cosmetic"],"items":[{"id":"rq-id-1","text":"Industrial design surfaces are received as a controlled, versioned CAD release","hint":"Engineering should design to a frozen ID surface revision; track which revision each part is built on.","tags":[],"severity":"major"},{"id":"rq-id-2","text":"Class A surfaces are identified and agreed with ID","hint":"Mark which faces are cosmetic and their grade, so gates, ejector pins, sink-prone ribs and parting lines stay off them.","tags":[],"severity":"major"},{"id":"rq-id-3","text":"CMF specification (color, material, finish, texture) is defined for each visible part","hint":"Reference physical color standards or color chips and texture supplier codes, not screen colors.","tags":[],"severity":"major"},{"id":"rq-id-4","text":"Parting line and split line locations are agreed with ID before detailed design","hint":"Parting lines visible on Class A surfaces are a frequent ID/ME conflict; resolve on the concept model.","tags":["injection-molded"],"severity":"major"},{"id":"rq-id-5","text":"Draft required on textured cosmetic surfaces is accounted for in the ID surfaces","hint":"Rule of thumb: heavier textures need more draft per the texture supplier. Adding draft late changes the ID form.","tags":["injection-molded"],"severity":"major"},{"id":"rq-id-6","text":"Gaps, flushness and step targets between visible parts are agreed with ID","hint":"State nominal gap and flush targets in mm; check they are achievable with the tolerance stack.","tags":[],"severity":"minor"},{"id":"rq-id-7","text":"Appearance acceptance criteria (viewing distance, lighting, defect limits) are agreed","hint":"Define cosmetic inspection conditions now so supplier sample approval isn't subjective.","tags":[],"severity":"minor"}]},{"id":"rq-ee","title":"Electronics Integration","tags":["electronics"],"items":[{"id":"rq-ee-1","text":"PCB outline, mounting holes and component height keep-outs are agreed with EE and frozen","hint":"Exchange a STEP/IDF board outline with height zones; check against the enclosure with interference detection.","tags":[],"severity":"critical"},{"id":"rq-ee-2","text":"Antenna keep-out volumes are defined and free of metal, metallized coatings and fasteners","hint":"Get the keep-out from the RF engineer or module datasheet; metal parts, screws and conductive paint nearby detune the antenna.","tags":[],"severity":"major"},{"id":"rq-ee-3","text":"Thermal budget (power dissipation per component and allowable temperatures) is shared with ME","hint":"Get worst-case dissipation in W and limits in °C, including surface touch-temperature limits. Feeds Thermal & Structural Analysis.","tags":["thermal"],"severity":"major"},{"id":"rq-ee-4","text":"Cable and harness routing paths are reserved in CAD with bend radius and connector mating clearance","hint":"Model cables and flex circuits as solids at their minimum bend radius; pinched or over-bent cables are a common field failure.","tags":[],"severity":"major"},{"id":"rq-ee-5","text":"Display, touch and button stack-ups are defined with the EE and supplier","hint":"Include adhesive, gaskets, cover glass and switch travel so actuation force and travel requirements can be met.","tags":[],"severity":"minor"},{"id":"rq-ee-6","text":"Grounding and EMC shielding approach is agreed (conductive coatings, gaskets, chassis bonding)","hint":"Shielding needs contact areas, coating masks and gasket compression in the mechanical design.","tags":[],"severity":"major"},{"id":"rq-ee-7","text":"Electrostatic discharge paths from user-touchable surfaces are considered with EE","hint":"Seams near PCBs and metal trim can let ESD reach electronics; agree creepage and ground paths early.","tags":[],"severity":"minor"}]},{"id":"rq-bat","title":"Battery","tags":["battery-pack"],"items":[{"id":"rq-bat-1","text":"Cell or pack is selected with datasheet dimensions, tolerance and mass","hint":"Use supplier drawings with tolerances, not nominal models; pouch cells vary in thickness.","tags":[],"severity":"major"},{"id":"rq-bat-2","text":"Swelling allowance around pouch or prismatic cells is provided per the cell supplier","hint":"Rule of thumb: leave space for end-of-life swelling as specified by the cell maker. Squeezed cells are a safety and field-return issue.","tags":[],"severity":"critical"},{"id":"rq-bat-3","text":"Transport and shipping rules for the battery (e.g. UN 38.3, air shipping limits) are identified","hint":"Shipping certification needs test samples and lead time; confirm requirements with the cell supplier and logistics.","tags":[],"severity":"major"},{"id":"rq-bat-4","text":"Battery safety standards for the product category are identified","hint":"E.g. IEC 62133 for portable cells and packs. Confirm with the compliance lab.","tags":["regulatory"],"severity":"major"},{"id":"rq-bat-5","text":"Venting path and containment for a cell failure are considered in the concept","hint":"Decide where gases go if a cell vents and keep that path away from the user's face and hands.","tags":[],"severity":"critical"},{"id":"rq-bat-6","text":"Battery is protected from puncture, crush and sharp edges in the housing","hint":"Check ribs, screw bosses and metal parts near the cell in CAD; drop loads can drive features into the cell.","tags":[],"severity":"critical"},{"id":"rq-bat-7","text":"Battery replaceability and access are decided (user, service or none)","hint":"Drives fasteners, door design and regional battery-removability rules.","tags":[],"severity":"minor"},{"id":"rq-bat-8","text":"Battery operating and charging temperature limits are reflected in the environmental requirements","hint":"Charging range is usually narrower than operating range; check against the product's use environment.","tags":[],"severity":"major"}]}]},{"id":"part-design","title":"Part Design & DFM","short":"Part DFM","version":1,"description":"Part-level design and manufacturability review covering CAD hygiene, general part design, and process rules for molding, sheet metal, machining, casting, additive, extrusion, elastomers, cosmetics and volume production.","sections":[{"id":"pd-cad","title":"CAD Model Hygiene","tags":[],"items":[{"id":"pd-cad-1","text":"Every sketch and feature in released part models is fully constrained","hint":"Check the feature tree for under-defined sketches (minus sign or blue geometry in most CAD tools). Under-defined sketches move silently when a dimension upstream changes.","tags":[],"severity":"minor"},{"id":"pd-cad-2","text":"The feature tree captures design intent: key dimensions drive the model and follow-on features reference them, not arbitrary edges","hint":"Change a primary dimension (wall, overall length, boss spacing) and confirm the model updates sensibly. Models built on incidental edges fail or distort on the first ECO.","tags":[],"severity":"minor"},{"id":"pd-cad-3","text":"The model rebuilds with no errors, warnings or suppressed features left unexplained","hint":"Force a full rebuild and review the error list. Suppressed or failed features can hide geometry that the supplier never sees in the STEP.","tags":[],"severity":"major"},{"id":"pd-cad-4","text":"Part bodies are single, closed solids with no zero-thickness geometry, slivers or self-intersections","hint":"Run the CAD geometry check (e.g. Check Entity / Validate Body) and an import check on the exported STEP. Broken geometry stops CAM, mold design and mold-flow meshing.","tags":[],"severity":"major"},{"id":"pd-cad-5","text":"Model units are millimeters and the part origin and principal planes follow the project convention","hint":"Check document units and confirm the origin sits on a meaningful datum (assembly origin or primary datum). Inconsistent units or origins cause scaled or misplaced parts at suppliers.","tags":[],"severity":"minor"},{"id":"pd-cad-6","text":"Modeled geometry is at nominal (or the agreed target such as mid-tolerance), and the convention is stated","hint":"Suppliers cut steel and program CAM from the model. If some features are modeled at a limit and others at nominal, state the rule on the drawing or in the model notes.","tags":[],"severity":"major"},{"id":"pd-cad-7","text":"No imported dumb solids or orphaned reference geometry remain in released part files","hint":"Remove or hide construction bodies, surface leftovers and imported reference parts, or move them to a clearly labeled folder. Stray bodies get exported and quoted as real parts.","tags":[],"severity":"minor"},{"id":"pd-cad-8","text":"The material is assigned in the model and matches the material callout on the drawing and BOM","hint":"Open the material property in CAD and compare with the drawing title block and BOM. A default material gives wrong mass, wrong FEA and wrong quotes.","tags":[],"severity":"major"},{"id":"pd-cad-9","text":"Mass properties (mass, center of gravity) are checked against the budget and a sanity estimate","hint":"Read the CAD mass properties with the correct material density and compare with the mass budget. A large mismatch usually means a missing feature, wrong material or wrong units.","tags":[],"severity":"minor"},{"id":"pd-cad-10","text":"Part file names, part numbers and revision properties follow the project numbering scheme","hint":"Check the custom properties that populate the title block and BOM. Mismatched names and numbers cause wrong parts to be quoted or built.","tags":[],"severity":"minor"},{"id":"pd-cad-11","text":"Configurations or variants in the part file are named clearly and the released one is unambiguous","hint":"Confirm which configuration is exported and drawn. Exporting the wrong configuration (e.g. a simplified or prototype variant) is a common release error.","tags":[],"severity":"minor"}]},{"id":"pd-gen","title":"General Part Design","tags":[],"items":[{"id":"pd-gen-1","text":"Internal corners carrying load or bending stress have a radius, not a sharp corner","hint":"Inspect the model with a curvature or edge check for zero-radius internal edges in load paths. Sharp internal corners are the most common origin of cracks in plastic, cast and machined parts.","tags":[],"severity":"major"},{"id":"pd-gen-2","text":"Stress concentrations at holes, notches, section changes and snap roots are identified and relieved","hint":"Mark the load path on the part and review every geometric discontinuity along it. Use the FEA from the analysis checklist to confirm peak stress where it matters.","tags":[],"severity":"major"},{"id":"pd-gen-3","text":"Minimum wall, rib, hole and slot sizes are within the chosen process capability","hint":"Compare the thinnest and smallest features (use thickness analysis in CAD) with supplier or process design guides. Features below capability are either not made or made inconsistently.","tags":[],"severity":"critical"},{"id":"pd-gen-5","text":"Features that locate the part to its mating parts are explicit (pins, bosses, slots), not reliant on outer profile","hint":"Trace how the part is located in the assembly in each direction. Locating on cosmetic outer surfaces or on drafted walls gives poor repeatability.","tags":[],"severity":"major"},{"id":"pd-gen-6","text":"The part has a defined location and method for part marking (part number, revision, material ID, date code, cavity ID as required)","hint":"Check the model for a marking pad or engraving area and confirm the method (molded-in, laser, label, stamp) suits the process and is not on a Class A surface.","tags":[],"severity":"minor"},{"id":"pd-gen-8","text":"Features are oriented so the part can be made in the minimum number of setups, tool directions or forming steps","hint":"Review the direction of every feature against the tool pull, spindle or press direction. Each extra direction adds a side action, setup or operation.","tags":[],"severity":"major"},{"id":"pd-gen-9","text":"The part is not over-designed: thickness, features and precision are no more than the function needs","hint":"Challenge every thick section, tight tolerance and secondary operation in the review. Over-design drives mass, cycle time and cost without improving function.","tags":[],"severity":"minor"},{"id":"pd-gen-10","text":"The part cannot be installed upside down or reversed if that would cause a failure, or misorientation is obvious","hint":"Check symmetric-looking parts for asymmetric function. Add a poka-yoke feature where needed; the assembly checklist owns the assembly sequence itself.","tags":[],"severity":"major"},{"id":"pd-gen-11","text":"Edges a user or assembler touches are broken or radiused, with no sharp edges or burrs left by design","hint":"Review handled edges in the model and on the drawing for radius or chamfer callouts. Sharp edges are an injury risk and a common safety-review finding.","tags":[],"severity":"major"},{"id":"pd-gen-12","text":"The selected manufacturing process for each part matches the production volume, cost target and geometry","hint":"Record the process for each part and the reason (e.g. machined for pilot, molded for volume). A process mismatch found late forces redesign of the part.","tags":[],"severity":"major"},{"id":"pd-gen-13","text":"Parts that change process between prototype and production have a design intended for the production process","hint":"A part designed for machining or printing rarely molds or casts without changes to walls, draft and corners. Confirm the production design is the one being reviewed.","tags":[],"severity":"major"},{"id":"pd-gen-14","text":"Clearances to mating parts, cables and moving parts are checked by interference detection in the assembly","hint":"Run interference and clearance checks in the top-level assembly, including at motion extremes. Zero-clearance contacts that are not intended are flagged.","tags":[],"severity":"critical"}]},{"id":"pd-im","title":"Injection Molding: Walls, Draft, Ribs & Bosses","tags":["injection-molded"],"items":[{"id":"pd-im-1","text":"Nominal wall thickness is uniform across the part, within the range the resin design guide recommends","hint":"Run a CAD thickness analysis and color-map the part. Rule of thumb: keep walls within about +/-10-15% of nominal; thick spots sink and void, thin spots short-shot.","tags":[],"severity":"major"},{"id":"pd-im-2","text":"Wall thickness transitions are gradual, not step changes","hint":"Rule of thumb: taper transitions over a length of about three times the thickness change. Abrupt steps cause sink, warp, flow hesitation and stress concentration.","tags":[],"severity":"major"},{"id":"pd-im-3","text":"Every face parallel to the draw direction has draft","hint":"Run a draft analysis for the pull direction of each half and every side action. Zero-draft faces scuff, stick or need costly tool changes. Rule of thumb: 1° or more per side for untextured surfaces.","tags":[],"severity":"critical"},{"id":"pd-im-4","text":"Textured faces have draft sized for the specified texture depth","hint":"Get the required draft per texture from the texture supplier or molder. Rule of thumb: about 1° per side extra for each 0.025 mm of texture depth; too little draft drags and streaks the texture.","tags":[],"severity":"major"},{"id":"pd-im-5","text":"Draft direction is chosen so critical dimensions and fits are controlled where they matter","hint":"Decide whether a fit or seal dimension is controlled at the top or base of the draft and note it on the drawing. Draft can eat most of a tight clearance on tall walls.","tags":[],"severity":"major"},{"id":"pd-im-6","text":"Rib thickness is a fraction of the adjoining wall thickness to avoid sink","hint":"Rule of thumb: rib thickness 40-60% of the wall, lower for high-shrink or cosmetic parts; check the resin design guide. Thick ribs sink on the opposite face.","tags":[],"severity":"major"},{"id":"pd-im-7","text":"Rib height and spacing are within moldable limits","hint":"Rule of thumb: rib height no more than about three times wall thickness and spacing at least two times wall thickness. Tall thin ribs short-shot, stick in the tool and are hard to cool.","tags":[],"severity":"major"},{"id":"pd-im-8","text":"Ribs and walls have a root radius","hint":"Rule of thumb: root radius about 25-50% of wall thickness. No radius concentrates stress; too large a radius creates a thick spot that sinks.","tags":[],"severity":"major"},{"id":"pd-im-9","text":"Bosses are cored out so their wall matches the nominal wall guideline","hint":"Rule of thumb: boss wall about 50-70% of nominal wall. Solid bosses sink, void and lengthen cycle time.","tags":[],"severity":"major"},{"id":"pd-im-10","text":"Tall or loaded bosses are supported by gussets or connected to nearby walls with ribs","hint":"Freestanding bosses crack, lean and fill poorly. Connect them with ribs or gussets that follow the rib thickness rule.","tags":[],"severity":"major"},{"id":"pd-im-11","text":"Bosses near walls are attached to the wall by a rib, or spaced away, not merged into a thick section","hint":"Merging a boss into a wall creates a thick spot. Check thickness analysis around every boss.","tags":[],"severity":"major"},{"id":"pd-im-12","text":"Screw boss dimensions (hole, outer diameter, depth) follow the fastener supplier guide for the resin","hint":"Thread-forming screw suppliers publish boss geometry per resin. Wrong pilot size strips or cracks bosses; confirm with a torque-to-strip test (see the validation checklist).","tags":[],"severity":"critical"},{"id":"pd-im-13","text":"Holes and cores are sized and spaced to resist core deflection and breakage","hint":"Rule of thumb: blind core length no more than about two to three times diameter for small cores; check with the molder. Long slender cores bend under melt pressure.","tags":[],"severity":"major"},{"id":"pd-im-14","text":"Thick sections that cannot be avoided are cored out from the non-cosmetic side","hint":"Check thickness analysis for local thick spots at boss bases, corners and intersections. Core them out to the nominal wall where possible.","tags":[],"severity":"major"},{"id":"pd-im-15","text":"Sink and void risk areas are identified and accepted or eliminated","hint":"Use thickness analysis and mold-flow sink prediction. Agree with the molder which areas may show sink and whether they matter functionally or cosmetically.","tags":[],"severity":"major"},{"id":"pd-im-16","text":"Outside corners have a radius equal to the inside radius plus wall thickness","hint":"Concentric radii keep the wall uniform through the corner. Sharp outside with radiused inside (or the reverse) creates thick or thin spots.","tags":[],"severity":"minor"},{"id":"pd-im-17","text":"Holes and windows near edges leave enough material for flow and strength","hint":"Rule of thumb: hole-to-edge and hole-to-hole distance at least two times wall thickness. Narrow webs short-shot, knit badly and crack.","tags":[],"severity":"major"},{"id":"pd-im-18","text":"The resin supplier's design guide has been reviewed for the selected grade","hint":"Most resin suppliers publish design guides covering walls, ribs, bosses, snaps and shrink. Note any recommendation the design departs from and why.","tags":[],"severity":"minor"}]},{"id":"pd-tool","title":"Injection Molding: Tooling & Process","tags":["injection-molded"],"items":[{"id":"pd-tool-1","text":"Parting line location is agreed with the molder and shown on the model or drawing","hint":"Review the parting line with the toolmaker before kick-off. A late parting-line change is a tooling recut.","tags":[],"severity":"critical"},{"id":"pd-tool-2","text":"Gate location and type are agreed with the molder for each part","hint":"Confirm the gate type (edge, sub, hot tip, valve) and location against fill, cosmetics and degating. Gate location drives knit lines, warp and fiber orientation.","tags":[],"severity":"major"},{"id":"pd-tool-3","text":"Weld/knit lines are predicted and are not in high-stress areas","hint":"Use mold-flow results to locate knit lines and overlay them on the load path. Knit lines can be far weaker than the bulk material, especially in glass-filled resins.","tags":[],"severity":"major"},{"id":"pd-tool-4","text":"Ejector pin locations are agreed with the molder and avoid cosmetic and sealing faces","hint":"Ask the toolmaker for an ejector layout. Witness marks and pin height tolerance (proud or recessed) must be acceptable where they land.","tags":[],"severity":"major"},{"id":"pd-tool-5","text":"Ejection is feasible: the part has enough flat area or ribs for ejectors and will not stick on the wrong half","hint":"Deep cores, low draft and textures on the ejector side cause sticking and distortion. Confirm with the toolmaker which half the part stays on.","tags":[],"severity":"major"},{"id":"pd-tool-6","text":"Every undercut is justified, and the side action, lifter or collapsible core needed for it is agreed with the toolmaker","hint":"List all undercuts from a draft analysis. Each action adds tool cost, maintenance and cycle time; remove undercuts that a pass-through core or redesign can avoid.","tags":[],"severity":"critical"},{"id":"pd-tool-7","text":"Lifters and slides have travel space and do not hit other features during ejection","hint":"Ask the toolmaker to confirm travel and clearance for each action. Lifters need clear space behind the undercut equal to their travel.","tags":[],"severity":"major"},{"id":"pd-tool-8","text":"Shut-off surfaces have adequate angle to avoid galling and flash","hint":"Rule of thumb: shut-offs at least about 3-5° from the pull direction, per toolmaker preference. Vertical shut-offs wear quickly and flash.","tags":[],"severity":"major"},{"id":"pd-tool-9","text":"Features likely to need tuning are designed steel-safe","hint":"Model critical fits so that tuning removes steel (adds plastic): e.g. snap engagement, boss diameters and mating clearances. Adding steel is costly welding.","tags":[],"severity":"major"},{"id":"pd-tool-10","text":"Shrink rate used for the tool is agreed with the molder for the specific resin grade","hint":"Get the shrink value from the resin datasheet and molder experience, including flow and cross-flow values for filled resins. Wrong shrink scales every dimension.","tags":[],"severity":"critical"},{"id":"pd-tool-11","text":"Warp risk is assessed, including anisotropic shrink in glass- or fiber-filled resins","hint":"Filled resins shrink differently along and across flow. Use mold-flow warp prediction for long, flat or thin parts and adjust gating or geometry.","tags":[],"severity":"major"},{"id":"pd-tool-12","text":"Mold-flow analysis is done for critical, large, thin-walled or cosmetic parts","hint":"Review fill, pack, weld lines, air traps, sink and warp. Run it before tool steel is cut; skip only for small simple parts where the molder agrees.","tags":[],"severity":"major"},{"id":"pd-tool-13","text":"Air traps are identified and venting is planned at end of fill","hint":"Mold-flow air-trap results and the toolmaker's venting plan should agree. Unvented ends of fill burn (dieseling) and short-shot.","tags":[],"severity":"major"},{"id":"pd-tool-14","text":"Flow length to wall thickness ratio is within the resin's capability","hint":"Check the resin's flow data or spiral-flow length for the nominal wall. Long thin flows need more gates or thicker walls.","tags":[],"severity":"major"},{"id":"pd-tool-15","text":"Inserts or molded-in metal parts are designed for placement, retention in the tool and resin shrink around them","hint":"Confirm insert loading method, tolerance and knurl or undercut for retention. Resin shrinking around metal can crack the boss; check the wall around the insert.","tags":[],"severity":"major"},{"id":"pd-tool-16","text":"Multi-cavity or family tool layout is agreed, including cavity balancing and cavity ID marking","hint":"Family tools fill unevenly when parts differ in volume. Add cavity numbers so defects can be traced.","tags":["high-volume"],"severity":"major"},{"id":"pd-tool-17","text":"Cooling and cycle time have been estimated for the thickest section and are consistent with the cost target","hint":"Cycle time is roughly driven by the square of the thickest wall. Ask the molder for a cycle estimate and confirm critical cooling (e.g. inside deep cores).","tags":["high-volume"],"severity":"major"},{"id":"pd-tool-18","text":"Tool texture or polish spec is defined per surface, and draft supports it","hint":"Specify texture or polish finish (e.g. a supplier texture code or SPI-style polish) for each face on the drawing or a texture map. Undefined finish is cut as the toolmaker sees fit.","tags":[],"severity":"minor"}]},{"id":"pd-imf","title":"Injection Molding: Snaps, Hinges, Threads & Overmolds","tags":["injection-molded"],"items":[{"id":"pd-imf-2","text":"Snap fits are moldable without side actions, or the action is justified","hint":"Use pass-through cores or windows beneath hooks where possible. Each snap with its own lifter adds cost and maintenance.","tags":[],"severity":"major"},{"id":"pd-imf-3","text":"Snap fits have a root radius and tapered beam where needed to spread strain","hint":"A sharp snap root is a crack starter. A tapered beam lowers peak strain for the same deflection.","tags":[],"severity":"major"},{"id":"pd-imf-4","text":"Snap retention force and disassembly behavior (permanent or releasable) match the requirement","hint":"Check the return angle against the intended separation force. Confirm whether service removal is needed and how a technician releases the snap.","tags":[],"severity":"major"},{"id":"pd-imf-5","text":"Living hinges use a resin suited to them and the geometry from the resin design guide","hint":"Polypropylene and some PE grades are typical; most engineering resins fail quickly. Gate so flow crosses the hinge, and flex it right after molding if the guide says to.","tags":[],"severity":"critical"},{"id":"pd-imf-6","text":"Molded threads have a thread form, pitch and start suited to molding","hint":"Molded external threads usually sit on the parting line or need unscrewing cores; internal threads need collapsible or unscrewing cores. Use coarse, rounded thread forms for plastic.","tags":[],"severity":"major"},{"id":"pd-imf-7","text":"Threaded inserts (heat-staked, ultrasonic, press-fit or molded-in) have hole sizes and boss walls per the insert supplier","hint":"Use the insert supplier's hole diameter and depth for the specific resin. Wrong hole size causes low pull-out torque or cracked bosses.","tags":[],"severity":"major"},{"id":"pd-imf-8","text":"Heat stake and ultrasonic weld features follow the equipment supplier's joint design","hint":"Check stake post diameter and height, energy director geometry and clearance for the horn. Poor joint design gives weak or flashy joints.","tags":[],"severity":"major"},{"id":"pd-imf-10","text":"Overmolds have mechanical interlocks (through holes, undercuts, grooves) in addition to chemical bond","hint":"Interlocks keep the overmold in place if the bond degrades from chemicals, heat or flexing.","tags":[],"severity":"major"},{"id":"pd-imf-11","text":"Overmold shut-off edges on the substrate are designed for a clean seal of the second-shot tool","hint":"The second shot needs a crisp shut-off groove or step on the substrate so it does not flash onto adjoining faces. Agree substrate tolerances with the molder.","tags":[],"severity":"major"},{"id":"pd-imf-12","text":"Substrate is designed to withstand second-shot pressure and heat without deforming","hint":"Thin substrate walls deflect under overmold pressure, causing flash and dimensional error. Support them from the tool side.","tags":[],"severity":"major"},{"id":"pd-imf-13","text":"Press-fits into plastic have interference calculated against hoop stress and creep","hint":"Calculate hoop stress at maximum interference and compare with the long-term allowable for the resin. Plastic press-fits relax over time and with temperature.","tags":[],"severity":"major"}]},{"id":"pd-sm","title":"Sheet Metal","tags":["sheet-metal"],"items":[{"id":"pd-sm-1","text":"Bend radius is at least the minimum for the material, temper and thickness","hint":"Check the supplier or material bend table. Rule of thumb: inside radius at least equal to thickness for mild steel; harder aluminum tempers need more. Too tight a radius cracks the outside of the bend.","tags":[],"severity":"critical"},{"id":"pd-sm-2","text":"Bend radii use the supplier's standard tooling where possible","hint":"Ask the fabricator for their punch radius list. Non-standard radii mean special tooling or air-bend variation.","tags":[],"severity":"minor"},{"id":"pd-sm-3","text":"The flat pattern uses the supplier's K-factor or bend deduction for the material and tooling","hint":"Get the K-factor or bend table from the fabricator and set it in CAD before releasing the flat. A wrong bend allowance shifts every formed dimension.","tags":[],"severity":"major"},{"id":"pd-sm-4","text":"Holes and slots are far enough from bends to avoid distortion","hint":"Rule of thumb: hole edge at least about 2-2.5 times thickness plus bend radius from the bend line. Closer holes deform into ovals during bending.","tags":[],"severity":"major"},{"id":"pd-sm-5","text":"Bend reliefs are added where a bend meets an edge or another bend","hint":"Check the flat for tears at bend ends. Rule of thumb: relief width at least sheet thickness and depth past the bend radius.","tags":[],"severity":"major"},{"id":"pd-sm-6","text":"Flange length is at least the minimum for the press brake tooling","hint":"Rule of thumb: minimum flange about 4 times thickness plus bend radius; confirm with the fabricator's die opening. Short flanges slip and bend unevenly.","tags":[],"severity":"major"},{"id":"pd-sm-7","text":"Hems and teardrop hems have a radius or gap the material can form without cracking","hint":"Closed hems crack in harder tempers and trap contamination. Confirm hem type with the fabricator and finish supplier.","tags":[],"severity":"minor"},{"id":"pd-sm-8","text":"Grain direction is specified where bends are tight or the material is prone to cracking","hint":"Bending across the rolling direction tolerates tighter radii. Note the grain direction on the flat pattern if it matters.","tags":[],"severity":"minor"},{"id":"pd-sm-9","text":"Self-clinching hardware (PEM-style) is compatible with sheet thickness and hardness per the hardware supplier","hint":"Check minimum sheet thickness, hardness and hole size in the supplier catalog. Fasteners in sheet that is too thin or too hard will not clinch.","tags":[],"severity":"critical"},{"id":"pd-sm-10","text":"Self-clinching hardware meets the supplier's minimum distance to edges and bends","hint":"Use the supplier's centerline-to-edge values. Hardware too close to an edge bulges it; too close to a bend cannot be pressed after forming.","tags":[],"severity":"major"},{"id":"pd-sm-11","text":"Countersinks are not specified in sheet thinner than the countersink depth requires","hint":"In thin sheet a machined countersink leaves a knife edge. Use a dimpled (formed) countersink or a different fastener.","tags":[],"severity":"major"},{"id":"pd-sm-12","text":"Tolerances across one or more bends reflect the fabricator's forming capability","hint":"Tolerances across bends accumulate bend variation. Agree realistic values with the fabricator; dimension critical features within one flat face where possible.","tags":[],"severity":"major"},{"id":"pd-sm-13","text":"Welds and spot welds are located where the welder can reach and distortion is acceptable","hint":"Check electrode access for spot welds and torch access for fusion welds. Long welds near precise features distort them; plan post-weld machining if needed.","tags":[],"severity":"major"},{"id":"pd-sm-14","text":"Finishing (plating, painting, powder coat) is specified after forming, or the coating is rated for forming","hint":"Pre-plated or pre-painted sheet can crack at bends. Note whether finish is applied before or after forming and allow for coating thickness on fits.","tags":[],"severity":"major"},{"id":"pd-sm-16","text":"Formed features (louvers, embosses, lances, extrusions) follow the fabricator's tooling dimensions","hint":"Formed features need specific punch tooling. Use the fabricator's standard form tools where possible and keep them away from bends.","tags":[],"severity":"minor"},{"id":"pd-sm-17","text":"Flat pattern nests efficiently and the part avoids features needing secondary operations","hint":"Ask the fabricator for nest yield on large parts. Tapped holes, machined features and deburring add operations.","tags":["high-volume"],"severity":"minor"}]},{"id":"pd-mc","title":"Machined Parts","tags":["machined"],"items":[{"id":"pd-mc-1","text":"Internal corner radii are no smaller than standard cutter radii, slightly larger than the cutter","hint":"Rule of thumb: internal radius slightly larger than the cutter radius so the tool does not dwell in the corner. Sharp internal vertical corners need EDM.","tags":[],"severity":"major"},{"id":"pd-mc-2","text":"Pocket depth is within the reach of a standard cutter for the corner radius","hint":"Rule of thumb: pocket depth up to about 3-4 times tool diameter is routine; deeper needs long-reach tools, slow feeds and more cost.","tags":[],"severity":"major"},{"id":"pd-mc-3","text":"Thin walls and floors are thick enough to machine without chatter or distortion","hint":"Rule of thumb: about 0.8 mm minimum in metal and more in plastic, per machinist capability. Thin unsupported walls vibrate and spring after release.","tags":[],"severity":"major"},{"id":"pd-mc-4","text":"Drilled holes use standard drill sizes unless a reamed or bored size is needed","hint":"Match hole diameters to standard metric drills. Non-standard sizes need interpolation or special tools.","tags":[],"severity":"minor"},{"id":"pd-mc-5","text":"Tapped hole depth is no deeper than needed for thread engagement","hint":"Rule of thumb: thread engagement about 1.5 times diameter in steel and 2 times in aluminum. Deeper threads add tap breakage risk and cost.","tags":[],"severity":"minor"},{"id":"pd-mc-6","text":"Blind tapped holes have drill depth beyond the full thread for tap clearance and chips","hint":"Specify full-thread depth and drill depth separately. Bottom-tapping to the drill point breaks taps.","tags":[],"severity":"major"},{"id":"pd-mc-7","text":"Threads in aluminum and other soft materials that are assembled repeatedly have threaded inserts","hint":"Use wire thread inserts or key-locking inserts where screws are removed in service. Threads in soft metal strip after a few cycles.","tags":[],"severity":"major"},{"id":"pd-mc-8","text":"Thread form, size and class are specified consistently in the model and on the drawing","hint":"Use cosmetic thread features in CAD and check the drawing callout (e.g. M4x0.7-6H). Mismatched thread callouts cause wrong taps or mating hardware.","tags":[],"severity":"major"},{"id":"pd-mc-9","text":"The part can be made in the minimum number of setups","hint":"Count the faces that need machining and the orientations required. Each setup adds cost and a datum transfer that affects tolerances.","tags":[],"severity":"major"},{"id":"pd-mc-11","text":"Every machined feature is accessible to a standard tool from a reachable direction","hint":"Check for features hidden behind walls or needing angled access. Inaccessible features need 5-axis machining, special tools or redesign.","tags":[],"severity":"major"},{"id":"pd-mc-12","text":"Edge breaks and deburr requirements are specified","hint":"Add a general note for edge break (e.g. a small chamfer or radius maximum) and call out any edge that must stay sharp. Undefined deburring gives inconsistent parts.","tags":[],"severity":"minor"},{"id":"pd-mc-13","text":"Turned features have relief grooves at shoulders where threads or grinding end","hint":"Thread runout and grinding wheels need a relief groove. Without one the thread is incomplete at the shoulder.","tags":[],"severity":"minor"},{"id":"pd-mc-14","text":"Turned parts have features concentric to one axis where possible to finish in one chucking","hint":"Off-axis features and flats need mill-turn or a second operation. Group them where possible.","tags":[],"severity":"minor"},{"id":"pd-mc-15","text":"Raw stock size has been considered and the part does not waste a large stock size","hint":"Check the envelope against standard bar and plate sizes. A part slightly larger than standard stock jumps to the next size.","tags":[],"severity":"minor"},{"id":"pd-mc-16","text":"Work-holding is feasible: the part has surfaces to clamp without distorting thin features","hint":"Discuss fixturing with the machinist for thin or odd-shaped parts. Add sacrificial tabs if needed and note their removal.","tags":[],"severity":"major"},{"id":"pd-mc-17","text":"Text and logos engraved or machined use a cutter-friendly font and size","hint":"Small text needs tiny engraving tools. Rule of thumb: letter stroke widths larger than the smallest practical cutter; confirm with the shop.","tags":[],"severity":"minor"}]},{"id":"pd-cst","title":"Cast Parts","tags":["cast"],"items":[{"id":"pd-cst-1","text":"Every face parallel to the die or mold pull has draft per foundry guidance","hint":"Run draft analysis for the casting pull direction. Draft requirements differ for die casting, investment casting and sand casting; get them from the foundry.","tags":[],"severity":"critical"},{"id":"pd-cst-2","text":"Section thickness is as uniform as practical, with gradual transitions","hint":"Thick sections solidify last and shrink, causing porosity and sink. Use thickness analysis and core out heavy areas.","tags":[],"severity":"major"},{"id":"pd-cst-3","text":"All internal and external corners have fillets per foundry guidance","hint":"Sharp corners cause hot tears, poor fill and stress concentration. Get the minimum fillet radius for the process from the foundry.","tags":[],"severity":"major"},{"id":"pd-cst-4","text":"Parting line and gating are agreed with the foundry","hint":"Parting line location affects draft, flash and trim. Gating and overflow location affect porosity and cosmetic areas.","tags":[],"severity":"critical"},{"id":"pd-cst-5","text":"Sealing faces and machined faces are located away from expected porosity","hint":"Ask the foundry for solidification simulation or porosity experience. Porosity exposed by machining can leak through sealing faces; specify impregnation if needed.","tags":[],"severity":"major"},{"id":"pd-cst-6","text":"Machined surfaces have machining stock added per foundry guidance","hint":"Model the as-cast part with stock on machined faces and draw both as-cast and machined states. Too little stock leaves cast skin; too much exposes porosity.","tags":[],"severity":"major"},{"id":"pd-cst-7","text":"Cored holes are sized and positioned within foundry capability, and holes needing precision are drilled after casting","hint":"Small or deep cored holes need pins that break or bend. Specify drilled holes where position or size is tight.","tags":[],"severity":"major"},{"id":"pd-cst-8","text":"Die-cast walls and ribs follow the die caster's rules of thumb for the alloy","hint":"Get the die caster's minimum wall, rib and boss guidelines for the alloy (e.g. aluminum or zinc). Walls too thin cold-shut; too thick porous.","tags":[],"severity":"major"},{"id":"pd-cst-9","text":"Casting datums and fixturing points for machining are defined on the as-cast part","hint":"Define target datums on cast surfaces the machinist can locate from. Without them the first machining setup is improvised.","tags":[],"severity":"major"},{"id":"pd-cst-10","text":"Ejector pin and overflow locations are acceptable for function and cosmetics","hint":"Ask the die caster for ejector and overflow layout. Trimmed overflow and gate stubs need a place that does not affect fit or appearance.","tags":[],"severity":"minor"},{"id":"pd-cst-11","text":"As-cast surface finish expected from the process is acceptable or post-processing is specified","hint":"Sand castings are rough and need machining or finishing on mating faces. State any shot blast, tumbling or coating requirement.","tags":[],"severity":"minor"},{"id":"pd-cst-12","text":"Pressure-tight castings have a leak test and impregnation requirement agreed with the foundry","hint":"If the casting holds fluid or forms a sealed enclosure, specify the leak test and whether vacuum impregnation is allowed.","tags":["sealed-ip","fluidic"],"severity":"major"}]},{"id":"pd-am","title":"Additive Parts","tags":["additive"],"items":[{"id":"pd-am-1","text":"The additive process and material are chosen for the required strength, temperature, accuracy and finish","hint":"Compare SLS, MJF, SLA, FDM and DMLS against the requirement with the service bureau. A process that cannot meet tolerance or temperature fails late.","tags":[],"severity":"major"},{"id":"pd-am-2","text":"Build orientation is defined for strength, accuracy and finish","hint":"Layer lines are weak in FDM and somewhat in other processes. Orient so loads are not across layers and critical surfaces are not support faces.","tags":[],"severity":"major"},{"id":"pd-am-3","text":"Anisotropy of the printed material is considered in load-bearing features","hint":"Use the service bureau's Z-direction properties for loads across layers. Many datasheets show only the best direction.","tags":[],"severity":"major"},{"id":"pd-am-4","text":"Minimum wall, hole and feature sizes follow the service bureau's design guide for the process","hint":"Check thinnest features with CAD thickness analysis against the bureau's limits. Features below the limit print poorly or break during cleaning.","tags":[],"severity":"major"},{"id":"pd-am-5","text":"Support structures can be removed and support witness areas are acceptable","hint":"Identify overhangs that need supports (SLA, FDM, DMLS). Supports inside closed channels cannot be removed.","tags":[],"severity":"major"},{"id":"pd-am-6","text":"Hollow or enclosed volumes have escape holes for trapped powder or resin","hint":"SLS, MJF and SLA parts with sealed cavities trap powder or liquid resin. Add drain holes sized per the bureau.","tags":[],"severity":"major"},{"id":"pd-am-7","text":"Threads in printed parts use inserts or a thread form suited to the process","hint":"Small printed threads are weak and inaccurate. Use heat-set inserts, tapped holes after printing or coarse modeled threads.","tags":[],"severity":"major"},{"id":"pd-am-8","text":"Dimensional accuracy expectations are agreed with the service bureau for critical features","hint":"Get the bureau's accuracy statement for the process and part size. Plan post-machining for fits that need more.","tags":[],"severity":"major"},{"id":"pd-am-9","text":"Post-processing (support removal, curing, bead blast, dye, vapor smoothing, heat treat, HIP) is specified","hint":"Post-processing changes dimensions, properties and appearance. Specify it on the drawing or purchase order.","tags":[],"severity":"minor"},{"id":"pd-am-10","text":"Large flat areas and thick sections are designed to limit warp and residual stress","hint":"SLS and DMLS parts warp with large flat areas or abrupt thickness changes. Add ribs, lattices or fillets per the bureau's advice.","tags":[],"severity":"major"},{"id":"pd-am-11","text":"Part design takes advantage of additive capability where it adds value (consolidation, internal channels, lattices)","hint":"If the part is printed for production, check that it is not just a molded part design printed at high cost. Consolidation can remove fasteners and assembly steps.","tags":[],"severity":"minor"},{"id":"pd-am-12","text":"Printed parts used for production have a defined material lot, machine and process qualification approach","hint":"Print properties vary between machines, powder refresh rates and bureaus. Agree what is locked and how changes are controlled.","tags":["medical","structural"],"severity":"major"}]},{"id":"pd-ext","title":"Extrusions","tags":["extruded"],"items":[{"id":"pd-ext-1","text":"A standard extrusion profile has been considered before a custom die","hint":"Check extruder catalogs for a standard profile that meets the need. Custom dies add tooling cost and lead time.","tags":[],"severity":"minor"},{"id":"pd-ext-2","text":"Custom profile walls are as symmetric and uniform as practical","hint":"Unequal walls cool and flow unevenly, causing twist and dimensional problems. Rule of thumb: keep adjacent wall ratios within about 2:1.","tags":[],"severity":"major"},{"id":"pd-ext-3","text":"Tongue ratios (depth to width of channels) are within the extruder's capability","hint":"Deep narrow channels need a fragile die tongue. Ask the extruder for their maximum tongue ratio for the alloy.","tags":[],"severity":"major"},{"id":"pd-ext-4","text":"Profile tolerances match the extruder's capability for the alloy and profile size","hint":"Get the extruder's standard tolerances. Tighter tolerances require special processing or post-machining.","tags":[],"severity":"major"},{"id":"pd-ext-5","text":"Cut length, end squareness and end machining are specified","hint":"Saw cut length tolerance and burr are often looser than expected. Specify any end machining, drilling or deburr as a secondary operation.","tags":[],"severity":"major"},{"id":"pd-ext-6","text":"Corner radii in the profile meet the extruder's minimums","hint":"Sharp corners wear dies and cause tearing. Use the extruder's minimum internal and external radii.","tags":[],"severity":"minor"},{"id":"pd-ext-7","text":"Features along the length (holes, slots, cutouts) are designed for post-machining fixturing","hint":"Long extrusions bow and twist within tolerance. Fixture locations and datum on the profile need definition.","tags":[],"severity":"major"},{"id":"pd-ext-8","text":"Hollow profiles are designed for the die type the extruder recommends","hint":"Hollow profiles need porthole or bridge dies with weld seams. Check the seam location is not in a highly stressed area.","tags":[],"severity":"major"},{"id":"pd-ext-9","text":"Surface finish, anodizing and visible faces of the profile are defined","hint":"Extrusion die lines are visible on exposed faces. Specify which faces are cosmetic and the finish requirement.","tags":["cosmetic"],"severity":"minor"}]},{"id":"pd-elb","title":"Elastomer Parts","tags":["elastomer"],"items":[{"id":"pd-elb-1","text":"Durometer is selected for the function (sealing, damping, actuation, grip) and stated with its scale","hint":"State hardness as Shore A or Shore 00 with a tolerance. Softer parts seal at lower force but extrude and tear more easily.","tags":[],"severity":"major"},{"id":"pd-elb-3","text":"Gasket groove volume accommodates the compressed elastomer without overfilling","hint":"Elastomers are nearly incompressible. Check groove fill at maximum material condition per the seal supplier guide.","tags":[],"severity":"critical"},{"id":"pd-elb-4","text":"Compression set data for the material at the operating temperature has been reviewed","hint":"Look up compression set at temperature and time from the datasheet. High compression set means loss of sealing force over life.","tags":[],"severity":"major"},{"id":"pd-elb-5","text":"LSR parts have shut-off, venting and parting-line clearances within the LSR molder's flash capability","hint":"Liquid silicone flashes into gaps far smaller than thermoplastics do, so steel fits and venting must be agreed with the LSR molder. Flash on sealing or keypad faces is a common reject.","tags":[],"severity":"major"},{"id":"pd-elb-6","text":"Keypad actuation force and travel meet the specification","hint":"Model the membrane web and check the force-travel curve with the keypad supplier. Tactile ratio and travel drive user feel.","tags":[],"severity":"major"},{"id":"pd-elb-7","text":"Elastomer parts have draft and parting line agreed with the molder, with flash location acceptable","hint":"Elastomer parts are often demolded by stretching, but flash and parting line still need agreement. Flash on sealing faces leaks.","tags":[],"severity":"major"},{"id":"pd-elb-8","text":"O-ring and seal dimensions use standard sizes where possible","hint":"Use standard O-ring cross sections and sizes (e.g. ISO 3601 series). Custom sizes add tooling and lead time.","tags":[],"severity":"minor"},{"id":"pd-elb-9","text":"Elastomer parts are retained in position during assembly","hint":"Loose gaskets fall out or twist during assembly. Use dovetail grooves, retention bumps or adhesive where needed.","tags":[],"severity":"major"},{"id":"pd-elb-10","text":"Elastomer chemical compatibility with fluids, cleaners and greases it will meet is confirmed per supplier data","hint":"Some elastomers swell or degrade in oils, alcohols or cleaners. Check the supplier compatibility chart.","tags":[],"severity":"major"}]},{"id":"pd-cos","title":"Cosmetic Considerations","tags":["cosmetic"],"items":[{"id":"pd-cos-1","text":"Knit lines are predicted away from Class A surfaces","hint":"Use mold-flow weld-line results overlaid on the cosmetic surface map. Knit lines on Class A faces show, especially with metallic or dark colors.","tags":["injection-molded"],"severity":"major"},{"id":"pd-cos-2","text":"Sink marks are not expected on Class A surfaces","hint":"Check rib, boss and thick-section locations behind cosmetic faces. Use mold-flow sink prediction and revise rib thickness if needed.","tags":["injection-molded"],"severity":"major"},{"id":"pd-cos-3","text":"Gate vestige is hidden on a non-cosmetic face or under another part","hint":"Agree gate location with the molder and check vestige height. A visible gate mark on a Class A face is a common cosmetic reject.","tags":["injection-molded","cast"],"severity":"major"},{"id":"pd-cos-4","text":"Parting lines are placed on edges or features where they are hidden or read as a design line","hint":"A parting line across a flat cosmetic face shows mismatch and flash. Place it on a sharp edge or a design step.","tags":[],"severity":"major"},{"id":"pd-cos-5","text":"Each cosmetic texture and gloss level is approved on a physical sample plaque before the tool is textured","hint":"Approve texture, gloss and color on plaques in the production resin. Texture looks different on screen, in another resin or at a different draft; re-texturing a tool is slow and costly.","tags":["injection-molded"],"severity":"minor"},{"id":"pd-cos-6","text":"Class A, B and C surfaces are identified on the model or drawing","hint":"Use a surface map or colored faces so the molder knows which faces are cosmetic. Without it, ejectors and gates may land on visible faces.","tags":[],"severity":"major"},{"id":"pd-cos-7","text":"Matching parts have cosmetic gaps and flushness designed with realistic process variation","hint":"Model nominal gaps large enough that variation does not cause interference or uneven gaps. Use a design step to hide mismatch at split lines.","tags":[],"severity":"minor"},{"id":"pd-cos-8","text":"Large flat cosmetic faces have slight curvature or texture to hide distortion","hint":"Perfectly flat glossy faces show every warp and sink. A small crown or texture hides it.","tags":[],"severity":"minor"},{"id":"pd-cos-9","text":"Slide, lifter and tool insert witness lines are kept off Class A faces","hint":"Review the tool layout with the toolmaker for every Class A face. Witness lines from actions and inserts show as fine lines and worsen as the tool wears.","tags":["injection-molded","cast"],"severity":"minor"}]},{"id":"pd-vol","title":"Volume Production","tags":["high-volume"],"items":[{"id":"pd-vol-1","text":"Part cost drivers (material, cycle time, tooling, secondary operations) are reviewed against the cost target","hint":"Get a cost breakdown from the supplier quote. Identify the top drivers and the design levers for each.","tags":[],"severity":"major"},{"id":"pd-vol-2","text":"Tool life and steel specification match the lifetime volume","hint":"Agree tool class and steel (e.g. hardened steel for high volume or glass-filled resin) with the toolmaker. Soft tools wear out early.","tags":[],"severity":"major"},{"id":"pd-vol-4","text":"Supplier DFM feedback has been received for every new tool or production part","hint":"Request a formal DFM report from each toolmaker or fabricator. Store it with the design record.","tags":[],"severity":"major"},{"id":"pd-vol-5","text":"Every supplier DFM comment is dispositioned (accepted, rejected with reason, or deferred) and the record is kept","hint":"Track DFM comments in a log with owner and decision. Unresolved comments resurface as tool changes.","tags":[],"severity":"major"},{"id":"pd-vol-6","text":"Secondary operations (deburr, machining, inserts, painting) are minimized or justified","hint":"List every post-process operation. Each adds cost, handling and a defect opportunity.","tags":[],"severity":"minor"},{"id":"pd-vol-7","text":"Number of cavities or production rate matches the demand forecast","hint":"Compare cavitation or line capacity with annual volume and peak demand. Too few cavities limit supply; too many cost tooling up front.","tags":[],"severity":"major"},{"id":"pd-vol-8","text":"Material grade is commonly available from more than one source or the single source is accepted","hint":"Special grades and colors carry long lead times and minimum orders. Check availability with the supplier; the materials checklist owns the grade choice.","tags":[],"severity":"major"},{"id":"pd-vol-9","text":"Design allows production tooling to be adjusted after first articles without a full recut","hint":"Steel-safe fits, inserts for changeable features and adjustable stops allow tuning. Confirm with the toolmaker.","tags":[],"severity":"major"},{"id":"pd-vol-10","text":"Part design supports automated handling, packing or inspection where planned","hint":"Check for features that allow robot pick, nesting or vision inspection. Parts that tangle or nest poorly slow production.","tags":[],"severity":"minor"}]}]},{"id":"tolerancing","title":"Tolerancing & GD&T","short":"Tolerancing","version":1,"description":"Tolerancing strategy, datums, GD&T, fits, stack-ups, cosmetic gap and flush, seal compression, mechanism clearances and inspection.","sections":[{"id":"tol-strat","title":"Tolerancing Strategy","tags":[],"items":[{"id":"tol-strat-1","text":"Functional requirements that depend on dimensions (fit, seal, alignment, appearance, motion) are listed before tolerances are assigned","hint":"Walk the product requirements and assembly and write down what each interface must do. Tolerances assigned without a functional reason end up either too loose to work or too tight to make.","tags":[],"severity":"major"},{"id":"tol-strat-2","text":"Critical-to-function (CTF) dimensions are identified and listed for every part","hint":"Keep a CTF list per part that traces each dimension to the requirement or stack it serves. The list drives inspection, supplier focus and change impact review.","tags":[],"severity":"major"},{"id":"tol-strat-3","text":"A general tolerance standard is chosen for each part and suits its process","hint":"For example ISO 2768 with a class suited to machining, ISO 8062 casting tolerance grades for castings, or a molder-agreed general table for plastics. A machining class applied to a molded part is usually unachievable on untoleranced features.","tags":[],"severity":"major"},{"id":"tol-strat-4","text":"Every specific tolerance is within the capability of the chosen process and supplier","hint":"Compare each tolerance against the supplier's stated capability or historical Cpk data for that feature type and size. Ask the supplier to flag any tolerance they cannot hold before tooling or quoting is final.","tags":[],"severity":"critical"},{"id":"tol-strat-5","text":"Tight tolerances are applied only to features that need them","hint":"Review every tolerance tighter than the general tolerance and confirm it is on the CTF list or supports a stack. Unnecessary tight tolerances add cost, inspection time and rejected parts.","tags":[],"severity":"major"},{"id":"tol-strat-6","text":"Tolerances on molded parts account for the material's shrink variation and the number of cavities","hint":"Glass-filled and semi-crystalline resins vary more and shrink anisotropically. Cavity-to-cavity variation adds to the spread, so confirm tolerances with the molder for multi-cavity tools.","tags":["injection-molded"],"severity":"major"},{"id":"tol-strat-7","text":"Dimensions intended to be adjusted at tool trial are identified as steel-safe","hint":"Leave plastic on (steel-safe) where the fit may need tuning so the tool can be cut rather than welded. Mark these on the drawing or in the tooling kickoff notes.","tags":["injection-molded"],"severity":"major"},{"id":"tol-strat-8","text":"The tolerancing scheme is consistent between the 3D model nominal and the drawing","hint":"Model nominals should sit at the intended target (often mid-tolerance for asymmetric limits). Suppliers machine and cut tools to the model, so a model at one limit shifts the whole distribution.","tags":[],"severity":"major"}]},{"id":"tol-dat","title":"Datums & Datum Reference Frames","tags":[],"items":[{"id":"tol-dat-1","text":"Primary datums are the functional mating or locating features of the part","hint":"The datum features should be the surfaces and holes that locate the part in the assembly. Datums chosen for drawing convenience produce parts that measure good and assemble badly.","tags":[],"severity":"critical"},{"id":"tol-dat-2","text":"Datum features are accessible and stable for fixturing and inspection","hint":"Check that a CMM probe or fixture can contact each datum feature and that it is large enough to establish the datum repeatably. Small, flexible or draft-angled datums give unstable measurements.","tags":[],"severity":"major"},{"id":"tol-dat-3","text":"Each datum reference frame constrains all the degrees of freedom the controlled features need","hint":"Walk the primary, secondary and tertiary datums and confirm translation and rotation are locked as required. An under-constrained frame lets the inspector orient the part differently each time.","tags":[],"severity":"major"},{"id":"tol-dat-4","text":"Datum precedence (primary, secondary, tertiary) reflects how the part seats in assembly","hint":"The primary datum should be the surface that contacts first and carries the most contact. Reversed precedence changes the measured result and can accept parts that do not fit.","tags":[],"severity":"major"},{"id":"tol-dat-5","text":"Mating parts use corresponding datum schemes at their shared interfaces","hint":"Compare datums across mating drawings: the hole pattern on one part and the pin pattern on the other should both be controlled to the same functional interface. Mismatched schemes break stack-up traceability.","tags":[],"severity":"major"},{"id":"tol-dat-6","text":"Datum targets are used where a full surface datum is impractical (castings, moldings, sheet metal)","hint":"Use datum target points, lines or areas on large, warped or as-cast surfaces and match them to fixture locators. Specify the target size and location on the drawing.","tags":[],"severity":"major"},{"id":"tol-dat-7","text":"Datum features on molded or cast parts avoid parting lines, gates, ejector marks and draft","hint":"Flash, vestige and draft make a surface a poor datum. Check gate and ejector locations against the datum features before releasing for tooling.","tags":[],"severity":"major"},{"id":"tol-dat-8","text":"Datum features are labeled with a single, consistent identifier scheme across drawing sheets and views","hint":"Reusing or skipping datum letters between sheets confuses suppliers and CMM programmers. Check every feature control frame references a datum that is actually defined.","tags":[],"severity":"minor"}]},{"id":"tol-gdt","title":"GD&T Application","tags":[],"items":[{"id":"tol-gdt-2","text":"Hole and pin patterns are located with position tolerances rather than chained ± dimensions","hint":"Position to a datum frame gives a cylindrical zone, enables bonus tolerance and avoids the accumulation of chained ± dimensions. Check bolt patterns, PCB mounting bosses and dowel patterns.","tags":[],"severity":"major"},{"id":"tol-gdt-3","text":"Freeform, molded and cast surfaces are controlled with profile of a surface","hint":"Profile to a datum frame controls size, form, orientation and location of complex surfaces in one callout, referenced to the CAD model. Avoid trying to dimension splines with ± coordinates.","tags":[],"severity":"major"},{"id":"tol-gdt-4","text":"Form controls (flatness, straightness, cylindricity) are applied only where function needs them","hint":"Flatness on a sealing or mounting face is justified; flatness on every face is cost. Check each form callout against the CTF list.","tags":[],"severity":"major"},{"id":"tol-gdt-5","text":"Orientation controls (parallelism, perpendicularity, angularity) reference a datum and are tighter than the related size or location tolerance","hint":"An orientation tolerance looser than the size or position tolerance it refines adds nothing. Verify the datum reference makes sense for the function.","tags":[],"severity":"minor"},{"id":"tol-gdt-6","text":"MMC or LMC modifiers are applied deliberately, with the functional reason understood","hint":"MMC suits clearance fits and enables functional gauging; LMC suits wall thickness and edge distance. A modifier added by habit can allow parts that fail the function.","tags":[],"severity":"major"},{"id":"tol-gdt-7","text":"Composite or multi-segment position is used where pattern-to-pattern location is looser than feature-to-feature spacing","hint":"A composite frame lets the pattern float relative to datums while holding hole-to-hole spacing tight, which often matches how mating patterns actually assemble. Confirm the inspector can measure it.","tags":[],"severity":"minor"},{"id":"tol-gdt-8","text":"No feature is over-constrained by conflicting or redundant tolerances","hint":"Look for features with both ± location dimensions and a position callout, or two controls that set the same limit. Conflicts force the supplier to guess which governs.","tags":[],"severity":"major"},{"id":"tol-gdt-9","text":"Every feature control frame is complete and syntactically valid","hint":"Check the symbol, zone shape (diameter symbol where needed), value, modifiers and datum references. Use the CAD GD&T checker if available, then read each frame manually.","tags":[],"severity":"major"},{"id":"tol-gdt-10","text":"Basic dimensions locate every feature controlled by position or profile","hint":"A position or profile tolerance without basic dimensions to its datums is undefined. Basic dimensions can come from the model if the drawing states the model is the source.","tags":[],"severity":"major"},{"id":"tol-gdt-11","text":"Runout or concentricity controls on rotating parts reflect the functional axis","hint":"Use circular or total runout to the bearing or mounting axis for shafts, rotors and pulleys. Coaxial controls to the wrong datum let wobble through.","tags":["moving-parts"],"severity":"major"}]},{"id":"tol-fit","title":"Fits & Clearances","tags":[],"items":[{"id":"tol-fit-1","text":"Shafts, bores, bearing seats and dowel pins use ISO 286 fit designations matched to the function","hint":"Pick clearance, transition or interference fits from ISO 286 and the bearing or pin manufacturer's recommendations. Check both limits on the drawing, not just the fit name.","tags":[],"severity":"major"},{"id":"tol-fit-2","text":"Bearing housing and shaft fits follow the bearing manufacturer's recommendations for the load case","hint":"Rotating versus stationary load on the inner or outer ring sets which ring needs interference. A wrong fit causes ring creep, fretting or lost internal clearance.","tags":["moving-parts"],"severity":"critical"},{"id":"tol-fit-3","text":"Press-fit interference at the maximum condition stays within the material's allowable stress","hint":"Calculate hoop stress at maximum interference with thick-wall cylinder equations or FEA and compare to the yield or creep limit per material datasheet. Plastic bosses are especially prone to cracking and stress relaxation.","tags":[],"severity":"critical"},{"id":"tol-fit-4","text":"Press-fit interference at the minimum condition still delivers the required retention or torque","hint":"Check pull-out or slip torque at minimum interference, including any relaxation over life and temperature. Validate on parts at both ends of the tolerance.","tags":[],"severity":"major"},{"id":"tol-fit-5","text":"Clearances remain positive across the full operating and storage temperature range","hint":"Compute dimensional change from the CTE mismatch of mating materials (plastic in metal, aluminum on steel) at the temperature extremes. Thermal growth can turn a clearance fit into interference.","tags":[],"severity":"major"},{"id":"tol-fit-6","text":"Coating, plating and paint thickness is accounted for on toleranced features","hint":"State whether dimensions apply before or after finish and mask or adjust critical bores, threads and fits. Anodize and powder coat thickness can close up a clearance fit entirely.","tags":[],"severity":"major"},{"id":"tol-fit-7","text":"Fastener clearance holes are sized so the parts assemble at worst-case position","hint":"Use the fixed or floating fastener formula with the position tolerances on both parts. Undersized clearance holes cause binding and cross-threading on the line.","tags":[],"severity":"major"},{"id":"tol-fit-8","text":"Moisture absorption is accounted for in fits on hygroscopic plastics","hint":"Polyamides and some other resins grow measurably as they absorb moisture. Check fits at conditioned dimensions per material datasheet, not dry-as-molded.","tags":["injection-molded"],"severity":"major"},{"id":"tol-fit-9","text":"Slip and sliding fits have clearance for lubricant film or wear allowance where required","hint":"Check that the minimum clearance supports the intended lubrication and that the maximum clearance after wear still meets play limits.","tags":["moving-parts"],"severity":"minor"}]},{"id":"tol-stk","title":"Tolerance Stack-Ups","tags":[],"items":[{"id":"tol-stk-1","text":"Every critical gap, interference, alignment and engagement in the assembly has a documented stack-up","hint":"Cross-check the CTF list and assembly interfaces against the stack-up register. Unstacked interfaces are where first-build surprises come from.","tags":[],"severity":"critical"},{"id":"tol-stk-2","text":"The stack method (worst-case, RSS or statistical) is stated and justified for each stack","hint":"Worst-case suits low volume, safety-critical or few-contributor stacks. RSS assumes centered, independent, normally distributed contributors and enough volume for the statistics to hold.","tags":[],"severity":"major"},{"id":"tol-stk-3","text":"Every stack-up input is traced to a dimension and tolerance on a released or current drawing","hint":"List the drawing number, revision and dimension for each contributor. Inputs typed from memory or the model drift out of date silently.","tags":[],"severity":"major"},{"id":"tol-stk-4","text":"Stack loops are drawn with correct direction and include every contributor in the path","hint":"Sketch the vector loop on a section view and check signs. Missing a contributor (a gasket, a washer, a datum shift) is the most common stack error.","tags":[],"severity":"major"},{"id":"tol-stk-5","text":"Assembly variation (fastener float, fixture location, operator placement) is included as a contributor","hint":"Clearance-hole float and fixture locating error often dominate part tolerances. Include them explicitly rather than assuming perfect assembly.","tags":[],"severity":"major"},{"id":"tol-stk-6","text":"Molded part contributors include shrink and warp variation, not only the drawing tolerance","hint":"Warp on long or thin parts can exceed the drawing tolerance in effect. Use moldflow warp results or measured first-shot data where available.","tags":["injection-molded"],"severity":"major"},{"id":"tol-stk-7","text":"Sheet-metal contributors include bend-to-bend and bend-to-hole variation","hint":"Each bend adds positional error to features across it. Use supplier capability for bend tolerances, not the general machining tolerance.","tags":["sheet-metal"],"severity":"major"},{"id":"tol-stk-8","text":"Geometric tolerances (position, profile, flatness) are converted correctly into stack contributors","hint":"Convert a diametral position zone to ± half the zone and include bonus or datum shift where modifiers apply. Ignoring geometric tolerances understates the stack.","tags":[],"severity":"major"},{"id":"tol-stk-9","text":"RSS stacks that rely on process centering have a supporting Cpk or a sigma assumption stated","hint":"State the assumed process capability for each contributor. If suppliers will not commit to that capability, recompute worst-case or with a safety factor.","tags":["high-volume"],"severity":"major"},{"id":"tol-stk-10","text":"Each stack result shows positive margin against the functional limit at the stated confidence","hint":"Report minimum and maximum result next to the requirement. A stack that just passes at nominal is not a pass.","tags":[],"severity":"critical"},{"id":"tol-stk-11","text":"Stacks with insufficient margin have a recorded resolution (tolerance change, design change, adjustment or selective assembly)","hint":"Track the action in the review log. Do not release with a known negative stack and a note to fix it at tool trial.","tags":[],"severity":"major"},{"id":"tol-stk-12","text":"Stack-ups are re-run after any change to a contributing dimension, tolerance, material or supplier","hint":"Link stacks to the change process so an ECO touching a contributor triggers a stack review. Check the stack revision matches the current drawing revisions.","tags":[],"severity":"major"},{"id":"tol-stk-13","text":"Stack-up predictions are compared against measured first-article or pilot data","hint":"Measure the actual gaps on built assemblies and compare with predicted range. Large disagreement means a missing contributor or wrong process assumption.","tags":[],"severity":"minor"}]},{"id":"tol-cos","title":"Cosmetic Gap & Flush","tags":["cosmetic"],"items":[{"id":"tol-cos-1","text":"Visible gap and flush targets are defined with nominal and allowable range for every Class A seam","hint":"Agree targets with industrial design and record them on a gap-and-flush map. Without targets there is no stack to run and no accept criterion.","tags":[],"severity":"major"},{"id":"tol-cos-2","text":"Every cosmetic seam has a gap and a flush stack-up showing the targets are achievable","hint":"Run both directions: gap across the seam and step normal to the surface. Flush stacks on two molded shells are frequently missed.","tags":[],"severity":"major"},{"id":"tol-cos-3","text":"Gap uniformity (variation along a seam) is controlled, not only the average gap","hint":"Tapered gaps are more visible than a uniformly larger gap. Profile tolerances on both mating edges control taper.","tags":[],"severity":"major"},{"id":"tol-cos-4","text":"Cosmetic seam design hides expected variation (reveal, offset or step-in) where flush cannot be held","hint":"A deliberate reveal or a small designed step tolerates variation that a zero-gap, zero-flush seam shows immediately. Review with industrial design.","tags":[],"severity":"minor"},{"id":"tol-cos-5","text":"Parts that meet at a visible seam are located from the same functional datums","hint":"Locate both parts from shared features near the seam rather than from distant datums so variation does not accumulate across the part.","tags":[],"severity":"major"},{"id":"tol-cos-6","text":"Color and gloss-matched mating parts consider texture and draft effects on perceived gap","hint":"Texture and draft at the seam edge change how a gap reads. Review on sample plaques or first shots under the specified lighting.","tags":[],"severity":"minor"}]},{"id":"tol-seal","title":"Sealing Compression Stacks","tags":["sealed-ip"],"items":[{"id":"tol-seal-2","text":"Seal compression stack includes flange flatness and deflection between fasteners","hint":"Housings bow between screws, so compression is lowest midway between fasteners. Check with FEA or measurement and include flatness tolerance on the flange.","tags":[],"severity":"major"},{"id":"tol-seal-3","text":"O-ring groove dimensions and tolerances follow the O-ring supplier's design guide","hint":"Check groove depth, width, fill ratio and surface finish against the supplier guide for static or dynamic use. Include thermal swell and chemical swell where relevant.","tags":["elastomer"],"severity":"major"},{"id":"tol-seal-4","text":"Seal compression at minimum stack still exceeds the minimum after compression set over life","hint":"Apply the compression set from the material datasheet at the operating temperature and life. A seal that passes new may leak after aging.","tags":[],"severity":"major"},{"id":"tol-seal-5","text":"Hard stops or compression limiters control final gasket compression independent of fastener torque","hint":"Without a metal-to-metal or plastic-to-plastic stop, compression depends on torque and part creep. Stack the hard stop height against the groove.","tags":[],"severity":"major"},{"id":"tol-seal-6","text":"Seal squeeze is checked at the temperature extremes, including CTE mismatch of housing and seal","hint":"Elastomers have much higher CTE than housings. Check squeeze at cold (shrunken seal) and hot (expanded, possible over-fill of the groove).","tags":[],"severity":"minor"}]},{"id":"tol-mech","title":"Mechanism Clearances & Kinematics","tags":["moving-parts"],"items":[{"id":"tol-mech-1","text":"Running clearances are positive throughout the full range of motion at worst-case tolerances","hint":"Sweep the mechanism in CAD motion study with parts at their worst-case extremes, or run stacks at multiple positions. Interference often occurs mid-travel, not at the end stops.","tags":[],"severity":"critical"},{"id":"tol-mech-2","text":"Maximum play or backlash at worst-case tolerances meets the functional and feel requirements","hint":"Stack the loose end as well as the tight end. Excess play produces rattle, wobble and poor perceived quality.","tags":[],"severity":"major"},{"id":"tol-mech-3","text":"Gear center distance and backlash tolerances follow the gear supplier's recommendations","hint":"Include bore position, bearing clearance and housing thermal growth in the center distance stack. Too little backlash binds hot, too much is noisy.","tags":[],"severity":"major"},{"id":"tol-mech-4","text":"Hinge and pivot axes are aligned within a tolerance that avoids binding","hint":"Coaxiality or position of multiple hinge knuckles to a common axis sets binding torque. Check with a stack across all knuckles, not just one.","tags":[],"severity":"major"},{"id":"tol-mech-5","text":"Latch and detent engagement remains sufficient at worst-case tolerances","hint":"Stack latch overlap at minimum engagement and confirm it holds under the specified load. Check that maximum engagement still releases at the specified force.","tags":[],"severity":"critical"},{"id":"tol-mech-6","text":"End stops and travel limits are dimensioned so travel is guaranteed within tolerance","hint":"Stack the travel at minimum to confirm full function and at maximum to confirm no over-travel into other parts.","tags":[],"severity":"major"},{"id":"tol-mech-7","text":"Spring working lengths and preloads stay within spec across the tolerance range of the spring pocket","hint":"Stack the pocket length and spring free-length tolerance. Out-of-range preload changes actuation force and can overstress the spring.","tags":[],"severity":"major"}]},{"id":"tol-insp","title":"Inspection & Measurement","tags":[],"items":[{"id":"tol-insp-1","text":"Every toleranced feature can be measured with available equipment and access","hint":"For each callout, name the method (CMM, gauge, optical, height gauge). Features with no feasible measurement cannot be accepted or rejected.","tags":[],"severity":"major"},{"id":"tol-insp-2","text":"Measurement uncertainty is small relative to the tolerance it verifies","hint":"Rule of thumb: measurement uncertainty or gauge R&R within about 10% of tolerance is good, and above about 30% is usually unacceptable. Run a gauge R&R study on tight CTF features.","tags":[],"severity":"major"},{"id":"tol-insp-3","text":"A CMM or fixture strategy matching the datum reference frame is agreed with the supplier","hint":"The supplier's fixture and alignment should replicate the drawing datums. Different alignment schemes are a common source of supplier-versus-customer measurement disputes.","tags":[],"severity":"major"},{"id":"tol-insp-4","text":"Functional gauges are specified for MMC-modified hole patterns on high-volume parts","hint":"A go gauge built to virtual condition checks position quickly on the line. Specify gauge design ownership and calibration.","tags":["high-volume"],"severity":"minor"},{"id":"tol-insp-5","text":"Restraint conditions are stated for flexible parts (molded shells, sheet metal) where free-state measurement is not meaningful","hint":"Note the fixturing restraint (clamp locations and forces) or use the free-state symbol. Unstated restraint means each lab measures differently.","tags":[],"severity":"major"},{"id":"tol-insp-6","text":"Measurement conditions (temperature, conditioning, time after molding) are specified where they affect results","hint":"Plastics shrink after molding and absorb moisture. State conditioning time and temperature so parts are measured consistently.","tags":["injection-molded"],"severity":"minor"},{"id":"tol-insp-7","text":"Critical-to-function dimensions are flagged for SPC and capability (Cpk) monitoring in production","hint":"Mark CTF dimensions on the drawing with the agreed symbol and state the required Cpk per the quality plan. Agree sampling frequency with the supplier.","tags":["high-volume"],"severity":"major"},{"id":"tol-insp-8","text":"Cosmetic and visual criteria that cannot be measured dimensionally have a defined inspection method","hint":"Specify viewing distance, lighting, time and limit samples. These belong in a cosmetic spec referenced from the drawing.","tags":["cosmetic"],"severity":"minor"},{"id":"tol-insp-9","text":"Inspection data from first articles is reviewed against every CTF dimension before production release","hint":"Check the full dimensional report, not a summary. Out-of-tolerance CTF features need a disposition (rework, deviation or drawing change) before release.","tags":[],"severity":"major"}]}]},{"id":"dfa","title":"Assembly, Fastening & DFA","short":"Assembly","version":1,"description":"Assembly review covering DFA principles, assembly sequence, threaded fasteners, snap fits, adhesives, permanent joints, cables, labeling, serviceability, high-volume assembly and mechanism retention.","sections":[{"id":"asm-prin","title":"DFA Principles","tags":[],"items":[{"id":"asm-prin-1","text":"Every separate part has a reason to exist: it moves relative to its neighbors, must be a different material, or must come apart for service","hint":"Run a Boothroyd-Dewhurst style minimum-part-count test on the BOM. Parts that fail all three criteria are candidates for consolidation.","tags":[],"severity":"major"},{"id":"asm-prin-2","text":"Part consolidation opportunities have been reviewed and the decisions recorded","hint":"List candidate merges (brackets into housings, separate clips into snaps, multi-piece covers) with the tooling cost and risk trade-off. Unreviewed consolidation is the usual source of avoidable assembly labor.","tags":[],"severity":"minor"},{"id":"asm-prin-3","text":"The product assembles predominantly from one direction (top-down / Z-axis) onto a stable base part","hint":"Step through the assembly in CAD and count reorientations of the work in process. Each flip adds handling time and a chance to drop or misalign parts.","tags":[],"severity":"major"},{"id":"asm-prin-4","text":"Each part locates itself on its mating part before fastening (pins, bosses, ribs or lead-ins), with no reliance on the operator holding alignment","hint":"Check that the part is constrained in its final position before the first screw goes in. Parts that float until clamped end up assembled out of position.","tags":[],"severity":"major"},{"id":"asm-prin-5","text":"Mating features have lead-ins (chamfers or radii) so parts guide into place","hint":"Look for square-edged pins, holes and slots that must be aligned by eye. Rule of thumb: lead-ins of about 0.5 mm or more on insertion features, sized to the expected misalignment.","tags":[],"severity":"minor"},{"id":"asm-prin-6","text":"Parts that look similar but are not interchangeable cannot be fitted in the wrong position or orientation (poka-yoke)","hint":"Try to assemble every part rotated 180° or swapped with its look-alike in CAD. Add a keying feature, asymmetric pin pattern or interference so the wrong assembly physically will not go together.","tags":[],"severity":"critical"},{"id":"asm-prin-7","text":"Parts are either fully symmetric about their insertion axis or obviously asymmetric","hint":"Slightly asymmetric parts are the ones that get installed backward. Exaggerate the asymmetry or make the part symmetric so orientation stops mattering.","tags":[],"severity":"major"},{"id":"asm-prin-8","text":"Every fastener and joint has clear access for the specified tool, driver bit and hand during assembly","hint":"Sweep a driver and bit envelope (and a socket, if used) along each fastener axis in CAD with the neighboring parts in place. Check finger and hand clearance for connectors and clips too.","tags":[],"severity":"critical"},{"id":"asm-prin-9","text":"Loose parts do not tangle, nest or stick together when handled or fed in bulk","hint":"Open springs, thin clips, and cups or covers that stack tightly cause line jams and miscounts. Close spring ends, add anti-nesting ribs, or specify tray packaging.","tags":[],"severity":"minor"},{"id":"asm-prin-10","text":"Flexible, fragile or small parts are minimized, and those that remain have a defined handling method","hint":"Tiny or delicate parts (thin films, small springs, sub-M2 screws) need tweezers, fixtures or vision. Note how each will be picked and placed.","tags":[],"severity":"minor"},{"id":"asm-prin-11","text":"Assembly does not depend on adjustment, shimming or selective fitting to meet its requirements","hint":"Adjustments add time, operator skill and a failure mode. If one is unavoidable, it has a documented procedure, a defined range and a lock after setting.","tags":[],"severity":"major"}]},{"id":"asm-seq","title":"Assembly Sequence & Fixturing","tags":[],"items":[{"id":"asm-seq-1","text":"The assembly sequence is documented step by step and matches the CAD assembly structure","hint":"Produce an exploded sequence or assembly-step list and walk it through in CAD. Gaps in the sequence show up as parts that cannot be installed after their neighbors.","tags":[],"severity":"major"},{"id":"asm-seq-2","text":"No part in the sequence is trapped or blocked by a part installed earlier","hint":"Animate or step through the assembly in CAD with collision detection on. A blocked part found at the first build costs a tool change or a redesigned sequence.","tags":[],"severity":"critical"},{"id":"asm-seq-3","text":"Sub-assemblies can be built and functionally tested on their own before final assembly","hint":"Group parts so that, for example, the PCBA with display or the drive train can be tested before closing the housing. Finding a defect after final assembly multiplies rework cost.","tags":[],"severity":"major"},{"id":"asm-seq-4","text":"Required assembly fixtures, nests and jigs are identified and listed with their purpose","hint":"List each fixture with the step it supports and its datum scheme. Fixtures are long-lead items and need to reference the same datums as the drawings.","tags":[],"severity":"minor"},{"id":"asm-seq-5","text":"Sub-assemblies are stable and do not fall apart when handled or moved between stations","hint":"An unfastened stack held together only by gravity will come apart on the line. Add a temporary snap, a first screw or a carrier.","tags":[],"severity":"minor"},{"id":"asm-seq-6","text":"The assembly can be disassembled for rework without damaging parts that must be reused","hint":"Walk through disassembly in reverse. Permanent joints (welds, adhesive, one-way snaps) on high-value parts should be deliberate decisions, not accidents.","tags":[],"severity":"major"},{"id":"asm-seq-7","text":"Critical assembly steps (torque, alignment, bonding, sealing) have an in-process check defined","hint":"Each critical step names how it is verified on the line: torque-monitored driver, go/no-go gauge, vision or functional test.","tags":[],"severity":"major"},{"id":"asm-seq-8","text":"Assembly stack-ups that drive fit or function have been checked across the full tolerance range","hint":"Confirm the assembly analysis exists for gaps, preload and clearances at worst-case and statistical limits. Cross-reference the Tolerancing & GD&T checklist for the analysis itself.","tags":[],"severity":"major"}]},{"id":"asm-thr","title":"Threaded Fasteners","tags":[],"items":[{"id":"asm-thr-1","text":"The number of different fastener sizes, lengths and head styles across the product is minimized","hint":"Tabulate all fasteners from the BOM. Each unique screw is another bit change, feeder, part number and chance of using the wrong one.","tags":[],"severity":"major"},{"id":"asm-thr-2","text":"Fasteners are metric (ISO) sizes unless a documented reason requires otherwise","hint":"Mixing inch and metric fasteners in one product invites cross-threading and wrong-part errors in assembly and service.","tags":[],"severity":"minor"},{"id":"asm-thr-3","text":"Look-alike screws of different lengths are not used in the same assembly where a wrong choice causes damage","hint":"A screw 2 mm too long can punch through a cosmetic wall or a battery cell. Use a distinct diameter or head, or make every location take the same screw.","tags":[],"severity":"critical"},{"id":"asm-thr-4","text":"Thread engagement length suits the internal thread material","hint":"Check engagement against the material and fastener grade so the bolt breaks before the threads strip. Rule of thumb: about 1×d in steel, 1.5×d in cast iron or brass, 2×d or more in aluminum; confirm with a calculation for loaded joints.","tags":[],"severity":"major"},{"id":"asm-thr-6","text":"Thread-forming screws in plastic have a drive torque and strip torque with an adequate margin between them, and the assembly torque sits inside it","hint":"Measure drive and strip torque on molded bosses at the extremes of hole size. Rule of thumb: strip-to-drive ratio of about 3:1 or more for reliable powered driving.","tags":["injection-molded"],"severity":"major"},{"id":"asm-thr-7","text":"Every structural joint has a specified torque derived from the required clamp load","hint":"The torque spec should trace to a clamp-load requirement and a friction (nut factor) assumption, with joint material bearing stress checked. A torque copied from a generic chart is not a design.","tags":[],"severity":"major"},{"id":"asm-thr-8","text":"Joints subject to vibration or thermal cycling have a defined anti-loosening method","hint":"Choose from preload with adequate grip length, thread-locker, prevailing-torque nuts or locking features. Split lock washers alone are not a reliable anti-loosening method.","tags":[],"severity":"major"},{"id":"asm-thr-9","text":"Thread-locker grade, application zone and cure time are specified where thread-locker is used","hint":"Check compatibility with plastics: some anaerobic thread-lockers cause stress cracking in polycarbonate and similar plastics. Note whether the joint must be removable for service.","tags":[],"severity":"major"},{"id":"asm-thr-10","text":"Fastener heads and nuts bearing on soft materials (plastics, soft aluminum, painted surfaces) use washers or flange heads sized to keep bearing stress acceptable","hint":"Compare under-head bearing stress to the material's compressive or creep limit per datasheet. Plastic under a small screw head creeps and loses preload.","tags":[],"severity":"major"},{"id":"asm-thr-11","text":"Fastener and mating materials are galvanically compatible for the environment, or the joint is isolated","hint":"Check the anodic index difference of the pair (e.g. stainless screw in aluminum, steel in magnesium). In wet or salty service use coatings, isolating washers or a compatible fastener.","tags":[],"severity":"major"},{"id":"asm-thr-12","text":"Captive screws or retention features are used wherever a dropped screw could fall into electronics or be lost in service","hint":"Service panels and lids opened by users or field technicians should keep their screws. A loose screw inside a powered product can short a board.","tags":["electronics"],"severity":"major"},{"id":"asm-thr-13","text":"Threaded inserts (heat-set, ultrasonic, press-in or molded-in) have pull-out and torque-out values that exceed the joint loads with margin","hint":"Get pull-out and torque-out from the insert supplier for the specific plastic, then verify on molded parts. Inserts in glass-filled or thin bosses can crack the boss during installation.","tags":[],"severity":"major"},{"id":"asm-thr-14","text":"Self-tapping screws into sheet metal have the correct pilot hole and enough material thickness or an extruded hole for thread engagement","hint":"Thin sheet gives one or two threads; use an extruded (flanged) hole, clinch nut or a thicker gauge. Check the pilot hole against the screw supplier's table.","tags":["sheet-metal"],"severity":"major"},{"id":"asm-thr-15","text":"Clinch nuts, studs and standoffs in sheet metal suit the sheet thickness, hardness and edge distance per the hardware supplier","hint":"Verify minimum sheet thickness, hole size, distance to bends and edges, and that the sheet is softer than the hardware. Wrong hardness means the fastener spins out.","tags":["sheet-metal"],"severity":"major"},{"id":"asm-thr-16","text":"Screw lengths leave clearance at the bottom of blind holes and bosses","hint":"A screw that bottoms out reaches torque without clamping. Check the stack in CAD at maximum screw length and minimum hole depth.","tags":[],"severity":"major"}]},{"id":"asm-snap","title":"Snap Fits & Clips","tags":[],"items":[{"id":"asm-snap-1","text":"Every snap fit has its assembly (insertion) force calculated or measured and within the operator or machine limit","hint":"Calculate from beam deflection, lead-in angle and friction, or measure on prototypes. High insertion forces cause operator fatigue and incomplete engagement.","tags":[],"severity":"major"},{"id":"asm-snap-2","text":"Every snap fit has a retention force that meets the requirement, including drop and handling loads","hint":"Calculate or test retention force at the return angle; a 90° return is usually permanent. Check retention after the snap has aged at maximum temperature.","tags":[],"severity":"major"},{"id":"asm-snap-3","text":"Snap fit strain during assembly stays below the material's allowable strain per datasheet, including at worst-case tolerance","hint":"Use the maximum interference from the tolerance stack, not nominal. Reduce allowable strain for glass-filled grades and for snaps assembled more than once.","tags":[],"severity":"critical"},{"id":"asm-snap-4","text":"Snaps that must release for service have a defined release method that does not require breaking parts","hint":"Provide a release slot, a tool access point or a ramped return. Show the service tool and its access in CAD.","tags":[],"severity":"major"},{"id":"asm-snap-5","text":"Snaps designed to be reused are rated for the required number of assembly cycles","hint":"Allowable strain for repeated cycles is lower than for one-time assembly. Cycle-test prototypes in the production material.","tags":[],"severity":"minor"},{"id":"asm-snap-7","text":"Snap fits do not stay deflected (preloaded) in the assembled state unless the material creep has been accounted for","hint":"A snap held under strain relaxes over time, especially at elevated temperature. Design for zero deflection once seated or check creep data per datasheet.","tags":[],"severity":"major"},{"id":"asm-snap-8","text":"Engagement of each snap can be confirmed by the assembler (audible click, visual flush, or a check feature)","hint":"A half-engaged snap passes assembly and fails in the field. Add a flush indicator or a gap that is visible only when not seated.","tags":[],"severity":"minor"},{"id":"asm-snap-9","text":"Metal spring clips and retaining rings have groove dimensions and installation tools specified per the supplier","hint":"Check groove diameter, width and edge radius against the supplier catalog, and that the installation tool fits in the space available.","tags":[],"severity":"minor"}]},{"id":"asm-adh","title":"Adhesives & Tapes","tags":[],"items":[{"id":"asm-adh-1","text":"The adhesive or tape is qualified for the surface energy of both substrates","hint":"Low-surface-energy plastics (PP, PE, POM, some TPEs, silicone) need a specific adhesive, primer or surface treatment. Check the adhesive supplier's substrate compatibility data.","tags":[],"severity":"critical"},{"id":"asm-adh-2","text":"Surface preparation (cleaning, abrading, plasma, flame or primer) is specified and practical on the production line","hint":"Bond strength depends more on surface prep than on the adhesive. Specify the solvent or treatment, the time window to bonding, and how it is verified (e.g. dyne pens).","tags":[],"severity":"major"},{"id":"asm-adh-3","text":"Mold release agents and contamination from upstream processes are controlled on bonded surfaces","hint":"Silicone release agents and finger oils kill adhesion. Agree release-agent-free molding or a cleaning step with the molder for bonded parts.","tags":[],"severity":"major"},{"id":"asm-adh-4","text":"Liquid adhesive bond line thickness is controlled by design (stand-offs, beads or spacer features)","hint":"Without a controlled gap the bond line varies from starved to thick. Use the adhesive supplier's recommended bond line range and add features to set it.","tags":[],"severity":"major"},{"id":"asm-adh-5","text":"Adhesive cure time, temperature and fixture time fit the production cycle, and handling strength is reached before the next step","hint":"Check the supplier's cure profile. Moving parts before handling strength causes misaligned or weakened bonds.","tags":[],"severity":"major"},{"id":"asm-adh-6","text":"Pressure-sensitive adhesive joints have specified application pressure and dwell time","hint":"PSA strength builds with pressure and time. Specify roller or press pressure and dwell, and the time before load is applied, per the tape supplier.","tags":[],"severity":"major"},{"id":"asm-adh-7","text":"Adhesive and tape are rated for the full operating and storage temperature range, humidity and chemical exposure","hint":"Compare service temperature, humidity and cleaning agents against the supplier data. PSAs soften and creep at elevated temperature.","tags":[],"severity":"major"},{"id":"asm-adh-8","text":"Bonded joints are loaded in shear or compression, not peel or cleavage","hint":"Adhesive peel strength is a small fraction of its shear strength. Add geometry so the load path avoids peel at bond edges.","tags":[],"severity":"major"},{"id":"asm-adh-9","text":"Adhesive or tape geometry (die-cut shape, bead path) is fully defined on a drawing","hint":"Die-cut tape needs a drawing with liner tabs and tolerances; dispensed beads need path, bead size and start/stop points.","tags":[],"severity":"minor"},{"id":"asm-adh-10","text":"Bonded parts can be reworked or serviced where required, or the joint is intentionally permanent","hint":"Decide whether the bond must be separable (pull-tab adhesive strips, heat-release tape) and document the decision.","tags":[],"severity":"minor"},{"id":"asm-adh-11","text":"Adhesive outgassing, corrosivity and compatibility with nearby electronics and optics are checked","hint":"Acetoxy-cure silicones release acetic acid that corrodes copper; some adhesives fog lenses. Use neutral-cure or low-outgassing grades near electronics or optics.","tags":["electronics"],"severity":"major"}]},{"id":"asm-join","title":"Welding, Staking, Riveting & Press Fits","tags":[],"items":[{"id":"asm-join-1","text":"Ultrasonic weld joints use a joint design (energy director, shear joint) suited to the plastic and the welding supplier's recommendations","hint":"Amorphous plastics weld well with energy directors; semi-crystalline plastics usually need shear joints. Review the joint with the welding equipment supplier before tool release.","tags":["injection-molded"],"severity":"major"},{"id":"asm-join-2","text":"Ultrasonic or other plastic weld joints have flash traps or are hidden where flash would be visible or interfere","hint":"Weld flash on cosmetic or sealing surfaces is a frequent first-article rejection. Add flash traps or move the joint.","tags":["injection-molded"],"severity":"minor"},{"id":"asm-join-3","text":"Ultrasonically welded assemblies keep sensitive components away from horn energy or have been tested for damage","hint":"Ultrasonic energy can crack crystal oscillators, MEMS sensors and solder joints. Test welded PCBAs functionally after welding.","tags":["electronics"],"severity":"major"},{"id":"asm-join-4","text":"Heat-stake and cold-stake boss geometry follows the staking equipment supplier's guide for boss diameter, height and head form","hint":"Check that boss height leaves enough material to form the head and that the head clamps the part without cracking. Verify pull-off strength on samples.","tags":["injection-molded"],"severity":"minor"},{"id":"asm-join-5","text":"Rivet grip range matches the actual material stack, and hole sizes and edge distances follow the rivet supplier's guide","hint":"Check the stack at minimum and maximum tolerance. Blind rivets into plastics or thin sheet may need a large-flange or soft-set style.","tags":[],"severity":"major"},{"id":"asm-join-6","text":"Press-fit interference, assembly force and retention force have been calculated across the tolerance range","hint":"Compute hoop stress at maximum interference and retention at minimum interference. Check the press force against the available press and the part's strength.","tags":[],"severity":"critical"},{"id":"asm-join-7","text":"Press fits into plastic account for creep and stress relaxation over the product life and temperature range","hint":"Plastic hubs relax and lose retention, especially when hot. Use knurls, ribs (crush ribs) or a metal insert, and check against creep data per datasheet.","tags":["injection-molded"],"severity":"major"},{"id":"asm-join-8","text":"Pressed and welded joints have a pass/fail criterion that can be checked in production (force-displacement window, weld depth, or pull test)","hint":"Monitor press force or displacement or weld collapse on the line. An unmonitored permanent joint cannot be screened for bad parts.","tags":["high-volume"],"severity":"major"}]},{"id":"asm-cbl","title":"Cables & Harnesses","tags":["electronics"],"items":[{"id":"asm-cbl-1","text":"Every cable and harness has a defined route in CAD with its retention points modeled","hint":"Model cables at real diameter and minimum bend radius. A cable left out of CAD ends up pinched or forced into space that does not exist.","tags":[],"severity":"major"},{"id":"asm-cbl-2","text":"Cable bend radius stays at or above the cable or FPC supplier's minimum at every bend, including dynamic bends","hint":"Check flex and FPC bends against the supplier's static and dynamic bend radius. FPCs that flex in use need a dynamic-rated construction.","tags":[],"severity":"major"},{"id":"asm-cbl-3","text":"Cables cannot be pinched between mating housings, fasteners or moving parts during assembly or in use","hint":"Check closing gaps and screw paths along the cable route. Pinched cables fail intermittently and are a common field return.","tags":[],"severity":"critical"},{"id":"asm-cbl-4","text":"Cables are retained so they cannot migrate onto hot, sharp or moving parts","hint":"Use clips, guides, tape or tie points. Check sheet-metal edges along the route are deburred or protected with grommets.","tags":[],"severity":"major"},{"id":"asm-cbl-5","text":"Strain relief is provided so that pulls on external cables do not load solder joints, crimps or connectors","hint":"Pull on the external cable in the design review and trace the load path. It should end in the housing, not at the PCB.","tags":[],"severity":"critical"},{"id":"asm-cbl-6","text":"Connectors can be mated and unmated with the required hand or tool access in the assembly sequence","hint":"Check that board-to-board and cable connectors can be seated with a straight push and inspected, and that latches can be released for service.","tags":[],"severity":"major"},{"id":"asm-cbl-7","text":"Connector mating is verifiable (latch click, full-seat feature or test) and cannot be mis-mated with a similar connector nearby","hint":"Use different keying, pin counts or colors for adjacent identical connectors. A partly seated connector passes initial test and fails after shipping.","tags":[],"severity":"major"},{"id":"asm-cbl-8","text":"Cable lengths have slack for assembly and service but not so much excess that it must be stuffed into the housing","hint":"Check the cable length with the housing open in the service position and closed. Excess loops press on components and block air flow.","tags":[],"severity":"minor"},{"id":"asm-cbl-9","text":"Grounding connections to the chassis (bonding straps, ring terminals, grounding screws) have a defined assembly step and contact method","hint":"Specify star washers, thread-cutting screws or clean contact areas so the bond is made reliably. Coordinate the electrical requirement with EE.","tags":[],"severity":"major"},{"id":"asm-cbl-10","text":"Wire and cable insulation is protected where it passes through holes or over edges","hint":"Grommets, edge trim or rolled edges on every pass-through. Bare sheet-metal edges cut insulation under vibration.","tags":[],"severity":"major"}]},{"id":"asm-lbl","title":"Labels & Marking","tags":[],"items":[{"id":"asm-lbl-1","text":"Every required label has a defined location, size and flat area that is accessible after assembly","hint":"Place the rating label, serial number and regulatory marks on a flat, unobstructed surface. Check visibility in the installed orientation.","tags":[],"severity":"minor"},{"id":"asm-lbl-2","text":"Label materials and adhesives suit the substrate and the environment for the product life","hint":"Check abrasion, cleaning agents, UV and temperature against the label supplier's data. Regulatory labels must remain legible for the product life.","tags":[],"severity":"major"},{"id":"asm-lbl-3","text":"Parts that look alike carry an identifying mark (part number, cavity number, material code) molded or marked in a non-cosmetic area","hint":"Part and material identification supports traceability and recycling. Include cavity identification for multi-cavity molds.","tags":[],"severity":"minor"},{"id":"asm-lbl-4","text":"Traceability marking (serial, date code or lot) is defined for parts and sub-assemblies that require it","hint":"Define what is marked, by what method (laser, label, mold date wheel) and where it is recorded. Medical and regulated products usually require this.","tags":["medical","regulatory"],"severity":"major"},{"id":"asm-lbl-5","text":"Assembly orientation aids (arrows, alignment marks, color codes) are added where orientation is not obvious","hint":"Use these in addition to poka-yoke features, not as a substitute for them.","tags":[],"severity":"minor"}]},{"id":"asm-svc","title":"Service & Repair","tags":[],"items":[{"id":"asm-svc-1","text":"Parts expected to fail or wear can be reached and replaced without disassembling unrelated parts","hint":"Rank parts by expected failure rate and count the steps to replace each. High-failure parts behind many others drive service cost.","tags":[],"severity":"major"},{"id":"asm-svc-2","text":"Consumable parts (filters, seals, batteries, brushes, blades) are replaceable by the intended user or technician with the intended tools","hint":"Check the replacement procedure against the user profile: no special tools for end users, defined tools for technicians.","tags":[],"severity":"major"},{"id":"asm-svc-3","text":"Whether the battery is user-replaceable, service-replaceable or not replaceable is a deliberate decision consistent with regulations in the target markets","hint":"Some markets require user-removable or replaceable portable batteries. Confirm the requirement with regulatory and record the decision.","tags":["battery-pack"],"severity":"major"},{"id":"asm-svc-4","text":"Battery disconnection or removal is possible before other service work where stored energy creates a hazard","hint":"Service steps should isolate the battery early. Check that the connector or tabs can be reached without passing tools across live conductors.","tags":["battery-pack"],"severity":"critical"},{"id":"asm-svc-5","text":"Service access does not require breaking seals, cosmetic parts or permanent joints that cannot be restored","hint":"If opening the product destroys a gasket, label or adhesive bond, the service kit and procedure must include its replacement.","tags":[],"severity":"major"},{"id":"asm-svc-6","text":"Fasteners used for service access are standard drives that the service organization has, or the special drive is a deliberate tamper-resistance decision","hint":"Security drives deter users but must be in the service toolkit. Record the decision.","tags":[],"severity":"minor"},{"id":"asm-svc-7","text":"Service-replaceable parts are keyed or identified so that the correct part is fitted after repair","hint":"Field technicians lack factory fixtures and work instructions. Keying and clear marking prevent wrong-part or wrong-orientation repairs.","tags":[],"severity":"minor"}]},{"id":"asm-vol","title":"High-Volume Assembly","tags":["high-volume"],"items":[{"id":"asm-vol-1","text":"Assembly time is estimated for each step and the total meets the cost target","hint":"Use a DFA time estimate or line study per step. Compare the total against the labor cost assumption in the business case.","tags":[],"severity":"major"},{"id":"asm-vol-2","text":"Parts intended for automated feeding or pick-and-place have consistent orientation features and gripper surfaces","hint":"Confirm with the automation integrator that each part can be fed (bowl, tray, tape) and gripped. Flat, featureless or tangled parts block automation.","tags":[],"severity":"major"},{"id":"asm-vol-3","text":"Fasteners intended for automatic feeding are compatible with the feeder (head geometry, length-to-head ratio)","hint":"Short screws with large heads, or very small screws, may not feed reliably. Confirm with the feeder supplier.","tags":[],"severity":"minor"},{"id":"asm-vol-4","text":"Parts are packaged and delivered to the line in an orientation that avoids extra handling","hint":"Specify trays, tape or kits for parts that are damaged or slow to orient from bulk. Include packaging in the supplier quotation.","tags":[],"severity":"minor"},{"id":"asm-vol-5","text":"Station count and line balance are planned so that no single step limits throughput","hint":"Identify the longest step (often cure, test or welding) and plan parallel stations or a different method.","tags":[],"severity":"minor"},{"id":"asm-vol-6","text":"End-of-line test coverage is defined for the functions the assembly process can affect","hint":"List the assembly-induced failure modes (missed fastener, unseated connector, leak) and map each to a test that detects it.","tags":[],"severity":"major"}]},{"id":"asm-mov","title":"Moving Parts & Mechanisms","tags":["moving-parts"],"items":[{"id":"asm-mov-1","text":"Bearings and bushings are axially and radially retained in their housings by a defined method (shoulder, retaining ring, press fit or adhesive)","hint":"Check that axial loads in both directions have a path to the housing. Bearings retained only by friction walk out under load or thermal cycling.","tags":[],"severity":"critical"},{"id":"asm-mov-2","text":"Bearing and bushing fits on shafts and housings follow the bearing supplier's recommended fit for the load case","hint":"Rotating inner ring loads usually need interference on the shaft; check the supplier's table. Wrong fits cause creep, fretting or lost clearance.","tags":[],"severity":"major"},{"id":"asm-mov-3","text":"Lubricant type and quantity are specified for every lubricated interface and are compatible with the adjacent plastics and elastomers","hint":"Some greases and oils swell elastomers or stress-crack plastics. Specify the grease by product name, amount and application area.","tags":[],"severity":"major"},{"id":"asm-mov-4","text":"Lubricant application is a controlled step (dispensed amount, location) in the assembly sequence","hint":"Hand-applied grease varies widely. Specify the dispensing method and how the amount is verified.","tags":[],"severity":"minor"},{"id":"asm-mov-5","text":"Shaft end-play and axial position are controlled by design within a specified range","hint":"Check the axial stack across tolerance. Too little end-play binds when hot; too much causes noise and gear misalignment.","tags":[],"severity":"major"},{"id":"asm-mov-6","text":"Springs are captive so they cannot escape during assembly, service or failure","hint":"Use spring seats, posts or pockets. A loose spring is a launch hazard during service and a lost part on the line.","tags":[],"severity":"major"},{"id":"asm-mov-7","text":"Springs are preloaded during assembly in a way that does not require the operator to hold them compressed","hint":"Use a fixture, a ramp or an assembly order that compresses the spring as parts close. Operators holding springs leads to slips and injuries.","tags":[],"severity":"minor"},{"id":"asm-mov-8","text":"Hinge pins, pivots and slides have defined retention and wear surfaces suited to the required cycle life","hint":"Check retention of the pin (head, ring, stake) and the wear pair materials. Cross-reference the validation plan for cycle testing.","tags":[],"severity":"major"},{"id":"asm-mov-9","text":"Moving parts have clearance to adjacent parts and cables through their full range of motion","hint":"Run a motion study or check interference at the travel extremes, including tolerances and part deflection under load.","tags":[],"severity":"critical"}]}]},{"id":"materials","title":"Materials & Finishes","short":"Materials","version":1,"description":"Material selection, plastics, metals, elastomers, finishes and coatings, compliance, contact materials, sustainability and outdoor durability.","sections":[{"id":"mat-sel","title":"Material Selection","tags":[],"items":[{"id":"mat-sel-1","text":"Every part has its material chosen against written requirements for strength, stiffness and operating temperature range","hint":"Trace each part's material back to the requirements list and load cases. A material picked by habit is the usual root cause of creep, cracking or softening found late in validation.","tags":[],"severity":"major"},{"id":"mat-sel-2","text":"Every part specifies a specific grade (manufacturer and grade name), not a generic family like \"ABS\" or \"aluminum\"","hint":"Check the drawing, BOM and CAD material field. Properties within one family vary widely, and a generic callout lets the supplier substitute whatever is cheapest.","tags":[],"severity":"critical"},{"id":"mat-sel-3","text":"Properties used for design are taken from the datasheet at the maximum operating temperature, not at 23 °C","hint":"Look for modulus, yield and HDT versus temperature curves (e.g. on Campus or the supplier's data). Plastics can lose a large share of their stiffness well below their HDT.","tags":[],"severity":"major"},{"id":"mat-sel-4","text":"Parts under sustained load have a material with documented creep or stress-relaxation behavior at the operating temperature","hint":"Ask for creep modulus or isochronous stress-strain data from the supplier. Bosses, press fits and clips under constant load are the usual victims.","tags":[],"severity":"major"},{"id":"mat-sel-5","text":"Chemical exposure (cleaners, disinfectants, oils, sunscreen, fuels, process fluids) is listed and every exposed material is rated for it","hint":"Build the list from the use environment and cleaning instructions, then check the supplier's chemical resistance table for each pair. Mark any untested pair for an immersion or strain test.","tags":[],"severity":"major"},{"id":"mat-sel-6","text":"Flammability requirement is identified and every part that needs it uses a material with the matching rating","hint":"Check the product safety standard for which parts must be flame rated (enclosures, parts near ignition sources). Cross-check with the compliance engineer before tooling.","tags":["regulatory","electronics"],"severity":"critical"},{"id":"mat-sel-7","text":"UV and light exposure is considered for every exposed part, including indoor exposure near windows or lighting","hint":"Unstabilized polymers yellow, chalk and embrittle. Check the datasheet for UV stabilization or plan a weathering test.","tags":[],"severity":"minor"},{"id":"mat-sel-8","text":"Every specified material is available from stock or with a confirmed lead time in the production region","hint":"Confirm with the molder, machine shop or distributor before release. Specialty grades and colors can carry long minimum order quantities and lead times.","tags":["high-volume"],"severity":"major"},{"id":"mat-sel-9","text":"Critical materials have an approved second source or an equivalent grade validated in advance","hint":"Record the alternate grade in the BOM with its approval status. Switching grades after a shortage without retesting is a common cause of field failures.","tags":["high-volume"],"severity":"major"},{"id":"mat-sel-10","text":"Material cost per part is estimated and fits the cost target","hint":"Use part volume or mass, scrap or runner allowance and current price per kg from the supplier. Flame-retardant, glass-filled and high-performance grades can change the part cost significantly.","tags":[],"severity":"minor"},{"id":"mat-sel-11","text":"Density and resulting part mass are entered in CAD and the total mass meets the product requirement","hint":"Assign the real material to every part in CAD and check the mass report against the weight budget. Default CAD densities make mass rollups meaningless.","tags":[],"severity":"minor"},{"id":"mat-sel-12","text":"Material choices are recorded in a materials list with grade, supplier, color, finish and the reason for selection","hint":"One table per product, kept with the design record. It speeds up compliance declarations and later substitutions.","tags":[],"severity":"minor"}]},{"id":"mat-pl","title":"Plastics","tags":["injection-molded","additive"],"items":[{"id":"mat-pl-1","text":"Resin grade and color are called out together as one orderable specification (grade plus color code)","hint":"A color code without a base grade, or a grade without a color, gets interpreted differently by each molder. Check the drawing title block and notes.","tags":[],"severity":"major"},{"id":"mat-pl-2","text":"Effects of glass or mineral fill on anisotropy, warpage and weld line strength are accounted for in the design","hint":"Filled grades have much lower strength across the flow direction and at weld lines. Review the gate location and mold flow fiber orientation results for loaded features.","tags":["injection-molded"],"severity":"major"},{"id":"mat-pl-3","text":"Moisture absorption is accounted for in dimensions and properties for hygroscopic resins such as nylon","hint":"Nylon grows and softens as it conditions to ambient humidity. Use conditioned properties from the datasheet and check fits in both dry-as-molded and conditioned states.","tags":[],"severity":"major"},{"id":"mat-pl-4","text":"Parts that see chemicals while under molded-in or assembly stress are checked for environmental stress cracking","hint":"Amorphous resins (PC, ABS, PC/ABS, acrylic) crack with cleaners, alcohols, oils and adhesives under strain. Use a strain jig or bent-strip test with the actual chemicals and the expected strain.","tags":[],"severity":"critical"},{"id":"mat-pl-5","text":"Regrind policy (allowed or not, maximum percentage) is stated on the drawing or in the supply agreement","hint":"Regrind lowers impact and flame performance. Medical, flame-rated and highly loaded parts usually forbid it or cap it per the material supplier's guidance.","tags":["injection-molded"],"severity":"major"},{"id":"mat-pl-6","text":"Colorant or masterbatch is confirmed not to degrade the required mechanical, flame or regulatory properties","hint":"Some pigments and carriers reduce impact strength or void a UL listing. Use a precolored compound listed by the supplier, or get the colorant approved in writing.","tags":["injection-molded"],"severity":"major"},{"id":"mat-pl-7","text":"UL 94 rating is verified at the actual minimum wall thickness and in the actual color of the part","hint":"UL Yellow Cards list ratings per thickness and sometimes per color. A rating at 3 mm does not cover a 1.5 mm wall; check the thinnest section in CAD against the card.","tags":["regulatory"],"severity":"critical"},{"id":"mat-pl-8","text":"Drying requirements of the resin are passed to the molder in the material specification","hint":"Undried PC, PBT, PET and nylon hydrolyze during molding and become brittle with no visible defect. Reference the supplier's drying temperature and time.","tags":["injection-molded"],"severity":"minor"},{"id":"mat-pl-9","text":"Temperature limits use the right property (HDT, RTI or Vicat) for the kind of exposure","hint":"HDT is a short-term deflection value, not a continuous use limit. For long-term elevated temperature use the relative thermal index or supplier aging data.","tags":[],"severity":"major"},{"id":"mat-pl-10","text":"Material for living hinges, snap fits and press fits has enough elongation at yield for the design strain","hint":"Check allowable strain from the datasheet or supplier guidance for the specific grade. Glass-filled and amorphous brittle grades often cannot survive repeated deflection.","tags":["moving-parts"],"severity":"major"},{"id":"mat-pl-11","text":"Overmold and two-shot material pairs are confirmed compatible for adhesion by the material supplier","hint":"TPE and LSR bond only to specific substrates. Get the supplier's compatibility chart or a peel test; otherwise design mechanical interlocks.","tags":["injection-molded","elastomer"],"severity":"major"},{"id":"mat-pl-12","text":"Additive parts specify process, material, build orientation and post-processing","hint":"SLS, MJF, SLA and FDM parts are anisotropic and orientation sensitive. Put the orientation and post-cure or annealing on the drawing or build sheet.","tags":["additive"],"severity":"major"},{"id":"mat-pl-13","text":"Properties of additive materials used for design come from the printing vendor's data for the specific process and machine","hint":"Generic datasheet values often overstate z-direction strength. Ask the service bureau for tested values or test coupons in the build orientation.","tags":["additive"],"severity":"minor"},{"id":"mat-pl-14","text":"Transparent or light-pipe parts use an optical grade with defined transmission, haze and color stability","hint":"Check the light transmission and yellowing index data in the datasheet. General-purpose grades of PC or acrylic can yellow and cloud over time.","tags":["electronics"],"severity":"minor"}]},{"id":"mat-met","title":"Metals","tags":["machined","sheet-metal","cast","extruded"],"items":[{"id":"mat-met-1","text":"Every metal part specifies alloy and temper or condition (e.g. 6061-T6, 304 annealed, 1/4 hard)","hint":"Temper drives yield strength, formability and machinability. A missing temper on the drawing lets the supplier ship the softest condition.","tags":[],"severity":"critical"},{"id":"mat-met-2","text":"Sheet-metal alloy and temper are confirmed formable to the bend radii in the design","hint":"Hard tempers and some aluminum alloys crack on tight bends. Check minimum bend radius against the supplier's or material standard's table for that temper and thickness.","tags":["sheet-metal"],"severity":"major"},{"id":"mat-met-3","text":"Every pair of dissimilar metals in contact is checked for galvanic corrosion in the expected environment","hint":"Use a galvanic series chart for the electrolyte (moisture, salt). Isolate with coatings, washers or sealant, or keep the anode area large relative to the cathode.","tags":[],"severity":"major"},{"id":"mat-met-4","text":"Stainless steel grade is chosen for the actual environment (e.g. 316 for chloride or marine exposure instead of 303 or 304)","hint":"Free-machining 303 and 400-series grades corrode much faster in chlorides. Check the corrosion requirement and cleaning chemicals.","tags":[],"severity":"major"},{"id":"mat-met-6","text":"Carbon and alloy steel parts have a defined corrosion protection","hint":"Bare steel rusts in storage and transport. Check the drawing for plating, coating or oil, and that it suits the environment.","tags":[],"severity":"major"},{"id":"mat-met-7","text":"Magnetic properties are checked where parts are near magnets, sensors, compasses or MRI","hint":"Austenitic stainless becomes partly magnetic after cold work or forming. Specify a low-permeability grade or annealing if it matters.","tags":["electronics","medical"],"severity":"minor"},{"id":"mat-met-8","text":"Die-cast alloy is chosen for the required ductility, corrosion resistance and finish","hint":"Common die-cast aluminum alloys trade ductility for castability, and porosity can affect plating, anodizing and pressure tightness. Confirm with the caster.","tags":["cast"],"severity":"major"},{"id":"mat-met-9","text":"Extrusion alloy and temper are confirmed with the extruder for the profile shape and finish","hint":"Some alloys anodize poorly or show die lines. Ask the extruder which alloy suits the profile and the cosmetic requirement.","tags":["extruded"],"severity":"minor"},{"id":"mat-met-10","text":"Weldable alloy and filler compatibility are confirmed for every welded joint","hint":"Some high-strength aluminum alloys are poorly weldable and lose temper in the heat-affected zone. Use the welded properties in analysis.","tags":["structural"],"severity":"major"},{"id":"mat-met-11","text":"Spring materials (spring steel, stainless spring temper, music wire) are specified with temper and fatigue suitability","hint":"Check the spring supplier's guidance for the stress level and cycle count. Relaxation at elevated temperature is a common failure.","tags":["moving-parts"],"severity":"major"}]},{"id":"mat-elas","title":"Elastomers","tags":["elastomer"],"items":[{"id":"mat-elas-1","text":"Elastomer compound is selected for compatibility with every fluid, lubricant and cleaner it contacts","hint":"Check the compound's chemical compatibility chart (EPDM swells in oils, NBR degrades with ozone and UV). Lubricants used during assembly count too.","tags":[],"severity":"critical"},{"id":"mat-elas-2","text":"Elastomer compound is rated for the full operating and storage temperature range","hint":"Check both ends: low-temperature stiffening (TR10 or brittleness point) and high-temperature aging in the datasheet.","tags":[],"severity":"major"},{"id":"mat-elas-3","text":"Compression set at the operating temperature is acceptable for the sealing or preload function over the product life","hint":"Use compression set data at the right temperature and duration from the supplier. A gasket that takes a permanent set loses its seal.","tags":["sealed-ip"],"severity":"major"},{"id":"mat-elas-4","text":"Durometer is specified with a tolerance consistent with supplier capability","hint":"Rule of thumb: ±5 Shore A is a common supplier tolerance. Make sure the design still works at both ends of the range.","tags":[],"severity":"minor"},{"id":"mat-elas-5","text":"Elastomer compound is specified by compound name or supplier part number, not only by polymer and durometer","hint":"\"70A silicone\" can be many different compounds. Specify the compound or a material standard callout and require change notification.","tags":[],"severity":"major"},{"id":"mat-elas-6","text":"Keypad, grip and skin-contact elastomers are checked for tackiness, plasticizer migration and staining","hint":"Some TPEs bleed oils that mark adjacent plastics or feel sticky after heat aging. Ask for heat-aging data or run a contact stain test.","tags":["cosmetic","handheld"],"severity":"minor"},{"id":"mat-elas-7","text":"Elastomer is confirmed suitable for its ozone and UV exposure","hint":"Diene rubbers (NR, NBR, SBR) crack under ozone and UV. Silicone, EPDM and fluoroelastomers resist it better.","tags":["outdoor"],"severity":"major"}]},{"id":"mat-fin","title":"Finishes & Coatings","tags":[],"items":[{"id":"mat-fin-1","text":"Anodize is specified with type, class or color, and thickness range","hint":"Name the anodize type (e.g. sulfuric or hard coat), dye or clear, and thickness per the finisher's capability. An unspecified anodize gives inconsistent color and wear.","tags":["machined","sheet-metal","extruded","cast"],"severity":"major"},{"id":"mat-fin-2","text":"Dimensional growth of anodize, plating or coating is included in fits and tolerances","hint":"Anodize grows partly outward per surface, and hard anodize much more. State whether dimensions apply before or after finishing on the drawing.","tags":[],"severity":"critical"},{"id":"mat-fin-3","text":"Masking areas are defined on the drawing for threads, bores, grounding points and mating faces that must stay bare","hint":"Show masking with a hatch or callout in a drawing view. Unmasked threads and fits are a common rework item after first finishing.","tags":[],"severity":"major"},{"id":"mat-fin-4","text":"Plating type and thickness are specified and suit the base metal and environment","hint":"Specify the plating (zinc, nickel, tin) with thickness and any post-treatment per the plater's capability. Check hydrogen embrittlement relief for high-strength steels.","tags":["machined","sheet-metal","cast"],"severity":"major"},{"id":"mat-fin-5","text":"Powder coat or paint thickness is accounted for at fits, holes and threaded features","hint":"Powder coat is thick and builds up at edges. Mask or oversize mating features and check stack-ups with the coating thickness per the coater's capability.","tags":["sheet-metal","cast","extruded"],"severity":"major"},{"id":"mat-fin-6","text":"Paint or coating adhesion is specified with a test method and acceptance level","hint":"Reference a cross-hatch or tape adhesion test and the required rating in the finish specification. Plastics often need a primer or surface treatment.","tags":["cosmetic"],"severity":"major"},{"id":"mat-fin-7","text":"Stainless steel parts are passivated after machining or forming where corrosion resistance matters","hint":"Free iron from tooling causes rust spots. Call out passivation and the method per the finisher's standard practice.","tags":["machined","sheet-metal"],"severity":"minor"},{"id":"mat-fin-8","text":"Grounding and bonding points have a conductive finish or a defined bare area","hint":"Anodize, powder coat and paint are insulators. Use conductive chromate conversion, mask the contact area, or use a star washer, and verify resistance on the prototype.","tags":["electronics"],"severity":"critical"},{"id":"mat-fin-9","text":"Shielding coatings (conductive paint, plating on plastic) are specified with surface resistance and coverage area","hint":"Coordinate with the EE on the resistance requirement and the contact points to the PCB ground.","tags":["electronics"],"severity":"major"},{"id":"mat-fin-10","text":"PVD or other decorative hard coatings are specified with color, thickness and substrate preparation","hint":"PVD replicates the substrate finish exactly, so polishing or blasting must be specified first. Confirm the wear and adhesion test with the supplier.","tags":["cosmetic"],"severity":"minor"},{"id":"mat-fin-11","text":"Mold texture is specified by texture supplier reference and checked against draft on every textured face","hint":"Each texture needs a minimum draft angle per the texture supplier. Insufficient draft drags the texture and scuffs the part, and fixing it means retexturing the tool.","tags":["injection-molded","cosmetic"],"severity":"major"},{"id":"mat-fin-12","text":"Pad printing, screen printing and laser marking are specified with the durability test they must pass","hint":"Define abrasion, chemical rub (e.g. alcohol or cleaners) and adhesion tests in the artwork specification. Laser marking needs a laser-markable grade or additive.","tags":[],"severity":"minor"},{"id":"mat-fin-13","text":"Colors are specified against a named standard (Pantone, RAL, NCS) or a physical color master with tolerance","hint":"Specify the measurement method, light source and allowed delta E. On-screen color is not a specification.","tags":["cosmetic"],"severity":"major"},{"id":"mat-fin-14","text":"Approved color and finish samples (boundary samples) exist and are held by both Dovetail and the supplier","hint":"Keep signed master and limit samples for color, gloss and texture. Without them cosmetic disputes at production start have no reference.","tags":["cosmetic"],"severity":"minor"},{"id":"mat-fin-15","text":"Gloss level is specified with a measurement angle and range for cosmetic surfaces","hint":"Gloss mismatch between parts from different processes (molded, painted, metal) is very visible. Specify gloss units at a stated angle.","tags":["cosmetic"],"severity":"minor"},{"id":"mat-fin-16","text":"Finish process is compatible with the base material temperature limits and part geometry","hint":"Powder curing, PVD and some plating processes run hot or need racking points. Confirm with the finisher that the part will not distort or soften.","tags":[],"severity":"major"}]},{"id":"mat-comp","title":"Compliance & Declarations","tags":["regulatory"],"items":[{"id":"mat-comp-1","text":"Every material and finish is confirmed RoHS compliant with a supplier declaration on file","hint":"Collect declarations for each part number, including coatings, inks and adhesives. Hexavalent chromate conversion coatings and leaded brass are common misses.","tags":[],"severity":"critical"},{"id":"mat-comp-2","text":"REACH SVHC content is checked against the current candidate list for every article","hint":"The candidate list is updated regularly. Request SVHC declarations from suppliers and re-check before each release.","tags":[],"severity":"major"},{"id":"mat-comp-3","text":"California Proposition 65 exposure is assessed where the product is sold in California","hint":"Common triggers include certain plasticizers, flame retardants and lead in brass. Decide on warning labels or substitution early.","tags":[],"severity":"major"},{"id":"mat-comp-4","text":"Conflict minerals (tin, tantalum, tungsten, gold) reporting needs are identified and supplier data is requested","hint":"Use the customer's reporting template and collect supplier responses before production start.","tags":[],"severity":"minor"},{"id":"mat-comp-5","text":"Material declarations (full or IPC-1752 style) are requested from suppliers for every purchased and custom part","hint":"Make declarations a deliverable in the supplier quote request. Chasing them after launch delays certification and customer audits.","tags":[],"severity":"major"},{"id":"mat-comp-6","text":"Restricted substance requirements from the customer or target markets are listed and checked","hint":"Customers often have their own restricted substance lists beyond RoHS and REACH (e.g. PFAS, halogens). Check them before material selection is final.","tags":[],"severity":"major"},{"id":"mat-comp-7","text":"Flame-retardant additives in chosen grades are compatible with halogen-free or restricted substance requirements","hint":"Brominated flame retardants may be restricted by customer specs. Check the grade's composition statement.","tags":["electronics"],"severity":"minor"},{"id":"mat-comp-8","text":"Materials used in safety-critical parts are on the certification body's accepted component list or have the required listing","hint":"Enclosure plastics usually need a UL-recognized grade; a substitute grade often triggers retesting. Record the file number.","tags":[],"severity":"critical"}]},{"id":"mat-bio","title":"Skin & Patient Contact","tags":["medical","wearable"],"items":[{"id":"mat-bio-1","text":"Every skin- or patient-contact material is identified with its contact type and duration","hint":"Classify contact per ISO 10993-1 (surface, external communicating, implant) and duration. This drives the biocompatibility test plan.","tags":[],"severity":"critical"},{"id":"mat-bio-2","text":"Biocompatibility evidence per ISO 10993 exists or is planned for every contact material in its final processed form","hint":"Supplier data on the raw resin is not enough by itself: colorants, processing, coatings and sterilization change the result. Use supplier master files and a biological evaluation plan.","tags":[],"severity":"critical"},{"id":"mat-bio-3","text":"Nickel release from metal parts in prolonged skin contact is assessed against the market requirement","hint":"Stainless, plated and nickel-containing alloys can cause allergic reactions. Check the alloy and plating, and test release if needed.","tags":["wearable"],"severity":"major"},{"id":"mat-bio-4","text":"Materials are compatible with the specified sterilization or disinfection method","hint":"Gamma, EtO, autoclave and hydrogen peroxide each affect polymers differently (yellowing, embrittlement, crazing). Check supplier data and test after repeated cycles.","tags":["medical"],"severity":"critical"},{"id":"mat-bio-5","text":"Material change control is agreed with suppliers for every contact material","hint":"Require advance notification of any formula, site or process change in the supply agreement. Unannounced changes can invalidate biocompatibility.","tags":[],"severity":"major"}]},{"id":"mat-flu","title":"Fluid & Food Contact","tags":["fluidic"],"items":[{"id":"mat-flu-1","text":"Every wetted material is checked for compatibility with every medium, including cleaning and flushing fluids","hint":"Build a wetted-materials matrix (tubing, seals, adhesives, housings, fittings) against media and temperature. Check swelling, extraction and stress cracking.","tags":[],"severity":"critical"},{"id":"mat-flu-2","text":"Required contact approvals (food, potable water, medical fluid path) are identified and every wetted material has them","hint":"Identify which regulations apply in each market and get the supplier's compliance letter for the specific grade and color.","tags":[],"severity":"critical"},{"id":"mat-flu-3","text":"Leachables and extractables risk is assessed where fluid purity or taste matters","hint":"Plasticizers, lubricants and mold release agents can contaminate the fluid. Ask suppliers for extractables data or plan a test.","tags":["medical"],"severity":"major"},{"id":"mat-flu-4","text":"Permeation of gases or vapors through tubing and housings is acceptable for the application","hint":"Silicone and some TPEs are highly permeable. Check permeation data if the fluid can dry out, degas or absorb oxygen.","tags":[],"severity":"minor"},{"id":"mat-flu-5","text":"Wetted metal parts are chosen to avoid corrosion and ion release into the fluid","hint":"Check the fluid chemistry (chlorides, pH) against the metal and its finish. Avoid platings that can flake into the fluid path.","tags":[],"severity":"major"}]},{"id":"mat-sus","title":"Sustainability & End of Life","tags":[],"items":[{"id":"mat-sus-1","text":"Plastic parts carry a resin identification marking where space allows","hint":"Mark per the applicable resin coding convention (e.g. >PC+ABS<) in a non-cosmetic area, and include it on the drawing.","tags":["injection-molded"],"severity":"minor"},{"id":"mat-sus-2","text":"The number of different materials is minimized and dissimilar materials are separable at end of life","hint":"Review the materials list for near-duplicate grades that could be consolidated. Permanently bonded mixed materials are hard to recycle.","tags":[],"severity":"minor"},{"id":"mat-sus-3","text":"Recycled-content or bio-based material targets, if any, are met by grades with verified properties","hint":"Recycled grades vary lot to lot. Get supplier data and certificates, and test critical properties.","tags":[],"severity":"minor"},{"id":"mat-sus-4","text":"Battery and electronics removal for end-of-life treatment is possible without destroying the enclosure","hint":"Check against market requirements for removable batteries and WEEE treatment. Coordinate with the DFA review.","tags":["battery-pack","electronics"],"severity":"major"}]},{"id":"mat-out","title":"Outdoor Durability","tags":["outdoor"],"items":[{"id":"mat-out-1","text":"Exposed plastics are UV-stabilized grades and the color is confirmed for UV stability","hint":"Check the datasheet for UV stabilization and ask the supplier for weathering data. Dark colors often hold up better; bright and light colors can fade or yellow.","tags":[],"severity":"major"},{"id":"mat-out-2","text":"Accelerated weathering test (xenon arc or UV fluorescent) is planned for exposed materials and finishes","hint":"Define the method, duration and acceptance (color change, gloss retention, property retention). Coordinate with the validation plan.","tags":[],"severity":"major"},{"id":"mat-out-3","text":"Salt spray or cyclic corrosion resistance is specified for metal parts and finishes where required","hint":"State the test method and duration per the product specification. Cyclic tests correlate better with real exposure than neutral salt spray alone.","tags":[],"severity":"major"},{"id":"mat-out-4","text":"Materials are rated for the outdoor temperature extremes including solar heating of dark surfaces","hint":"Dark surfaces in sun get much hotter than ambient air. Use the analysis or field data to set the material temperature rating.","tags":[],"severity":"major"},{"id":"mat-out-5","text":"Fasteners and hardware exposed outdoors match the corrosion class of the parts they join","hint":"A zinc-plated screw in a stainless or anodized assembly rusts first and stains the product. Check the fastener finish in the BOM.","tags":[],"severity":"minor"}]}]},{"id":"analysis","title":"Thermal & Structural Analysis","short":"Analysis","version":1,"description":"Analysis planning, loads and boundary conditions, FEA modeling, results interpretation, structural, dynamics, thermal, thermal expansion, pressure, battery and analysis documentation.","sections":[{"id":"fea-plan","title":"Analysis Planning","tags":[],"items":[{"id":"fea-plan-1","text":"A list of parts and load cases that need analysis is agreed at the start of detailed design","hint":"Base it on the requirements, risk analysis and past failures. Unanalyzed critical parts are usually found during testing, when changes are expensive.","tags":[],"severity":"major"},{"id":"fea-plan-2","text":"Acceptance criteria and safety factors are defined before any analysis is run","hint":"State the allowable (yield, ultimate, strain, temperature, deflection) and safety factor for each load case in the plan. Criteria chosen after seeing results invite wishful thinking.","tags":[],"severity":"major"},{"id":"fea-plan-3","text":"Hand calculations bound each critical result before or alongside FEA","hint":"Beam, plate, pressure-vessel or thermal resistance hand calcs catch unit errors and wrong boundary conditions. Large disagreement with FEA needs an explanation.","tags":[],"severity":"major"},{"id":"fea-plan-4","text":"Rules of thumb used in place of analysis are labeled as such and recorded with their source","hint":"Mark them clearly in the design record so reviewers know which numbers were not calculated.","tags":[],"severity":"minor"},{"id":"fea-plan-5","text":"The analysis type (static, modal, transient, nonlinear, thermal, CFD) matches the physics of each load case","hint":"Impact and snap fits are not linear static problems. Large deflections, contact and yielding need nonlinear analysis.","tags":[],"severity":"major"},{"id":"fea-plan-6","text":"Analysis results feed back into a decision: design change, test or accepted risk","hint":"Every result should close with an action. Reports that conclude nothing waste the effort.","tags":[],"severity":"minor"},{"id":"fea-plan-7","text":"Analysis schedule allows results before tooling release","hint":"Tie analysis milestones to the tooling kickoff. Results after tool steel is cut become a recut.","tags":["injection-molded","cast","high-volume"],"severity":"major"},{"id":"fea-plan-8","text":"The software, version and solver settings used are recorded","hint":"Results can change between versions and solver settings. Record them for reproducibility.","tags":[],"severity":"minor"}]},{"id":"fea-load","title":"Loads & Boundary Conditions","tags":[],"items":[{"id":"fea-load-1","text":"Load cases are derived from the requirements, including normal use, reasonably foreseeable misuse and abuse","hint":"Trace each load case to a requirement or risk item. Sitting, stepping, dropping and lifting by the wrong feature are common misuse loads.","tags":[],"severity":"critical"},{"id":"fea-load-2","text":"Drop and impact loads are included for handheld and portable products","hint":"Define the drop height, surface and orientations from the requirement. Use the results to rank risk, not as a pass/fail replacement for testing.","tags":["handheld"],"severity":"major"},{"id":"fea-load-3","text":"Transport and packaging loads (vibration, stacking, shock) are included","hint":"Use the shipping test standard named in the requirements to define the loads. Stacking compression on packaged products can exceed use loads.","tags":[],"severity":"major"},{"id":"fea-load-4","text":"Assembly loads such as screw torque, press fits, heat staking and insertion forces are included","hint":"Boss splitting and stripped threads often come from assembly, not use. Apply the bolt preload or interference as a load case.","tags":[],"severity":"major"},{"id":"fea-load-5","text":"Fastener preload is modeled where it affects joint stiffness, contact or separation","hint":"Use bolt pretension features in the solver, with preload from torque per the fastener supplier's torque-tension data.","tags":[],"severity":"major"},{"id":"fea-load-6","text":"Boundary conditions represent the real supports and do not overconstrain the model","hint":"Fixed faces add artificial stiffness and stress. Use the actual mounting features, springs or remote supports, and check reaction forces.","tags":[],"severity":"critical"},{"id":"fea-load-7","text":"Bonded versus contact interfaces are chosen deliberately and justified in the report","hint":"Bonded contact transfers tension through faces that would separate in reality. Use frictional or frictionless contact where parts can slide or open.","tags":[],"severity":"major"},{"id":"fea-load-8","text":"Reaction forces sum to the applied loads","hint":"Check the reaction-force probe in the solver. A mismatch reveals missing loads, wrong units or rigid body motion.","tags":[],"severity":"major"},{"id":"fea-load-9","text":"Load magnitude and direction worst cases are identified, not just one nominal load","hint":"Sweep directions where the load can come from different angles. The worst case is often off-axis.","tags":[],"severity":"major"},{"id":"fea-load-10","text":"Loads from internal components (battery, motors, heat sinks, displays) are applied with their masses","hint":"Heavy internal parts load their mounts during drop and vibration. Use point masses with correct center of gravity location.","tags":["electronics"],"severity":"minor"}]},{"id":"fea-mod","title":"FEA Modeling","tags":[],"items":[{"id":"fea-mod-1","text":"Geometry defeaturing (removed fillets, holes, ribs) is listed and justified as not affecting the results","hint":"Removing a fillet at a high-stress location changes the answer. Keep features in the region of interest.","tags":[],"severity":"major"},{"id":"fea-mod-2","text":"A mesh convergence study is done at the locations used for decisions","hint":"Refine the mesh until peak stress or displacement changes less than a stated tolerance. Report the convergence plot or table.","tags":[],"severity":"critical"},{"id":"fea-mod-3","text":"Element type and order suit the geometry (e.g. second-order tetrahedra, shells for thin sheet metal)","hint":"First-order tetrahedra are too stiff in bending. Use at least two to three elements through thin walls, or shells.","tags":[],"severity":"major"},{"id":"fea-mod-4","text":"The material model (linear elastic, elastic-plastic, hyperelastic) matches the expected behavior","hint":"Linear elastic results above yield are meaningless. Use plasticity for yielding metals and hyperelastic models for elastomers.","tags":[],"severity":"major"},{"id":"fea-mod-5","text":"Glass-filled plastic parts account for fiber orientation and anisotropy, or use conservative properties","hint":"Map fiber orientation from mold flow into the FEA where results are critical, otherwise use the transverse (lower) properties and weld line knockdowns.","tags":["injection-molded"],"severity":"major"},{"id":"fea-mod-6","text":"Material data used is at the operating temperature and, where relevant, conditioned moisture state","hint":"Enter temperature-dependent properties from the supplier for the analyzed temperature. Room-temperature data overstates plastic strength at elevated temperature.","tags":[],"severity":"major"},{"id":"fea-mod-7","text":"Stress singularities at sharp corners, point loads and constraints are identified and not used as design stresses","hint":"Stress that keeps rising with mesh refinement is a singularity. Add the real fillet, or evaluate stress away from the singular point.","tags":[],"severity":"critical"},{"id":"fea-mod-8","text":"Units are consistent throughout the model and inputs","hint":"Check density, modulus and load units against the solver unit system. Unit errors are among the most common FEA mistakes.","tags":[],"severity":"critical"},{"id":"fea-mod-9","text":"Symmetry, if used, is valid for geometry, loads and constraints","hint":"Symmetric models miss asymmetric buckling and vibration modes. Check that loads are truly symmetric.","tags":[],"severity":"minor"},{"id":"fea-mod-10","text":"Material properties assigned to every body match the specified grade on the BOM","hint":"Check each body's material assignment in the model tree. Default steel on a plastic part is a frequent mistake.","tags":[],"severity":"major"}]},{"id":"fea-res","title":"Results & Interpretation","tags":[],"items":[{"id":"fea-res-1","text":"Peak stresses are compared with the allowable for the material and failure mode, with the agreed safety factor","hint":"Use von Mises for ductile metals and principal stress or strain for brittle materials and plastics. Report the margin explicitly.","tags":[],"severity":"critical"},{"id":"fea-res-2","text":"Displacements are checked against functional limits such as clearances, alignments and seal compression","hint":"Overlay deformed shape with nearby parts. Excess deflection can cause rubbing, gaps or loss of sealing even without failure.","tags":[],"severity":"major"},{"id":"fea-res-3","text":"Buckling is checked for slender or thin-walled parts under compression","hint":"Run a linear buckling analysis and apply a knockdown for imperfections, or a nonlinear analysis for critical cases.","tags":[],"severity":"major"},{"id":"fea-res-4","text":"Fatigue life is evaluated for cyclically loaded parts using an S-N curve for the material and the expected cycle count","hint":"Use the cycle count from the life requirement and include mean stress effects. Plastics fatigue at lower stress than static strength suggests.","tags":["moving-parts"],"severity":"critical"},{"id":"fea-res-5","text":"Creep and stress relaxation are evaluated for plastic parts under sustained load","hint":"Use creep modulus or isochronous curves for the load duration and temperature. Bosses, clips and press fits loosen over time.","tags":["injection-molded","additive"],"severity":"major"},{"id":"fea-res-6","text":"Snap fit strain at full deflection is below the allowable for the material grade","hint":"Compute the peak strain during assembly (not just the latched state) and compare against the supplier's allowable strain for the number of cycles.","tags":["injection-molded"],"severity":"major"},{"id":"fea-res-7","text":"Results are plotted with a sensible scale and the deformed shape is reviewed for plausibility","hint":"Check exaggerated deformed shape and animation. Parts flying apart or moving through each other point to modeling errors.","tags":[],"severity":"minor"},{"id":"fea-res-8","text":"A second engineer reviews the model setup and results before they are used for decisions","hint":"The reviewer checks loads, boundary conditions, materials and mesh, not just the final plot.","tags":[],"severity":"major"},{"id":"fea-res-9","text":"The model is correlated with a physical test or a known reference case where results drive critical decisions","hint":"Compare strain gauge, deflection or temperature measurements with prediction, and update the model if it disagrees.","tags":[],"severity":"major"},{"id":"fea-res-10","text":"Sensitivity to uncertain inputs (friction, material properties, contact stiffness) is checked","hint":"Run the analysis at both ends of the input range. Conclusions that flip with a reasonable input change need a test.","tags":[],"severity":"minor"},{"id":"fea-res-11","text":"Failure modes are reported with location and the design change that addresses them","hint":"Name the feature and propose the fix. A plot without a conclusion leaves the designer guessing.","tags":[],"severity":"minor"}]},{"id":"fea-str","title":"Structural","tags":["structural"],"items":[{"id":"fea-str-1","text":"Load paths from the point of load application to the supports are identified and continuous","hint":"Sketch the load path and check every joint, weld and fastener along it. Gaps in the path usually show up as unexpected deformation.","tags":[],"severity":"critical"},{"id":"fea-str-2","text":"Fastener and joint loads (tension, shear, prying) are calculated and below the rated capacity","hint":"Extract forces at each fastener from FEA or calculate by hand. Include prying action and thread strip in the base material.","tags":[],"severity":"critical"},{"id":"fea-str-3","text":"Weld strength is checked with the weld size, process and reduced heat-affected-zone properties","hint":"Weld toes are fatigue hotspots. Use the structural welding standard named in the requirements for allowables.","tags":[],"severity":"major"},{"id":"fea-str-4","text":"Factor of safety follows the applicable standard or requirement and is documented for each load case","hint":"Name the source of each factor. Lifting, pressure and overhead equipment often have prescribed factors.","tags":[],"severity":"critical"},{"id":"fea-str-5","text":"The predicted failure mode is safe: it gives warning, fails gradually or fails in a direction that does not harm people","hint":"Prefer yielding before fracture. Check that a failed part does not release stored energy or drop loads on users.","tags":[],"severity":"critical"},{"id":"fea-str-6","text":"Load ratings marked on the product or in the manual are supported by the analysis with the required margin","hint":"Cross-check the rated load in labeling against the analyzed and tested capacity.","tags":["regulatory"],"severity":"major"}]},{"id":"fea-dyn","title":"Dynamics, Shock & Drop","tags":[],"items":[{"id":"fea-dyn-1","text":"Natural frequencies are calculated and separated from known excitation frequencies","hint":"Run a modal analysis and compare against motor, fan, pump and transport vibration frequencies. Rule of thumb: keep a clear margin between the first mode and the main excitation.","tags":["moving-parts","electronics"],"severity":"major"},{"id":"fea-dyn-2","text":"Random or sine vibration response is evaluated for the transport or operating vibration profile","hint":"Use the profile from the requirements and include appropriate damping. Check PCB and heavy-component mounts.","tags":["electronics"],"severity":"major"},{"id":"fea-dyn-3","text":"Shock loads are evaluated for the specified shock pulse","hint":"Use transient or response-spectrum analysis. Check mounts of heavy components and brittle parts like displays and glass.","tags":[],"severity":"major"},{"id":"fea-dyn-4","text":"Drop simulation assumptions (impact surface, contact, material strain-rate effects) are stated and its limits are acknowledged","hint":"Explicit drop simulations are sensitive to material data and contact. Use them to compare designs and find weak points, and confirm with physical drop tests.","tags":["handheld"],"severity":"major"},{"id":"fea-dyn-5","text":"Moving masses and mechanisms are checked for dynamic loads, including end-of-travel impact","hint":"End stops, latches and hinges see peak loads at impact. Include velocity and stop stiffness.","tags":["moving-parts"],"severity":"major"},{"id":"fea-dyn-6","text":"Damping values used in dynamic analyses are justified by data or conservative assumptions","hint":"Response at resonance is very sensitive to damping. State the value and the source.","tags":[],"severity":"minor"}]},{"id":"fea-th","title":"Thermal","tags":["thermal"],"items":[{"id":"fea-th-1","text":"Heat sources and their power dissipation come from the EE power budget, including worst-case operating modes","hint":"Use the current power budget for every component, including peak and sustained modes. Analysis with stale or guessed power is not useful.","tags":["electronics"],"severity":"critical"},{"id":"fea-th-2","text":"Maximum ambient temperature for analysis is the worst case from the requirements, including enclosure placement","hint":"Consider installation in cabinets, near other equipment, in vehicles or in direct sun. Ambient inside the installation can be well above room ambient.","tags":[],"severity":"critical"},{"id":"fea-th-3","text":"Conduction paths from hot components to the enclosure or heat sink are identified and modeled","hint":"Check every interface along the path. A path through a thin plastic wall or an air gap is often the bottleneck.","tags":[],"severity":"major"},{"id":"fea-th-4","text":"Thermal interface materials are specified with thickness, compression and thermal resistance at that compression","hint":"Thermal pad resistance depends on compression. Check the gap stack-up gives the intended compression without overloading components or the PCB.","tags":["electronics"],"severity":"major"},{"id":"fea-th-5","text":"Natural or forced convection assumptions are stated, including the orientation of the product","hint":"Natural convection depends strongly on orientation and vent placement. Analyze the worst installed orientation.","tags":[],"severity":"major"},{"id":"fea-th-6","text":"Fan selection is based on the system impedance curve intersecting the fan curve, with margin","hint":"Estimate system pressure drop from CFD or hand calcs, including filters and grilles. Account for filter clogging and fan aging.","tags":[],"severity":"major"},{"id":"fea-th-7","text":"CFD assumptions (turbulence model, mesh, boundary conditions, radiation) are documented and checked for sensitivity","hint":"Check mesh independence at component temperatures. Include radiation where natural convection dominates.","tags":[],"severity":"major"},{"id":"fea-th-8","text":"Every component temperature is below its rated limit with a margin agreed with the EE","hint":"Compare predicted junction or case temperatures with datasheet limits and derating rules from the EE.","tags":["electronics"],"severity":"critical"},{"id":"fea-th-9","text":"Touch temperatures of accessible surfaces are within the limits of the applicable safety standard","hint":"Identify which surfaces are touchable and for how long, and check against the standard's surface temperature limits for that material and contact duration.","tags":["regulatory"],"severity":"critical"},{"id":"fea-th-10","text":"Solar loading is included for outdoor products","hint":"Apply solar flux from the requirement or design climate data, with surface absorptivity for the actual color and finish.","tags":["outdoor"],"severity":"major"},{"id":"fea-th-11","text":"Plastic parts near heat sources stay below their long-term temperature limits","hint":"Check predicted part temperatures against RTI or HDT with margin. Hot spots near power components and LEDs soften bosses and clips.","tags":[],"severity":"major"},{"id":"fea-th-12","text":"Battery cell temperatures stay within the cell manufacturer's limits for charge and discharge","hint":"Charge limits are usually tighter than discharge limits. Coordinate with the EE on charge rate at high ambient.","tags":["battery-pack"],"severity":"critical"},{"id":"fea-th-13","text":"Vent and filter placement does not short-circuit airflow from outlet back to inlet","hint":"Check CFD streamlines or smoke tests. Recirculation raises inlet temperature and defeats the cooling design.","tags":[],"severity":"minor"},{"id":"fea-th-14","text":"Transient thermal behavior is evaluated where duty cycles or startup peaks matter","hint":"Short bursts may be acceptable even if steady-state would not be. Use the duty cycle from the requirements.","tags":[],"severity":"minor"},{"id":"fea-th-15","text":"Condensation risk is evaluated for products that cycle through the dew point","hint":"Cold surfaces inside a warm humid enclosure collect water. Check temperature cycling and venting strategy with the enclosure review.","tags":["outdoor","sealed-ip"],"severity":"minor"}]},{"id":"fea-cte","title":"Thermal Expansion & Thermal Stress","tags":[],"items":[{"id":"fea-cte-1","text":"CTE mismatch between joined parts is evaluated over the full temperature range","hint":"Long plastic parts on metal frames, glass in housings and overmolds are common problem areas. Calculate differential growth by hand over the part length.","tags":[],"severity":"major"},{"id":"fea-cte-2","text":"Thermal stresses from constrained expansion are below allowables at temperature extremes","hint":"Run a thermal-structural analysis or hand calc for bonded, press-fit or fastened dissimilar materials.","tags":[],"severity":"major"},{"id":"fea-cte-3","text":"Clearances and fits remain functional at both temperature extremes","hint":"Recompute critical gaps at hot and cold. Coordinate with the tolerance stack-ups in the tolerancing review.","tags":[],"severity":"major"},{"id":"fea-cte-4","text":"Slotted holes, floating mounts or compliant features allow thermal growth where needed","hint":"Check that only one fixed point exists along a long part. Over-constrained long parts buckle or crack.","tags":[],"severity":"minor"}]},{"id":"fea-flu","title":"Fluid & Pressure","tags":["fluidic"],"items":[{"id":"fea-flu-1","text":"Pressure-containing parts are analyzed for the maximum operating pressure with the required margin","hint":"Include pressure spikes from valves closing or pumps starting. Use the rated pressure from the requirements.","tags":[],"severity":"critical"},{"id":"fea-flu-2","text":"Burst pressure factor meets the applicable standard or requirement","hint":"State the required burst factor and its source, and check the analysis and planned test against it.","tags":[],"severity":"critical"},{"id":"fea-flu-3","text":"Pressure-induced deformation does not open leak paths at seals and joints","hint":"Check the seal compression at peak pressure in the deformed model. Housings bulge and unload O-rings.","tags":["sealed-ip"],"severity":"major"},{"id":"fea-flu-4","text":"Pressure drop and flow through the fluid path meet requirements","hint":"Use hand calcs or CFD for the full path, including fittings, filters and valves.","tags":[],"severity":"minor"},{"id":"fea-flu-5","text":"Plastic pressure parts are evaluated for long-term creep rupture at temperature","hint":"Use long-term hydrostatic strength data from the supplier. Short-term burst tests do not predict long-term failure.","tags":["injection-molded"],"severity":"major"}]},{"id":"fea-bat","title":"Battery","tags":["battery-pack"],"items":[{"id":"fea-bat-1","text":"Thermal runaway propagation between cells is considered and the mitigation strategy is agreed with the EE","hint":"Review cell spacing, barriers and venting paths. Coordinate with the battery safety standard named in the requirements.","tags":[],"severity":"critical"},{"id":"fea-bat-2","text":"Cell venting gases have a path out of the enclosure that does not direct them at the user","hint":"Check vent direction and enclosure pressure relief. A sealed enclosure can rupture during a cell vent event.","tags":[],"severity":"critical"},{"id":"fea-bat-3","text":"Cell swelling over life and mounting pressure are within the cell manufacturer's limits","hint":"Allow space for end-of-life swelling per the cell datasheet. Check the mounting design does not apply point loads to cells.","tags":[],"severity":"major"},{"id":"fea-bat-4","text":"Cells are protected from puncture and crush by the enclosure and internal structure under drop and impact loads","hint":"Check the drop and crush analysis results at the cell envelope, including sharp internal features such as screw tips, ribs and PCB components near the cells.","tags":[],"severity":"critical"}]},{"id":"fea-doc","title":"Documentation","tags":[],"items":[{"id":"fea-doc-1","text":"Each analysis has a report with inputs, assumptions, load cases, results and conclusions","hint":"A reviewer should be able to repeat the analysis from the report alone.","tags":[],"severity":"major"},{"id":"fea-doc-2","text":"The report states the CAD revision and part numbers analyzed","hint":"Results on an old revision may no longer apply. Re-run or justify when the geometry changes.","tags":[],"severity":"major"},{"id":"fea-doc-3","text":"Analysis files (model, mesh, results) are archived with the project","hint":"Store native files in the project repository with the CAD revision. Lost models mean rerunning from scratch.","tags":[],"severity":"minor"},{"id":"fea-doc-4","text":"Assumptions and simplifications are listed with their expected effect on the results","hint":"Mark which assumptions are conservative and which are not.","tags":[],"severity":"minor"},{"id":"fea-doc-5","text":"Open issues and recommendations from analysis are tracked to closure","hint":"Enter them in the issue tracker or design review action list with an owner.","tags":[],"severity":"minor"},{"id":"fea-doc-6","text":"Analysis results that support certification or regulatory submissions are under document control","hint":"Release the report with a document number and revision so it can be referenced in the technical file.","tags":["regulatory","medical"],"severity":"major"}]}]},{"id":"enclosure","title":"Enclosures, Sealing & IP","short":"Enclosure","version":1,"description":"Enclosure review covering architecture, ingress protection and sealing, environmental durability, drop, EMC and electronics integration, thermal, safety, battery compartments, user interface and cleanability.","sections":[{"id":"enc-arch","title":"Enclosure Architecture","tags":[],"items":[{"id":"enc-arch-1","text":"Split lines between housings are placed so they do not cross sealing paths, cosmetic surfaces or user grip zones unnecessarily","hint":"Review split lines on the industrial design model with sealing and cosmetics in view. A badly placed split line forces a complex gasket or a visible step.","tags":[],"severity":"major"},{"id":"enc-arch-2","text":"Mating housings locate to each other with defined locating features rather than fasteners or outer edges","hint":"Use pins, bosses or perimeter tongue-and-groove features tied to the datum scheme. Locating on screws gives variable alignment.","tags":[],"severity":"major"},{"id":"enc-arch-3","text":"Housing-to-housing step and gap at the split line are specified and achievable with the locating scheme","hint":"Run the step and gap stack around the perimeter. Cross-reference the Tolerancing checklist for the analysis method.","tags":["cosmetic"],"severity":"major"},{"id":"enc-arch-4","text":"A lip, tongue or overlap at the split line hides the gap and blocks a direct line of sight into the enclosure","hint":"A straight butt joint shows every mismatch and gives a direct path for light, dust and probes.","tags":[],"severity":"minor"},{"id":"enc-arch-5","text":"Lids, doors and covers are retained so that they stay closed under drop, vibration and pressure conditions","hint":"Check the latch or fastener retention force against the loads. Doors that pop open in a drop expose batteries and electronics.","tags":[],"severity":"major"},{"id":"enc-arch-6","text":"Large flat walls have enough stiffness (ribs, curvature or thickness) to avoid oil-canning, rattles and seal gaps","hint":"Check wall deflection under the expected handling and internal loads by hand calculation or FEA. A flexible wall between fasteners opens the seal gap.","tags":[],"severity":"major"},{"id":"enc-arch-7","text":"PCBs are supported by bosses or ribs close enough together to limit board flex during assembly, connector mating and drop","hint":"Check support spacing near heavy parts and connectors that are pushed by users. Coordinate support locations with EE keep-outs.","tags":["electronics"],"severity":"major"},{"id":"enc-arch-8","text":"PCB mounting is not over-constrained, so housing tolerance or thermal expansion does not bend the board","hint":"Use one fixed point and slotted or compliant others, or check the induced board strain. Board flex cracks ceramic capacitors and BGA joints.","tags":["electronics"],"severity":"major"},{"id":"enc-arch-9","text":"Mounting provisions for the product (wall, DIN rail, VESA, tripod, panel cut-out) are defined and load-rated","hint":"Check the mounting interface against the customer specification and the load with a safety factor. Cross-reference Thermal & Structural Analysis for the load case.","tags":[],"severity":"major"},{"id":"enc-arch-10","text":"Internal space claims for components, cables and air paths are reserved and checked with the latest EE and supplier CAD","hint":"Import the latest PCBA STEP and component models and run interference and clearance checks. Stale EE models are a common source of late conflicts.","tags":["electronics"],"severity":"major"}]},{"id":"enc-ip","title":"Ingress Protection & Sealing","tags":["sealed-ip"],"items":[{"id":"enc-ip-1","text":"The IP rating target per IEC 60529 is defined for the product and for each opening, including service and battery doors","hint":"List every opening (split lines, buttons, connectors, vents, windows, speaker ports, doors) with its target rating and sealing method. An opening without an owner is the one that leaks.","tags":[],"severity":"critical"},{"id":"enc-ip-2","text":"Every seal path is continuous around the full perimeter with no gaps, butt joints or unsupported spans","hint":"Trace the sealing line in CAD around each opening, including where it passes bosses and corners. Check the gasket or bead is supported along its whole length.","tags":[],"severity":"critical"},{"id":"enc-ip-3","text":"Gasket compression stays within the gasket supplier's recommended range across worst-case tolerances","hint":"Run the stack for minimum and maximum compression. Too little leaks; too much takes a compression set or overstresses the housing.","tags":["elastomer"],"severity":"critical"},{"id":"enc-ip-4","text":"Seal path corners have radii that the gasket can follow without wrinkling or lifting","hint":"Check the minimum inner radius against the gasket supplier's guidance for the cross-section. Sharp corners are the usual leak points.","tags":[],"severity":"major"},{"id":"enc-ip-5","text":"Gasket groove fill stays below the gasket supplier's maximum at maximum gasket and minimum groove volume","hint":"Elastomers are nearly incompressible; an overfilled groove forces material out or prevents closing. Include thermal expansion of the gasket at maximum temperature.","tags":["elastomer"],"severity":"major"},{"id":"enc-ip-6","text":"A compression stop (hard stop) limits gasket compression so the clamping load goes into housing metal-to-metal or plastic-to-plastic contact","hint":"Without a hard stop, compression depends on screw torque and plastic creep. Check that the stop is reached before the gasket is overcompressed.","tags":[],"severity":"major"},{"id":"enc-ip-7","text":"Fastener spacing and housing stiffness give even gasket compression between fasteners","hint":"Check housing deflection between fasteners under the gasket reaction force using FEA or a beam calculation. Gaps open midway between widely spaced screws.","tags":[],"severity":"major"},{"id":"enc-ip-8","text":"O-ring glands follow the O-ring supplier's handbook for gland depth, width, squeeze and stretch","hint":"Check static or dynamic gland dimensions, squeeze and stretch percentages, and lead-in chamfer against the handbook for the chosen cross-section and material.","tags":["elastomer"],"severity":"major"},{"id":"enc-ip-9","text":"O-rings are protected from cutting during assembly by lead-in chamfers and the absence of sharp edges or cross holes they pass over","hint":"Trace the O-ring path during assembly. Threads, port edges and parting lines it crosses must be chamfered or covered.","tags":["elastomer"],"severity":"major"},{"id":"enc-ip-10","text":"Sealing faces have a specified surface finish compatible with the seal type","hint":"Specify the roughness on the drawing per the seal supplier. Texture, tool marks or ejector pins on a sealing face create leak paths.","tags":[],"severity":"major"},{"id":"enc-ip-11","text":"No parting line, gate, ejector mark or weld line crosses a sealing face","hint":"Review mold flow and tooling layout against the seal path. A parting-line flash across a seal face is a classic leak and tooling-change cause.","tags":["injection-molded"],"severity":"critical"},{"id":"enc-ip-12","text":"Formed-in-place or dispensed gaskets have a defined bead size, path and cure, and a dispensing supplier has confirmed the geometry","hint":"Check minimum bead start/stop overlap, corner radii and groove shape with the dispensing material supplier.","tags":[],"severity":"major"},{"id":"enc-ip-13","text":"A membrane vent equalizes internal pressure where altitude, temperature changes or sealed volume would otherwise load the seals","hint":"Sealed enclosures pump air through the weakest seal as they heat and cool. Size the vent airflow and water entry pressure per the vent supplier.","tags":[],"severity":"major"},{"id":"enc-ip-14","text":"Membrane vents are protected from direct jets, debris and mechanical damage and can be sealed to the housing reliably","hint":"Place vents in sheltered locations and specify the bonding surface finish and flatness required by the vent supplier.","tags":[],"severity":"minor"},{"id":"enc-ip-15","text":"Buttons and switches have a seal (membrane, boot, O-ring or overmold) rated for the IP target and the actuation cycle life","hint":"Check that the seal remains intact over the full actuation count and that actuation force includes the seal's stiffness.","tags":[],"severity":"major"},{"id":"enc-ip-16","text":"External connectors are sealed by a rated sealed connector, a panel gasket or a cover, with the mated and unmated states considered","hint":"Define the IP rating for each connector both mated and unmated. Connector supplier ratings apply only with the specified panel cutout and gasket.","tags":[],"severity":"major"},{"id":"enc-ip-17","text":"Cable entries use rated cable glands or overmolded strain reliefs sized for the actual cable diameter range","hint":"Check the gland's clamping range against the cable OD tolerance and the panel thickness and hole size required.","tags":[],"severity":"major"},{"id":"enc-ip-18","text":"Windows, lenses and labels bonded over openings use an adhesive seal with a continuous, defined bond width","hint":"Specify the die-cut tape or adhesive bead with minimum bond width per the tape supplier, and the bonding pressure.","tags":[],"severity":"major"},{"id":"enc-ip-19","text":"Water that enters non-sealed zones (between outer cosmetic parts and the sealed core) drains out and does not pool against seals","hint":"Trace where spray or rain collects in the use orientations and add drain paths. Standing water defeats seals designed for splash.","tags":[],"severity":"minor"},{"id":"enc-ip-20","text":"Potting or encapsulation, where used, has a defined volume, fill level, cure, and compatibility with components and housing","hint":"Check the potting compound's shrinkage, CTE and cure stress on components, and that air can escape during fill. Potting makes rework impossible; confirm the decision.","tags":["electronics"],"severity":"major"}]},{"id":"enc-env","title":"Environmental Durability","tags":["outdoor"],"items":[{"id":"enc-env-1","text":"Exposed plastics and elastomers are UV-stabilized grades rated for the expected outdoor exposure","hint":"Check UV stability data per material datasheet. Unstabilized plastics chalk, yellow and embrittle; the gasket will fail long before the housing.","tags":[],"severity":"major"},{"id":"enc-env-2","text":"Condensation inside the enclosure is managed by venting, desiccant, conformal coating or drainage","hint":"Sealed enclosures that cycle through the dew point collect water. Decide the strategy with EE and document it.","tags":["electronics"],"severity":"major"},{"id":"enc-env-3","text":"All exposed metals and fasteners have corrosion protection suitable for the environment (salt spray, humidity, chemicals)","hint":"Check finish and material against the environment class. Cross-reference Materials & Finishes for the finish specification.","tags":[],"severity":"major"},{"id":"enc-env-4","text":"Seals remain compliant across the full operating and storage temperature range","hint":"Check the elastomer's low-temperature limit and compression set at high temperature per datasheet. Stiff seals at low temperature leak.","tags":["elastomer"],"severity":"major"},{"id":"enc-env-5","text":"Dissimilar materials in the enclosure are checked for differential thermal expansion at temperature extremes","hint":"Large plastic-to-metal joints shift with temperature and can open seals or crack bosses. Calculate the expansion difference at extremes.","tags":[],"severity":"major"},{"id":"enc-env-6","text":"Openings and surfaces exposed to dust, sand, ice or insects are protected against blockage and damage","hint":"Check vents, drain holes and moving parts for clogging. Ice formation in recesses can jam buttons and doors.","tags":[],"severity":"minor"}]},{"id":"enc-drop","title":"Impact & Drop","tags":["handheld"],"items":[{"id":"enc-drop-1","text":"Housing corners and edges that hit first in a drop are reinforced or protected by bumpers","hint":"Identify likely impact points from the drop orientations. Add wall thickness, ribs or an elastomer bumper and check by drop simulation or prototype.","tags":[],"severity":"major"},{"id":"enc-drop-2","text":"Heavy internal parts (motors, magnets, speakers, ballast) are retained so they cannot break loose or load the PCB in a drop","hint":"Trace each heavy part's load path to the housing. Calculate inertial load from the drop deceleration estimate or simulation.","tags":[],"severity":"critical"},{"id":"enc-drop-3","text":"Displays, cover glass and touch panels are supported around their perimeter and isolated from housing flex","hint":"Check the support area, bonding tape and gap to the housing. Glass breaks where it bears on a hard point or edge.","tags":["electronics"],"severity":"major"},{"id":"enc-drop-4","text":"Cover glass and lenses are recessed or have a raised housing bezel so a flat-surface drop does not hit the glass first","hint":"Check the bezel height above the glass at all edges with tolerances.","tags":[],"severity":"major"},{"id":"enc-drop-5","text":"Ribs, screw tips and sharp edges near the battery keep enough clearance that a drop cannot dent or puncture the cell","hint":"Check the clearance at worst-case tolerance plus housing deflection from drop simulation. Cell damage is a fire and safety issue.","tags":["battery-pack"],"severity":"critical"},{"id":"enc-drop-6","text":"Snap fits and latches on the enclosure stay engaged under drop loads","hint":"Check the latch retention force against inertial loads on the latched part. Lids popping open in a drop is a common first-test failure.","tags":[],"severity":"major"}]},{"id":"enc-emc","title":"EMC & Electronics Integration","tags":["electronics"],"items":[{"id":"enc-emc-1","text":"Shielding requirements (shield cans, conductive coating, conductive gaskets) are agreed with EE and represented in CAD","hint":"Confirm which housing areas must be conductive and how continuity is made at seams. Late shielding additions often need tooling changes.","tags":[],"severity":"major"},{"id":"enc-emc-2","text":"Conductive paint or plating areas have masking defined on the drawing, coordinated with EE contact points","hint":"Show coated and masked areas in a drawing view. Paint where a gasket or ground contact needs bare metal kills the ground path.","tags":[],"severity":"major"},{"id":"enc-emc-3","text":"Grounding contact points between PCB, chassis and shields are defined with spring contacts, gaskets or fasteners and a controlled contact surface","hint":"Check spring contact compression range across tolerances per the contact supplier. Specify bare or plated contact areas.","tags":[],"severity":"major"},{"id":"enc-emc-4","text":"Antenna areas keep the clearance from metal parts, metallic paint, fasteners and conductive coatings that EE and the antenna supplier specify","hint":"Overlay the antenna keep-out on the housing CAD, including in-mold decoration, metallic inks and fasteners.","tags":[],"severity":"critical"},{"id":"enc-emc-5","text":"ESD discharge paths from user-accessible seams, buttons and connectors lead away from sensitive circuits","hint":"Review seams near the PCB edge, button gaps and connector shells with EE. Increase creepage paths at seams or provide a deliberate discharge path to ground.","tags":[],"severity":"major"},{"id":"enc-emc-6","text":"Light pipes are aligned with their LEDs within tolerance and optically isolated from neighbors","hint":"Run the LED-to-light-pipe stack. Add light-blocking ribs or opaque materials between adjacent indicators to prevent crosstalk.","tags":[],"severity":"minor"},{"id":"enc-emc-7","text":"Display windows have a defined viewing area, black-mask border and gap to the display that avoids pressure marks","hint":"Check that the visible area aligns with the active area across tolerance, and that the window cannot touch the display when pressed.","tags":[],"severity":"minor"},{"id":"enc-emc-8","text":"Button actuators line up with their switches across tolerances and actuate them at the center","hint":"Run the actuator-to-switch stack in X, Y and Z. Off-center actuation gives a mushy feel and short switch life.","tags":[],"severity":"major"},{"id":"enc-emc-9","text":"Connectors on the PCB are accessible through the housing openings with correct alignment and depth across tolerances","hint":"Check the opening-to-connector stack and that the mating plug seats fully before its overmold hits the housing.","tags":[],"severity":"major"}]},{"id":"enc-thm","title":"Thermal Integration","tags":["thermal"],"items":[{"id":"enc-thm-1","text":"Any conflict between ventilation openings and the IP target is resolved with a documented approach","hint":"Options include sealed heat paths to the housing, membrane vents, labyrinth vents or a lower rating for part of the enclosure. Record the decision.","tags":["sealed-ip"],"severity":"critical"},{"id":"enc-thm-2","text":"Heat paths from hot components to the housing (thermal pads, gap fillers, heat spreaders) have defined compression and contact area","hint":"Check gap filler compression across tolerances against the supplier's range, and that the PCB is not overstressed by the pad force.","tags":[],"severity":"major"},{"id":"enc-thm-4","text":"Vent openings, fans and air paths are not blocked by the product's mounting, users' hands or nearby surfaces in intended use","hint":"Check vent placement against all use orientations and mounting. Cross-reference Thermal & Structural Analysis for the thermal model.","tags":[],"severity":"major"},{"id":"enc-thm-5","text":"Housing materials near heat sources are rated for the local temperature over the product life","hint":"Compare the local temperature to the material's heat deflection and long-term temperature rating per datasheet.","tags":[],"severity":"major"}]},{"id":"enc-reg","title":"Safety & Regulatory","tags":["regulatory"],"items":[{"id":"enc-reg-1","text":"Enclosure materials meet the flammability rating required by the applicable safety standard (e.g. a UL 94 class) at the actual wall thickness","hint":"UL 94 ratings depend on thickness. Check the material's yellow card at the thinnest wall of the enclosure.","tags":[],"severity":"critical"},{"id":"enc-reg-2","text":"Openings in the enclosure prevent access to hazardous parts as checked with the standard's test probes","hint":"Model the applicable probe (e.g. the test finger) and check it against every opening and gap. Include gaps that open under the probe force.","tags":[],"severity":"critical"},{"id":"enc-reg-3","text":"Access to hazardous voltages, moving parts or hot parts requires a tool, or is interlocked","hint":"Check every cover that exposes a hazard is tool-only or interlocked, per the applicable standard.","tags":[],"severity":"critical"},{"id":"enc-reg-4","text":"Mains or external power cords have strain relief and anti-rotation that meet the applicable standard's pull and torque tests","hint":"Check the strain relief design and that it cannot be pushed into the enclosure. Plan a pre-compliance pull test.","tags":[],"severity":"critical"},{"id":"enc-reg-5","text":"Creepage and clearance distances that depend on mechanical parts (housing ribs, barriers, insulating sheets) are maintained across tolerances and assembly variation","hint":"Get the required distances from EE and check them in CAD at worst case, including after a drop or applied force.","tags":["electronics"],"severity":"critical"}]},{"id":"enc-batt","title":"Battery Compartment","tags":["battery-pack"],"items":[{"id":"enc-batt-1","text":"The battery compartment has a vent path that directs gas away from the user in a cell failure","hint":"Follow the cell supplier's and the safety standard's guidance. A fully sealed battery compartment can turn a cell failure into a burst housing.","tags":[],"severity":"critical"},{"id":"enc-batt-2","text":"The compartment allows for cell swelling over life per the cell supplier's data without stressing the housing or PCB","hint":"Leave the swelling allowance in the thickness direction for pouch cells. Swelling pushes displays and housings apart in the field.","tags":[],"severity":"major"},{"id":"enc-batt-3","text":"Battery polarity is enforced mechanically for user-installed cells or packs","hint":"Keyed shapes, polarity-specific contacts or a reversed-insertion block. Mark polarity clearly as well.","tags":[],"severity":"major"},{"id":"enc-batt-4","text":"Battery contacts provide the required contact force over the life and tolerance range, and resist corrosion","hint":"Check spring contact deflection range across cell size tolerance per the contact supplier.","tags":[],"severity":"major"},{"id":"enc-batt-5","text":"The battery door or cover stays closed in a drop and resists opening by children where the regulations or market require it","hint":"Check the applicable child-resistance requirements for coin cells and button batteries. Verify door retention under drop load.","tags":[],"severity":"critical"},{"id":"enc-batt-6","text":"Battery packs are retained in all directions with features that do not bear on the cell's weak areas","hint":"Avoid loads on pouch cell seals and terminals. Use foam, brackets or a tray as the cell supplier recommends.","tags":[],"severity":"major"}]},{"id":"enc-ui","title":"User Interface Features","tags":[],"items":[{"id":"enc-ui-1","text":"Button travel and actuation force meet the UI specification across tolerances, including the seal and actuator contribution","hint":"Build a force-travel budget combining switch, dome, membrane and actuator stiffness. Confirm on prototypes.","tags":[],"severity":"major"},{"id":"enc-ui-2","text":"Buttons have a defined tactile response and do not rattle or stick in their openings","hint":"Check the clearance between button and housing across tolerances, and that the button cannot rotate or catch on an edge.","tags":[],"severity":"minor"},{"id":"enc-ui-3","text":"Button and interface labels (printed, molded, laser-etched) are durable for the expected wear and cleaning","hint":"Check abrasion resistance for the marking method against the use profile.","tags":[],"severity":"minor"},{"id":"enc-ui-4","text":"Backlit features and indicators do not leak light around button edges or through thin walls","hint":"Check wall opacity and add light-blocking features. Light leakage at seams is a common cosmetic rejection.","tags":[],"severity":"minor"},{"id":"enc-ui-5","text":"Controls cannot be actuated accidentally by normal handling, carrying or placing the product on a surface","hint":"Check recess depth or guards for critical buttons. Accidental actuation is a usability and sometimes safety issue.","tags":[],"severity":"major"}]},{"id":"enc-hyg","title":"Cleaning & Skin Contact","tags":["medical","wearable"],"items":[{"id":"enc-hyg-1","text":"External surfaces can be cleaned with the specified method without crevices, deep recesses or seams that trap contamination","hint":"Review seams, button gaps and texture for areas a wipe cannot reach. Minimize exposed fasteners and gaps.","tags":[],"severity":"major"},{"id":"enc-hyg-2","text":"Enclosure materials and seals are resistant to the specified cleaning and disinfecting agents over the required number of cycles","hint":"Check chemical resistance per datasheet and plan chemical exposure testing under stress. Many plastics crack under the combination of disinfectant and molded-in stress.","tags":[],"severity":"critical"},{"id":"enc-hyg-4","text":"Openings and seals in cleaned areas keep cleaning fluid out of the enclosure","hint":"Check the seal design against the cleaning method (spray, wipe, immersion) and the fluid's surface tension, which is lower than water's.","tags":[],"severity":"major"},{"id":"enc-hyg-5","text":"Skin-contact surfaces have no sharp edges, pinch points or features that snag hair or skin","hint":"Inspect radii and gaps on all contact surfaces. Check moving parts such as straps and clasps for pinch points.","tags":[],"severity":"major"}]}]},{"id":"drawings","title":"Drawings & Release","short":"Drawings","version":1,"description":"Drawing content, process-specific notes, assembly drawings and BOMs, revision control, checking and supplier release packages.","sections":[{"id":"drw-tb","title":"Title Block & Metadata","tags":[],"items":[{"id":"drw-tb-1","text":"Part number in the title block matches the PDM/PLM record and the file name","hint":"Compare the title block, model properties and PDM record. Mismatches cause wrong parts to be quoted, ordered or built.","tags":[],"severity":"critical"},{"id":"drw-tb-2","text":"Revision letter in the title block matches the latest entry in the revision table","hint":"A title block that disagrees with the revision table makes the revision ambiguous at the supplier.","tags":[],"severity":"major"},{"id":"drw-tb-3","text":"Material is specified fully, with grade, standard or manufacturer and trade name","hint":"\"Aluminum\" or \"ABS\" is not a specification. Give alloy and temper, or resin grade and supplier, plus any approved equivalents.","tags":[],"severity":"critical"},{"id":"drw-tb-4","text":"Finish is specified (anodize type and color, plating, paint, texture) or stated as none","hint":"Reference the finish spec or Materials & Finishes callout. A blank finish field is often read as \"as machined\" or \"as molded\".","tags":[],"severity":"major"},{"id":"drw-tb-5","text":"Units are stated on the drawing (mm by default) and used consistently","hint":"Dual dimensions, if any, show the primary unit clearly. Mixed units on one sheet are a recipe for scrap.","tags":[],"severity":"major"},{"id":"drw-tb-6","text":"Projection angle (first or third angle) is stated with the standard symbol","hint":"Suppliers in different regions default to different projection angles. A missing symbol can mirror a view interpretation.","tags":[],"severity":"major"},{"id":"drw-tb-7","text":"Drawing scale is stated and views not at the sheet scale are labeled with their own scale","hint":"Detail and section views often use a different scale. Remind readers not to scale the drawing.","tags":[],"severity":"minor"},{"id":"drw-tb-8","text":"Sheet number and total sheet count are shown on every sheet","hint":"\"Sheet 2 of 3\" lets a supplier know a page is missing from the package.","tags":[],"severity":"minor"},{"id":"drw-tb-9","text":"Drawn, checked and approved fields carry names and dates","hint":"An empty checked field means the drawing was not independently checked. Match the names to the PDM approval record.","tags":[],"severity":"minor"},{"id":"drw-tb-10","text":"The general tolerance note or title-block tolerance table is present and matches the chosen tolerance standard","hint":"Confirm the note references the general tolerance standard and class selected during tolerancing (see Tolerancing & GD&T). Leftover template tolerance blocks are a frequent error.","tags":[],"severity":"major"},{"id":"drw-tb-11","text":"Applicable drawing and GD&T standards are stated (e.g. ASME Y14.5 edition or ISO GPS)","hint":"The standard sets how every symbol is interpreted. Use the company template field rather than a free note so it is never omitted.","tags":[],"severity":"major"},{"id":"drw-tb-12","text":"Part mass or weight is shown where the drawing template calls for it","hint":"Use the CAD mass with the correct material density applied. Mass is useful for incoming checks and for BOM rollups.","tags":[],"severity":"minor"}]},{"id":"drw-view","title":"Views & Dimensioning","tags":[],"items":[{"id":"drw-view-1","text":"The drawing has enough views to define every feature without ambiguity","hint":"Check that hidden or internal features appear in at least one view where they can be dimensioned. A feature shown only in an isometric is undefined.","tags":[],"severity":"major"},{"id":"drw-view-2","text":"Section and detail views are provided for internal geometry, small features and complex profiles","hint":"Section through bosses, ribs, grooves and undercuts. Label section lines and views consistently.","tags":[],"severity":"major"},{"id":"drw-view-3","text":"Every feature is fully defined by dimensions, GD&T or a reference to the 3D model","hint":"Review each feature in turn and confirm its size and location are controlled. Missing dimensions get filled in by the supplier's guess.","tags":[],"severity":"critical"},{"id":"drw-view-4","text":"No dimension is duplicated across views or sheets","hint":"Duplicates diverge after the next revision. Use the CAD tool's duplicate dimension check where available, then scan by eye.","tags":[],"severity":"minor"},{"id":"drw-view-5","text":"Dimensions originate from datum features rather than chaining from edge to edge","hint":"Chained dimensions accumulate tolerance. Baseline or ordinate dimensioning from the datum frame matches how the part is inspected.","tags":[],"severity":"major"},{"id":"drw-view-6","text":"Reference dimensions are marked as reference and are not used to control features","hint":"Use parentheses or REF per the stated standard. An unmarked redundant dimension creates a conflict.","tags":[],"severity":"minor"},{"id":"drw-view-7","text":"Dimensions are driven from the model and not overridden with manually typed values","hint":"Search for overridden or detached dimensions in the CAD drawing. A typed value that disagrees with the model is a silent error.","tags":[],"severity":"critical"},{"id":"drw-view-8","text":"When the 3D model is the master definition, the drawing states this and identifies the governing model and revision","hint":"Model-based definition (e.g. per ASME Y14.41) needs a note naming the model file, revision and what the drawing still controls. Otherwise the supplier cannot tell which governs when they disagree.","tags":[],"severity":"major"},{"id":"drw-view-9","text":"Features controlled only by the model are identified and given a general profile tolerance","hint":"A note such as \"all untoleranced surfaces profile X to datums A|B|C per model\" closes the gap. Without it, model-only geometry has no tolerance.","tags":[],"severity":"major"},{"id":"drw-view-10","text":"Text, dimensions and symbols are legible at the printed sheet size and do not overlap geometry","hint":"Print or view at 100% on the intended sheet size. Overlapping dimensions are misread.","tags":[],"severity":"minor"},{"id":"drw-view-11","text":"Threads, holes and countersinks use standard hole callouts rather than manual notes","hint":"Use the CAD hole callout so depth, thread class and countersink angle stay linked to the feature.","tags":[],"severity":"minor"}]},{"id":"drw-note","title":"General Notes","tags":[],"items":[{"id":"drw-note-1","text":"Edge break and deburr requirements are stated (e.g. per ISO 13715 or a general edge note)","hint":"Sharp edges cut assemblers and users; uncontrolled breaks affect seals and fits. State exceptions where sharp edges are functional.","tags":[],"severity":"major"},{"id":"drw-note-2","text":"Surface finish (Ra) is specified on functional surfaces and as a general value elsewhere","hint":"Call out Ra on sealing faces, bearing bores and sliding surfaces using the stated standard's symbol. Leave non-functional surfaces to the general note to avoid cost.","tags":[],"severity":"major"},{"id":"drw-note-3","text":"Heat treatment, hardness and case depth are specified where required, with the test method","hint":"Give the hardness scale and location of measurement. State whether dimensions apply before or after heat treatment.","tags":[],"severity":"major"},{"id":"drw-note-4","text":"A cosmetic specification is referenced for customer-facing surfaces","hint":"Reference the cosmetic spec that defines surface classes, allowable defects, viewing conditions and SPI or VDI 3400 finish where applicable.","tags":["cosmetic"],"severity":"major"},{"id":"drw-note-5","text":"Part marking is specified: content, location, method and size","hint":"Include part number, revision, cavity number, date code, material ID or regulatory marks as required. Mark location must not land on a cosmetic or functional surface.","tags":[],"severity":"minor"},{"id":"drw-note-6","text":"RoHS, REACH and other substance compliance requirements are stated on the drawing or in a referenced spec","hint":"Use a standard compliance note so suppliers certify every lot. Missing notes lead to non-compliant platings and coatings.","tags":["regulatory"],"severity":"major"},{"id":"drw-note-7","text":"Cleanliness, biocompatibility or particulate requirements are stated for patient- or fluid-contacting parts","hint":"Reference the cleaning spec or ISO 10993 evaluation basis for patient-contact parts. Suppliers will not apply cleaning steps that are not specified.","tags":["medical"],"severity":"major"},{"id":"drw-note-8","text":"Notes are numbered, current and free of template leftovers that do not apply","hint":"Delete inherited notes that conflict with this part (wrong material, wrong process). Flag-note symbols on the views should match the note numbers.","tags":[],"severity":"minor"},{"id":"drw-note-9","text":"Packaging and handling requirements are stated where the part is fragile or cosmetic","hint":"Specify protective film, separators or trays so cosmetic and precision parts arrive undamaged.","tags":[],"severity":"minor"}]},{"id":"drw-im","title":"Injection-Molded Part Drawings","tags":["injection-molded"],"items":[{"id":"drw-im-1","text":"Resin is specified by manufacturer, grade and color code, with any approved alternates","hint":"Name the resin grade and color masterbatch or pre-color code. Generic resin names let the molder substitute.","tags":[],"severity":"critical"},{"id":"drw-im-2","text":"Surface texture or polish is specified by standard (SPI, VDI 3400 or texture supplier code) for each surface","hint":"Show texture zones on a view and give the code per zone. Texture affects draft, so confirm draft supports the texture.","tags":[],"severity":"major"},{"id":"drw-im-3","text":"Gate location and allowable gate vestige are shown or restricted","hint":"Mark permitted gate zones and maximum vestige height. Leaving it open lets the toolmaker gate on a Class A surface.","tags":[],"severity":"major"},{"id":"drw-im-4","text":"Ejector pin locations and allowable witness marks are restricted on cosmetic and functional surfaces","hint":"Show keep-out zones for ejectors and state allowable witness depth or protrusion.","tags":[],"severity":"major"},{"id":"drw-im-5","text":"Parting line location and allowable mismatch and flash are specified","hint":"Show the parting line and state the maximum flash and step per the molder's capability. Flash on a sealing surface causes leaks.","tags":[],"severity":"major"},{"id":"drw-im-6","text":"Sink and void acceptance criteria are stated for surfaces over ribs and bosses","hint":"Reference the cosmetic spec or give limits for sink on visible faces opposite ribs and bosses.","tags":[],"severity":"minor"},{"id":"drw-im-7","text":"Cavity identification and date code inserts are specified on the drawing","hint":"Cavity ID lets quality trace defects to a specific cavity; date wheels support lot traceability.","tags":["high-volume"],"severity":"minor"}]},{"id":"drw-sm","title":"Sheet-Metal Part Drawings","tags":["sheet-metal"],"items":[{"id":"drw-sm-1","text":"A flat pattern view is included with overall blank size","hint":"The flat pattern confirms the supplier's unfold matches yours. Note that the flat is for reference and the formed part governs, unless agreed otherwise.","tags":[],"severity":"major"},{"id":"drw-sm-2","text":"Bend notes give direction, angle and inside radius for every bend","hint":"Include bend up/down and radius in a bend table. Inside radius should match the supplier's tooling.","tags":[],"severity":"major"},{"id":"drw-sm-3","text":"Material thickness, grade and grain or rolling direction (where it matters) are specified","hint":"Grain direction affects cracking on tight bends in some alloys. State it when bends are near the material's minimum radius.","tags":[],"severity":"major"},{"id":"drw-sm-4","text":"Hardware inserts (PEM-style nuts, studs, standoffs) are called out with supplier part numbers","hint":"Give the hardware manufacturer's part number and the installation side. Generic \"M3 nut\" callouts get substituted.","tags":[],"severity":"major"},{"id":"drw-sm-5","text":"Dimensions to formed features are given from the side that is controlled (inside or outside of bend)","hint":"Indicate inside versus outside mold line dimensions. Ambiguity here shifts features by a material thickness.","tags":[],"severity":"major"},{"id":"drw-sm-6","text":"Burr direction is specified where it affects safety, assembly or cosmetic surfaces","hint":"Punching leaves a burr on one side. Specify burr side away from users, cables and seals.","tags":[],"severity":"minor"}]},{"id":"drw-mc","title":"Machined Part Drawings","tags":["machined"],"items":[{"id":"drw-mc-1","text":"Threads are specified with size, pitch, class and depth (e.g. M5x0.8-6H, full thread depth)","hint":"Specify thread class per ISO 965 or the applicable standard and the minimum full-thread depth. Unspecified depth leaves the tap-drill depth to the machinist.","tags":[],"severity":"major"},{"id":"drw-mc-2","text":"Thread inserts (helical coil, key-locking) are specified with manufacturer part numbers and tapped hole spec","hint":"Give the insert part number and the insert manufacturer's tapped-hole size. The hole spec differs from a standard thread.","tags":[],"severity":"minor"},{"id":"drw-mc-3","text":"Internal corner radii are compatible with standard cutters or are explicitly called out","hint":"Sharp inside corners cannot be milled. Show the maximum allowable radius so the shop can choose the tool.","tags":[],"severity":"major"},{"id":"drw-mc-4","text":"Surface finishes on machined functional surfaces are specified separately from the general finish","hint":"Call out Ra on sealing, bearing and sliding surfaces. Do not over-specify a fine general finish.","tags":[],"severity":"minor"},{"id":"drw-mc-5","text":"Finish masking requirements are shown for threads, bores and grounding points","hint":"Mark areas to be masked from anodize, plating or paint. Unmasked grounding pads break electrical bonding.","tags":[],"severity":"major"}]},{"id":"drw-cst","title":"Cast Part Drawings","tags":["cast"],"items":[{"id":"drw-cst-1","text":"Machining stock is shown on as-cast surfaces that will be machined","hint":"Provide a casting drawing with stock allowance, or a combined drawing that distinguishes as-cast and machined dimensions.","tags":[],"severity":"major"},{"id":"drw-cst-2","text":"As-cast tolerances reference a casting tolerance standard or the foundry's agreed grade","hint":"ISO 8062 grades or a supplier-agreed table. Do not apply machining tolerances to as-cast features.","tags":[],"severity":"major"},{"id":"drw-cst-3","text":"Porosity acceptance class and inspection method are specified for critical zones","hint":"Reference the agreed radiographic or sectioning standard and zone the drawing where porosity matters (sealing faces, threads, high-stress areas).","tags":[],"severity":"major"},{"id":"drw-cst-4","text":"The as-cast part and the machined part are separate, linked definitions (part numbers or drawing views)","hint":"Foundries are quoted and inspected on the as-cast condition, machinists on the finished part. Linking both on one ambiguous view causes disputes over which dimensions the foundry owns.","tags":[],"severity":"major"},{"id":"drw-cst-5","text":"Impregnation, heat treatment or stress relief requirements are stated where needed","hint":"Vacuum impregnation seals porosity for pressure-tight castings; state it with the spec if required.","tags":[],"severity":"minor"}]},{"id":"drw-asm","title":"Assembly Drawings & BOM","tags":[],"items":[{"id":"drw-asm-1","text":"Every balloon on the assembly drawing matches an item in the BOM, and every BOM item is ballooned","hint":"Cross-check the balloon list with the BOM table. Orphan balloons or missing items cause build errors.","tags":[],"severity":"major"},{"id":"drw-asm-2","text":"BOM quantities and units of measure are correct for every line, including bulk items","hint":"Check quantities against the model and give units for adhesives, tapes and cables (mm, g, mL). Bulk items without units cause shortages.","tags":[],"severity":"major"},{"id":"drw-asm-3","text":"Purchased parts list the manufacturer and manufacturer part number","hint":"A description alone is not orderable. Include the exact catalog number, including any variant suffixes.","tags":[],"severity":"major"},{"id":"drw-asm-4","text":"Approved alternates for purchased parts are listed or explicitly forbidden","hint":"List qualified alternates or state \"no substitution\". Unlisted substitutes may differ in critical dimensions or materials.","tags":[],"severity":"minor"},{"id":"drw-asm-5","text":"Fastener torque values are specified for every threaded joint","hint":"Give torque in N·m with tolerance and the tool or method. Torque values should come from the joint analysis (see Assembly, Fastening & DFA).","tags":[],"severity":"major"},{"id":"drw-asm-6","text":"Adhesive and thread-locker callouts give product, application area and cure requirements","hint":"Name the product and grade, show where to apply it and state cure time or conditions before handling.","tags":[],"severity":"major"},{"id":"drw-asm-7","text":"Assembly sequence notes are given where order matters","hint":"Call out steps that cannot be reversed (adhesive, press fits, heat-staking) and any orientation requirements.","tags":[],"severity":"minor"},{"id":"drw-asm-8","text":"Assembly-level dimensions and checks are shown for critical interfaces","hint":"Include the final gaps, heights or alignments the line must verify, with tolerances from the stack-ups.","tags":[],"severity":"major"},{"id":"drw-asm-9","text":"Lubrication, grease or potting callouts are specified with product and quantity","hint":"\"Lubricate\" without product or amount gets interpreted differently by each operator.","tags":["moving-parts"],"severity":"minor"},{"id":"drw-asm-10","text":"Label and marking placements are shown on the assembly drawing","hint":"Show product label, serial and regulatory mark locations with orientation.","tags":["regulatory"],"severity":"minor"}]},{"id":"drw-rev","title":"Revision Control & Release","tags":[],"items":[{"id":"drw-rev-1","text":"The revision table lists each revision with a description of the change","hint":"Descriptions such as \"updated\" are useless. Name what changed and where (zone or view).","tags":[],"severity":"minor"},{"id":"drw-rev-2","text":"Each revision references its ECO/ECN number","hint":"Traceability to the change order connects the drawing to the reason, approval and affected parts.","tags":[],"severity":"minor"},{"id":"drw-rev-3","text":"Model and drawing revisions match in the PDM/PLM system","hint":"Check that the drawing references the released model revision. A drawing pointing to a work-in-progress model can carry unapproved geometry.","tags":[],"severity":"critical"},{"id":"drw-rev-4","text":"The drawing is released through PDM/PLM, not sent from a local or working file","hint":"Released state locks the file and records approvals. Files emailed from a workspace bypass the release process.","tags":[],"severity":"major"},{"id":"drw-rev-5","text":"Changed features are identified on the drawing (revision clouds or triangles) for the current revision","hint":"Clouding lets suppliers and checkers find the change quickly. Clear old clouds when the next revision starts.","tags":[],"severity":"minor"},{"id":"drw-rev-6","text":"STEP and PDF exports are generated from the released revision and stored with it","hint":"Regenerate exports at release rather than reusing earlier files. Check the STEP opens and the PDF revision matches.","tags":[],"severity":"major"},{"id":"drw-rev-7","text":"Native CAD files are archived with the release","hint":"Archive the native files and references (or a Pack and Go) so the design can be reproduced later.","tags":[],"severity":"minor"},{"id":"drw-rev-8","text":"Suppliers receive controlled copies and superseded revisions are withdrawn","hint":"Send from PDM/PLM or a controlled portal and confirm the supplier acknowledges the new revision. Superseded copies at the supplier are a common cause of wrong parts.","tags":[],"severity":"major"},{"id":"drw-rev-9","text":"Interchangeability is assessed for each revision and part number changed when form, fit or function changes","hint":"If old and new parts are not interchangeable, the part number should change. Bumping only the revision mixes incompatible parts in stock.","tags":[],"severity":"major"},{"id":"drw-rev-10","text":"Where-used is checked for every changed part so affected assemblies and drawings are updated","hint":"Run the PDM where-used report. Shared parts often affect other products.","tags":[],"severity":"major"}]},{"id":"drw-chk","title":"Checking","tags":[],"items":[{"id":"drw-chk-1","text":"Each drawing is checked by someone other than the author","hint":"An independent checker catches errors the author cannot see. Record the checker in the title block and PDM.","tags":[],"severity":"major"},{"id":"drw-chk-2","text":"The drawing checklist was completed and stored with the release","hint":"Store the completed checklist in PDM with the release so later reviews can see what was checked.","tags":[],"severity":"minor"},{"id":"drw-chk-3","text":"All checker redlines are closed or dispositioned before release","hint":"Each redline is either incorporated or answered with a reason. Open redlines at release are deferred errors.","tags":[],"severity":"major"},{"id":"drw-chk-4","text":"The checker compared the drawing against the model, stack-ups and CTF list","hint":"Check that CTF dimensions carry the tolerances the stack-ups assume. The drawing and stack-up analysis are often out of sync.","tags":[],"severity":"major"},{"id":"drw-chk-5","text":"A print-out or PDF review was done at final sheet size","hint":"Errors hidden by on-screen zoom (overlapping text, missing leaders) show up on a full-size print.","tags":[],"severity":"minor"}]},{"id":"drw-sup","title":"Supplier Package","tags":[],"items":[{"id":"drw-sup-1","text":"The RFQ package contains drawings, 3D models, specifications and referenced documents at matching revisions","hint":"Send one zip or portal package with a document list. Missing referenced specs (cosmetic, finish, packaging) are the usual gap.","tags":[],"severity":"major"},{"id":"drw-sup-2","text":"Annual volumes, lot sizes and ramp schedule are stated in the RFQ","hint":"Volume drives tooling choice (cavity count, soft versus hard tooling) and price. Quotes without volumes cannot be compared.","tags":[],"severity":"major"},{"id":"drw-sup-3","text":"Inspection requirements and the critical dimensions list are included in the package","hint":"State which dimensions need measurement on every lot, SPC or certificates. Suppliers quote inspection cost from this.","tags":[],"severity":"major"},{"id":"drw-sup-4","text":"First article inspection (FAI) requirements are specified: quantity, report format and full-dimension scope","hint":"State the FAI format (e.g. AS9102-style or PPAP if required), number of parts per cavity and which documents are returned.","tags":[],"severity":"major"},{"id":"drw-sup-5","text":"Material certifications and compliance declarations required from the supplier are listed","hint":"Specify mill certs, resin lot certificates, RoHS/REACH declarations and conflict-minerals statements as required.","tags":[],"severity":"minor"},{"id":"drw-sup-6","text":"Tooling ownership, tool life and maintenance expectations are stated for production tooling","hint":"Agree who owns the tool, expected shot life and who pays for repair. Leaving this open causes disputes at transfer.","tags":["high-volume"],"severity":"minor"},{"id":"drw-sup-7","text":"Supplier questions and deviations from the RFQ are logged and answered in writing","hint":"Track supplier DFM feedback and agreed deviations, and fold accepted ones into the next drawing revision.","tags":[],"severity":"minor"}]}]},{"id":"validation","title":"Prototype, Test & Validation","short":"Validation","version":1,"description":"Review of prototype planning, first article inspection, fit and assembly trials, design verification planning, mechanical, environmental, ingress, thermal and battery testing, regulatory pre-compliance, pilot builds and test reporting.","sections":[{"id":"val-plan","title":"Prototype Plan","tags":[],"items":[{"id":"val-plan-1","text":"Each prototype build has written questions it must answer","hint":"Write the purpose per build (e.g. ergonomics, mechanism feel, drop survival) before ordering parts; builds without questions waste money.","tags":[],"severity":"major"},{"id":"val-plan-2","text":"Looks-like and works-like prototypes are distinguished and their limitations documented","hint":"A looks-like model can't validate strength, and a works-like rig can't validate ergonomics; state what each can and can't show.","tags":[],"severity":"minor"},{"id":"val-plan-3","text":"EVT, DVT and PVT entry and exit criteria are defined","hint":"E.g. DVT requires production-intent design and tooled parts; PVT requires production tooling, process and line. Record which criteria were waived.","tags":[],"severity":"major"},{"id":"val-plan-4","text":"Process fidelity of prototype parts vs. production is recorded for each test","hint":"A printed or machined part behaves differently from a molded one (strength, anisotropy, knit lines, residual stress). Note which results must be repeated on tooled parts.","tags":[],"severity":"major"},{"id":"val-plan-5","text":"Additive prototypes use process and orientation appropriate to the question being answered","hint":"Build orientation drives strength in FDM, SLS and MJF parts; record orientation and material on the build sheet.","tags":["additive"],"severity":"minor"},{"id":"val-plan-6","text":"Prototype quantities cover test sample sizes plus spares for failures and rework","hint":"Count samples per test from the verification plan and add margin; running out of samples mid-DVT stalls the schedule.","tags":[],"severity":"major"},{"id":"val-plan-7","text":"Prototype builds are tracked with part revision, material and supplier per unit","hint":"Serialize units and keep a build record so test results can be tied to the exact design revision.","tags":[],"severity":"minor"},{"id":"val-plan-8","text":"Build schedule aligns with test lab bookings and tooling milestones","hint":"Lab slots for regulatory and environmental tests often book weeks ahead.","tags":[],"severity":"minor"}]},{"id":"val-fai","title":"First Article & Incoming Inspection","tags":[],"items":[{"id":"val-fai-1","text":"First article inspection report covers every dimension and note on the drawing","hint":"Ballooned drawing with each characteristic measured and recorded against tolerance. Missing characteristics hide out-of-spec features.","tags":[],"severity":"major"},{"id":"val-fai-2","text":"Critical and key dimensions are measured on a CMM or equivalent calibrated method","hint":"Hand calipers are not adequate for tight-tolerance or datum-referenced GD&T features. Confirm the datum setup matches the drawing.","tags":[],"severity":"major"},{"id":"val-fai-3","text":"Measurement datums and fixturing match the drawing datum scheme","hint":"Measuring from the wrong datum gives false passes or failures; review the CMM program setup with the supplier.","tags":[],"severity":"major"},{"id":"val-fai-4","text":"Material certifications are received and match the drawing callout","hint":"Check grade, temper, resin grade and color code on the cert. Substituted materials are a common source of failure.","tags":[],"severity":"major"},{"id":"val-fai-5","text":"Finish, plating and coating verification is recorded (thickness, adhesion, color)","hint":"Coating thickness gauge, tape adhesion test and color comparison against the approved standard.","tags":[],"severity":"minor"},{"id":"val-fai-6","text":"Out-of-spec features are dispositioned with a documented decision","hint":"Use-as-is, rework or reject, with engineering rationale. Undocumented deviations become the de facto specification.","tags":[],"severity":"major"},{"id":"val-fai-7","text":"Cosmetic parts are inspected under the agreed lighting and viewing conditions","hint":"Compare against approved boundary samples and the cosmetic specification.","tags":["cosmetic"],"severity":"minor"},{"id":"val-fai-8","text":"Incoming inspection plan for production defines sampling and characteristics for each part","hint":"Base sampling on part risk and supplier history; focus on critical dimensions.","tags":["high-volume"],"severity":"minor"}]},{"id":"val-fit","title":"Fit, Function & Assembly Trials","tags":[],"items":[{"id":"val-fit-1","text":"Every part assembles to its mating parts without forcing, trimming or rework","hint":"Record any part that needed modification during the build; each is a design or tolerance issue to close.","tags":[],"severity":"critical"},{"id":"val-fit-2","text":"Assembly trial uses the documented assembly sequence and specified tools","hint":"Builds by engineers who improvise hide problems operators will hit. Use the draft work instructions.","tags":[],"severity":"major"},{"id":"val-fit-3","text":"Fasteners reach specified torque without stripping, cracking bosses or thread jumping","hint":"Torque-to-strip and drive torque checks on production-material bosses; check margin between drive and strip torque.","tags":[],"severity":"major"},{"id":"val-fit-4","text":"Gaps, flushness and alignment between visible parts are measured against targets","hint":"Use feeler gauges or a gap/flush gauge at defined points; record on a map of the product.","tags":["cosmetic"],"severity":"minor"},{"id":"val-fit-5","text":"Cables and flex circuits route without pinching, stretching or interference","hint":"Inspect each unit opened after assembly and after test; look for witness marks on cables.","tags":["electronics"],"severity":"major"},{"id":"val-fit-6","text":"Moving parts operate through full travel with no binding across the tolerance range","hint":"Test units built from parts near both tolerance extremes where possible, not only nominal parts.","tags":["moving-parts"],"severity":"major"},{"id":"val-fit-7","text":"Disassembly and reassembly for service is demonstrated without damage","hint":"Disassemble at least one unit per the service procedure and rebuild it; check snaps and seals still function.","tags":[],"severity":"minor"},{"id":"val-fit-8","text":"Assembly time is measured and compared against the cost model","hint":"Time each operation during the build; large deviations mean the cost model or the design needs updating.","tags":["high-volume"],"severity":"minor"}]},{"id":"val-dvp","title":"Design Verification Test Plan","tags":[],"items":[{"id":"val-dvp-1","text":"Every requirement has at least one verification test, analysis or inspection in the plan","hint":"Cross-check the requirements matrix against the test plan; list any requirement verified by analysis only and why.","tags":[],"severity":"critical"},{"id":"val-dvp-2","text":"Sample sizes are justified statistically or by a referenced standard","hint":"State the confidence and reliability basis or the standard that sets the sample size. \"Three units\" without rationale won't survive an audit.","tags":[],"severity":"major"},{"id":"val-dvp-3","text":"Pass/fail criteria are written and approved before testing begins","hint":"Criteria defined after seeing results are not verification. Include what functional checks are done after each test.","tags":[],"severity":"critical"},{"id":"val-dvp-4","text":"Test units are production-intent in design, material and process, or the deviation is documented","hint":"Record each difference and justify why it doesn't affect the result.","tags":[],"severity":"major"},{"id":"val-dvp-5","text":"Test sequence is defined where tests are performed on the same units","hint":"E.g. thermal cycling before drop reflects aging. Sequential testing can reveal failures that single tests miss.","tags":[],"severity":"minor"},{"id":"val-dvp-6","text":"Test procedures specify fixtures, equipment, settings and measurement methods","hint":"Someone else should be able to repeat the test from the procedure alone.","tags":[],"severity":"minor"},{"id":"val-dvp-7","text":"Test equipment is calibrated and calibration status is recorded","hint":"Record equipment ID and calibration due date in each test report.","tags":[],"severity":"minor"},{"id":"val-dvp-8","text":"Design verification plan is traceable to the design FMEA and risk controls","hint":"High-severity failure modes and risk controls each need a verification activity.","tags":["medical"],"severity":"major"}]},{"id":"val-mech","title":"Mechanical Testing","tags":[],"items":[{"id":"val-mech-1","text":"Drop testing is performed per the specified height, surface, orientations and count","hint":"Inspect for cracks, displaced parts and loss of function after each drop; a high-speed camera helps diagnose failures.","tags":["handheld"],"severity":"major"},{"id":"val-mech-2","text":"Transit drop and vibration testing is performed in the shipping packaging","hint":"Use the defined transport test profile with production packaging.","tags":[],"severity":"major"},{"id":"val-mech-3","text":"Vibration testing is run to the specified profile, with resonance search where needed","hint":"Check for loosened fasteners, fretting, connector unseating and cracked brackets afterward.","tags":[],"severity":"major"},{"id":"val-mech-4","text":"Mechanical shock testing is run to the specified pulse and axes","hint":"Inspect mounts, heavy components and latches after test.","tags":[],"severity":"minor"},{"id":"val-mech-5","text":"Impact testing is performed on exposed surfaces, windows and displays","hint":"Apply the specified impact energy at the weakest location identified by analysis or inspection.","tags":[],"severity":"minor"},{"id":"val-mech-6","text":"Mechanisms are life-tested to the duty-cycle count with margin","hint":"Run hinges, slides, latches and gears to rated cycles plus a margin; measure force, play and wear at intervals.","tags":["moving-parts"],"severity":"major"},{"id":"val-mech-7","text":"Button and switch actuation is cycle-tested with force and travel measured before and after","hint":"Use a cycle tester at the specified actuation force; check for feel change, sticking and cosmetic wear.","tags":[],"severity":"minor"},{"id":"val-mech-8","text":"Hinge cycle testing measures torque and play retention over life","hint":"Record hinge torque at intervals; loss of friction torque is a common complaint.","tags":["moving-parts"],"severity":"minor"},{"id":"val-mech-9","text":"Snap fits are cycle-tested for the number of assembly/disassembly cycles required","hint":"Measure retention force after cycling; check for stress whitening and cracks.","tags":["injection-molded"],"severity":"minor"},{"id":"val-mech-10","text":"Threaded insert torque-out and pull-out strength is tested on production-material parts","hint":"Heat-set and molded-in inserts depend on the boss design and process; test on tooled parts.","tags":[],"severity":"major"},{"id":"val-mech-11","text":"Fastener joint preload or clamp retention is checked after thermal and vibration exposure","hint":"Plastic creep and relaxation lose preload; check prevailing torque after environmental testing.","tags":[],"severity":"minor"},{"id":"val-mech-12","text":"Cable and connector strain relief is pull-tested to the specified load","hint":"Apply load in the worst direction and confirm no electrical or mechanical damage.","tags":["electronics"],"severity":"minor"},{"id":"val-mech-13","text":"Static and user-load tests confirm no permanent deformation or failure at the specified load","hint":"Apply loads per the requirements; measure deflection and set after load removal.","tags":["structural"],"severity":"major"},{"id":"val-mech-14","text":"Safety-critical load paths are tested to the required safety factor","hint":"Test to failure where feasible to know the actual margin, not just pass/fail.","tags":["structural"],"severity":"critical"}]},{"id":"val-envt","title":"Environmental Testing","tags":[],"items":[{"id":"val-envt-1","text":"Thermal cycling is performed over the specified range and number of cycles","hint":"Check for cracking, warping, loosening, seal failure and adhesive bond failure after cycling.","tags":[],"severity":"major"},{"id":"val-envt-2","text":"High-temperature storage and operation tests show no deformation or creep beyond spec","hint":"Check fit and gaps after high-temperature exposure; plastic parts under load may creep.","tags":[],"severity":"major"},{"id":"val-envt-3","text":"Low-temperature tests confirm mechanisms, snaps and seals still function","hint":"Many plastics and elastomers become brittle or stiff at low temperature; repeat functional tests cold.","tags":[],"severity":"major"},{"id":"val-envt-4","text":"Humidity or damp heat exposure shows no corrosion, delamination or dimensional problems","hint":"Nylons absorb moisture and change dimension; check fits after exposure.","tags":[],"severity":"minor"},{"id":"val-envt-5","text":"UV exposure testing confirms acceptable color change and property retention","hint":"Run accelerated weathering per the spec; measure color shift and impact strength.","tags":["outdoor"],"severity":"major"},{"id":"val-envt-6","text":"Salt fog or corrosion testing confirms coating and fastener performance","hint":"Inspect plated parts, fasteners and dissimilar-metal joints for corrosion after test.","tags":["outdoor"],"severity":"major"},{"id":"val-envt-7","text":"Chemical resistance is tested with the specified cleaning agents and disinfectants","hint":"Wipe or soak per the cleaning instructions for the required number of cycles, ideally on parts under stress; look for crazing and cracking.","tags":["medical"],"severity":"major"},{"id":"val-envt-8","text":"Chemical exposure testing covers sweat, sunscreen, oils or other substances in the requirements","hint":"Test with the substances listed in the requirements; stressed plastics can crack under exposure.","tags":[],"severity":"minor"}]},{"id":"val-ip","title":"Ingress Testing","tags":["sealed-ip"],"items":[{"id":"val-ip-1","text":"Ingress tests are performed to the target IP rating per IEC 60529","hint":"Use an accredited lab or the defined in-house setup; inspect internally for water and dust after testing.","tags":[],"severity":"critical"},{"id":"val-ip-2","text":"Ingress tests are repeated after environmental and mechanical stress","hint":"Seals often pass when new and fail after thermal cycling, drop or vibration.","tags":[],"severity":"major"},{"id":"val-ip-3","text":"Ingress tests use units built from parts at tolerance extremes","hint":"Seal compression varies with stack-up; test the worst case.","tags":[],"severity":"major"},{"id":"val-ip-4","text":"Ingress testing is repeated after service disassembly and reassembly","hint":"Gaskets may take compression set; check resealing.","tags":[],"severity":"minor"},{"id":"val-ip-5","text":"Production leak test method and limits are correlated with IP test results","hint":"If an air-decay or pressure test will be used in production, correlate its threshold to actual ingress failures.","tags":["high-volume"],"severity":"major"},{"id":"val-ip-6","text":"Pressure vents and membranes are verified for function and sealing","hint":"Check venting performance and water ingress through vent assemblies.","tags":[],"severity":"minor"}]},{"id":"val-thm","title":"Thermal Validation","tags":["thermal"],"items":[{"id":"val-thm-1","text":"Component temperatures are measured at worst-case ambient and power","hint":"Use thermocouples on critical components and compare to limits and analysis predictions.","tags":[],"severity":"critical"},{"id":"val-thm-2","text":"Touch temperatures of accessible surfaces are measured against the requirement","hint":"Measure surfaces the user can touch during and after operation.","tags":[],"severity":"major"},{"id":"val-thm-3","text":"Thermal measurements are compared with simulation and the model is updated if needed","hint":"Large deviation means the analysis model or assumptions were wrong; see Thermal & Structural Analysis.","tags":[],"severity":"minor"},{"id":"val-thm-4","text":"Fans and active cooling are tested for blocked-vent and failure conditions","hint":"Check temperatures with blocked inlets or a failed fan and verify safe behavior.","tags":[],"severity":"major"},{"id":"val-thm-5","text":"Thermal interface materials are inspected for contact and coverage after assembly","hint":"Disassemble a unit and check the pad or paste imprint.","tags":[],"severity":"minor"}]},{"id":"val-bat","title":"Battery Safety Coordination","tags":["battery-pack"],"items":[{"id":"val-bat-1","text":"Battery abuse and safety test plan is agreed with the cell supplier and test lab","hint":"Coordinate crush, impact, short circuit and overcharge testing responsibility; do not run abuse tests without suitable facilities.","tags":[],"severity":"critical"},{"id":"val-bat-2","text":"Battery compartment is inspected for cell damage after drop and vibration testing","hint":"Check for cell dents, swelling, displaced cells or tab damage.","tags":[],"severity":"critical"},{"id":"val-bat-3","text":"Cell swelling allowance is verified with aged or swollen cells","hint":"Measure cell thickness at end-of-life and confirm housing doesn't load the cell.","tags":[],"severity":"major"},{"id":"val-bat-4","text":"Transport test samples are scheduled for battery shipping certification","hint":"Sample and lead time requirements must be in the plan.","tags":[],"severity":"major"},{"id":"val-bat-5","text":"Battery temperature during charging and operation stays within the cell supplier's limits","hint":"Measure cell surface temperature during worst-case charge and operation.","tags":[],"severity":"major"}]},{"id":"val-reg","title":"Regulatory Pre-Compliance & Lab Booking","tags":[],"items":[{"id":"val-reg-1","text":"Pre-compliance testing is done for the mechanical requirements of the safety standard","hint":"Run enclosure strength, impact, stability and accessibility checks in-house before formal testing.","tags":["regulatory"],"severity":"major"},{"id":"val-reg-2","text":"Certification test lab is booked and sample requirements are confirmed","hint":"Labs specify sample quantity, configuration and documentation; book early.","tags":["regulatory"],"severity":"major"},{"id":"val-reg-3","text":"Flammability rating of plastic parts is confirmed by material certificates or listings","hint":"Check UL 94 rating at the actual wall thickness and color used.","tags":["regulatory"],"severity":"major"},{"id":"val-reg-4","text":"Biocompatibility evaluation per ISO 10993 is planned with an accredited lab","hint":"Use final materials, colorants and processing; test samples must be representative of production.","tags":["medical","wearable"],"severity":"critical"},{"id":"val-reg-5","text":"Samples for biocompatibility testing are production-representative, including cleaning and sterilization","hint":"Process changes after testing can invalidate results.","tags":["medical","wearable"],"severity":"major"},{"id":"val-reg-6","text":"Cleaning and disinfection validation is planned for reusable devices","hint":"Validate cleaning instructions with the specified agents and cycle count.","tags":["medical"],"severity":"major"},{"id":"val-reg-7","text":"Regulatory test results are tracked and nonconformities are fed back into design changes","hint":"Keep a log of each finding and its resolution.","tags":["regulatory"],"severity":"minor"}]},{"id":"val-pvt","title":"Pilot & PVT","tags":[],"items":[{"id":"val-pvt-1","text":"T1 tool samples are reviewed against drawings and a tool correction list is issued","hint":"Review dimensions, cosmetics, sink, flash and warp; record every change request with owner.","tags":["injection-molded"],"severity":"major"},{"id":"val-pvt-2","text":"T2 and later trials close every item on the tool correction list","hint":"Track each correction to closure; unconfirmed fixes resurface at production.","tags":["injection-molded"],"severity":"major"},{"id":"val-pvt-3","text":"Process window for molded parts is documented by the molder","hint":"Record the established process parameters and confirm parts pass at the window limits.","tags":["injection-molded"],"severity":"minor"},{"id":"val-pvt-4","text":"Process capability is measured on critical dimensions","hint":"Rule of thumb: Cpk targets per the customer or quality plan, often 1.33 or higher on critical dimensions.","tags":["high-volume"],"severity":"major"},{"id":"val-pvt-5","text":"Golden samples are approved and stored for each part","hint":"Signed and labeled reference parts for dimensional and cosmetic comparison.","tags":[],"severity":"minor"},{"id":"val-pvt-6","text":"Tooling sign-off is completed with supplier and customer","hint":"Formal tool acceptance after samples meet spec.","tags":["high-volume"],"severity":"major"},{"id":"val-pvt-7","text":"Pilot build yield and defects are recorded and root-caused","hint":"Pareto of defects with corrective actions before ramp.","tags":[],"severity":"major"},{"id":"val-pvt-8","text":"Assembly fixtures and production test equipment are validated","hint":"Gauge R&R on fixtures and testers for critical measurements.","tags":["high-volume"],"severity":"minor"},{"id":"val-pvt-9","text":"Design verification tests are repeated on PVT units where earlier tests used non-production parts","hint":"Confirm production tooling and process do not change results.","tags":[],"severity":"major"}]},{"id":"val-rep","title":"Test Records & Reporting","tags":[],"items":[{"id":"val-rep-1","text":"Every test has a signed report with unit IDs, configuration, procedure revision and results","hint":"Reports without unit and revision traceability can't be reused.","tags":[],"severity":"major"},{"id":"val-rep-2","text":"Every failure is logged with a root cause analysis","hint":"Use 5 Whys, fishbone or failure analysis; \"tested again and passed\" is not root cause.","tags":[],"severity":"critical"},{"id":"val-rep-3","text":"Corrective actions are implemented and verified by retest","hint":"Link each corrective action to the retest that proves it.","tags":[],"severity":"major"},{"id":"val-rep-4","text":"Test deviations and anomalies are recorded in the report, not just failures","hint":"Unexplained behavior is often an early warning.","tags":[],"severity":"minor"},{"id":"val-rep-5","text":"Verification summary links every requirement to its test result and status","hint":"Close the loop on the requirements matrix.","tags":[],"severity":"major"},{"id":"val-rep-6","text":"Test photos and failed samples are kept for reference","hint":"Label and store failed parts for later analysis.","tags":[],"severity":"minor"}]}]}];
